-- GENERATED by `wfj generate` from data/quest/quest-0004.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [4001] = { "Che cosa sta succedendo?", "Parla con ⟦Kharan Mighthammer=Kharan Fortebraccio⟧ e raccogli informazioni sul rapimento della principessa Moira Bronzebeard. Porta quelle informazioni a Thrall, a Orgrimmar.\n\nRicordi che Gor'shak ha detto che Kharan è rinchiuso in una cella qui vicino.", "Finora la mia comunicazione con il nano, Kharan, nella cella dall'altra parte del corridoio è stata limitata. Sono però riuscito a convincerlo che io, anzi, che -noi- non vogliamo fargli del male.\n\nVa' a parlargli e raccogli quante più informazioni puoi sulla principessa e sui suoi carcerieri. Poi riporta quelle informazioni al Capoguerra.\n\nThrall non vuole che la principessa subisca alcun male; ha invece in mente un grande piano, che prevede che lei torni sana e salva a ⟦Ironforge=Forgiardente⟧. Kharan sa già tutto questo... Va'!", "Che cosa ti porta in questo luogo sacro?", "È un'occasione per l'⟦Horde=Orda⟧ di cambiare per sempre il clima politico del nostro mondo dilaniato dalla guerra. Ascolta attentamente, {name}.\n\nFallire questa missione non è un'opzione.", 0x6bdf65cd, 0x16317fb3, 0x09658a85, 0x3f3cae06, 0xf15b0d4a, "....." },
  [4002] = { "I Regni Orientali", "Parla con Thrall se sei pront<o/a> ad accettare la missione che ha in mente.", "Porti informazioni eccellenti, {name}.\n\nCome Capoguerra, è mio dovere fare ciò che è meglio per l'⟦Horde=Orda⟧. Fare in modo che le generazioni che verranno dopo di noi non siano costrette a un'esistenza senza speranza.\n\nL'occasione di plasmare le nostre future alleanze ci è caduta in grembo. Una mossa per aiutare i nani potrebbe rafforzare molto i nostri rapporti nei Regni Orientali. Ecco perché non devi fallire!\n\nSei pront<o/a>?", nil, "Oltre questo punto non si torna indietro, {name}.", 0x59d013ef, 0xe862d33c, 0x9ba00750, nil, 0x751cb339, "...m." },
  [4003] = { "Il salvataggio reale", "Uccidi ⟦Emperor Dagran Thaurissan=Imperatore Dagran Thaurissan⟧ e libera la principessa Moira Bronzebeard dal suo incantesimo malvagio.", "Questo attacco contro i nani ⟦Dark Iron=Ferroscuro⟧, se avrà successo, scuoterà il loro regno da cima a fondo.\n\nLa principessa Bronzebeard è sotto il controllo dell'imperatore Thaurissan. Per liberarla devi uccidere l'imperatore. Ti avverto: il tuo compito è doppiamente pericoloso, perché finché sarà sotto il controllo dell'imperatore la principessa ti attaccherà senza esitare.\n\nNON FARLE DEL MALE!", "<La principessa Moira si rannicchia, terrorizzata.>", "Che cosa hai fatto!", 0xb3f1fa82, 0x0fccab9e, 0xf393d85a, 0x73a34525, 0x30978a13, "....." },
  [4004] = { "⟦Princess Saved=Principessa Salvata⟧?", "Torna da Thrall!", "Hai ucciso mio marito, {race}! Mio figlio verrà al mondo senza un padre.\n\n<La principessa Moira ti punta il dito contro.>\n\nTi assicuro che questo bambino sarà il prossimo sovrano del regno di ⟦Ironforge=Forgiardente⟧. Tu e quelli come te sarete braccati fino alla fine dei giorni per questo torto.\n\n<Pensi che la principessa Moira risenta ancora degli effetti dell'incantesimo di Thaurissan.>\n\nLasciami in pace, {race}. Sono certa che il tuo Capoguerra sarà ansioso di conoscere i frutti della sua intromissione.", nil, "<Thrall è sconcertato dalle informazioni che gli hai riferito.>\n\nUna nuova minaccia incombe all'orizzonte. Man mano che gli anni di Magni volgono al termine, si aprirà la strada perché questo ⟦Dark Iron=Ferroscuro⟧ non ancora nato diventi sovrano di ⟦Ironforge=Forgiardente⟧.\n\nHai compiuto ciò che ti avevo chiesto e per questo sarai ricompensat<o/a>.\n\nOra lasciami, {name}! Devo consultarmi con Sylvanas e Cairne.", 0xe74b8f44, 0x0a323a4f, 0xafcd1b6a, nil, 0x75487453, "...m." },
  [4005] = { nil, "Porta il ⟦Book of Aquor=Libro di Aquor⟧, gli ⟦Silvery Claws=Artigli Argentei⟧ e il ⟦Irontree Heart=Cuore di Troncoferro⟧ a Tanaris.\n\nUsa il ⟦Book of Aquor=Libro di Aquor⟧ per evocare Aquementas.\n\nQuando avrai il totem completo, portalo a J.D. Collie al ⟦Marshal's Refuge=Rifugio dei Grant⟧.", "Porta con te a Tanaris questa sacca di provviste. Raggiungi la ⟦Lost Rigger Cove=Cala del Sartiame⟧ e cerca un cerchio di pietre.\n\nLa penisola più a est è il segreto...\n\nSolo da quel cerchio leggi il libro di Aquor: evocherai l'unica creatura in grado di trasformare gli oggetti che hai raccolto in un totem per combattere ⟦Blazerunner=Fiammafulgida⟧.\n\nAquementas non sarà contento di essere risvegliato ma, ricorda, devi restare nel cerchio perché trasformi gli oggetti.", "Quindi sei <tornato/tornata>, eh? Mmh... Fammi dare un'occhiata, {name}.", "⟦Blazerunner=Fiammafulgida⟧, dici...\n\nSì, so che un potente elementale dimora nel centro carbonizzato del cratere. Ci teniamo tutti alla larga: nessuno è riuscito a penetrare la potente aura che lo circonda. Molti, cercando di affrontarlo, sono stati spinti giù dai sentieri rocciosi fino al terreno sottostante.", 0xa2e8e5f3, 0xc6b51af7, 0x4553998f, 0xa907dd37, 0x25722d4b, "e...." },
  [4021] = { "Contrattacco!", "Porta un ⟦Piece of Krom'zar's Banner=Pezzo dello Stendardo di Krom'zar⟧ a ⟦Regthar Deathgate=Regthar Spargimorte⟧, a ovest del ⟦Crossroads=Crocevia⟧.", "L'⟦Horde=Orda⟧ loda i tuoi successi contro i Kolkar, ma i Kolkar sono furiosi. Mi riferiscono che un contingente di Kolkar è giunto nelle ⟦Barrens=Savane⟧ dalla loro terra, ⟦Desolace=Desolanda⟧, in cerca di vendetta. Secondo l'ultimo rapporto, proprio ora stanno avanzando contro questi bunker, da ovest!\n\nAffronta gli invasori Kolkar e poni fine alla loro minaccia nelle ⟦Barrens=Savane⟧. Uccidili finché non comparirà il loro capo, il signore della guerra Krom'zar. Sconfiggilo e portami un pezzo del suo stendardo come prova.\n\nContiamo su di te, {name}.", "Hai lo stendardo?", "Ce l'hai fatta! Hai sconfitto i Kolkar!\n\nMi assicurerò che Thrall venga a sapere delle tue imprese qui, {name}.\n\nA testa alta. Fai onore a te stess<o/a> e all'⟦Horde=Orda⟧.", 0xa53d08ff, 0x6d88481e, 0xa8ad7e6b, 0x38ed797c, 0x77820849, "....." },
  [4022] = { "Un assaggio di fiamma", "Mostra a Cyrus Therepentous la ⟦Black Dragonflight Molt=Muta dello Stormo Nero⟧ che hai ricevuto da Velarok Windblade.", "Lo Stormo sa del tuo lavoro nella ⟦Searing Gorge=Gorgia Rovente⟧.\n\nMostramela, {race}. La muta, imbecille.", "<Gli occhi di Cyrus diventano due sfere ardenti.>", "<Cyrus esamina la muta.>\n\nHai dimostrato di non essere del tutto inutile, mortale.", 0xfcdfe35e, 0xa5ea3cce, 0xd8a51497, 0xe95b54fc, 0xaec23a34, "....." },
  [4023] = { "Un assaggio di fiamma", "Mostra a Cyrus Therepentous una prova del tuo valore.\n\nHai la sensazione che Cyrus sappia già che non ne sei degn<o/a>.", "Cerchi lo Stormo? Mostrami una prova del tuo valore, mortale.", "<Gli occhi di Cyrus diventano due sfere ardenti.>", "<Cyrus esamina la muta.>\n\nHai dimostrato di non essere del tutto inutile, mortale.", 0xfcdfe35e, 0x5486cd0f, 0x40ef8a00, 0xe95b54fc, 0xaec23a34, "....." },
  [4024] = { "Un assaggio di fiamma", "Raggiungi i ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e uccidi ⟦Bael'Gar=Bael'gar⟧.\n\nSai solo che il gigante si trova nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧. Ricorda di usare la ⟦Altered Black Dragonflight Molt=Muta Alterata dello Stormo Nero⟧ sui resti di ⟦Bael'Gar=Bael'gar⟧ per catturare l'essenza ardente.\n\nPorta l'⟦Encased Fiery Essence=Essenza Ardente Intrappolata⟧ a Cyrus Therepentous.", "Desidero assaporare le fiamme roventi della montagna di fuoco. Lasciare che i fuochi fusi di ⟦Blackrock=Roccianera⟧ si riversino su tutto il mio essere. Quell'essenza, quel calore rovente: è ciò che bramo.\n\n⟦Bael'Gar=Bael'gar⟧ risiede nei Sotterranei di ⟦Blackrock=Roccianera⟧: un essere di pura fiamma, nato dai fuochi di Ragnaros. Uccidi ⟦Bael'Gar=Bael'gar⟧ e dai suoi resti fumanti portami un frammento del suo fuoco interiore.\n\nUsa la muta sui suoi resti per estrarre senza pericolo la fiamma interiore.\n\nRiesci e sarai ricompensat<o/a>.", "Il gigante è caduto?", "<Cyrus ti strappa di mano l'essenza ardente.>\n\nSÌ!\n\nPrendi il tuo premio e sparisci. Togliti subito dalla mia vista!", 0xfcdfe35e, 0xba5ae01f, 0x2e60532b, 0x5af18fe3, 0x9c8fb03f, "....." },
  [4061] = { "L'ascesa delle macchine", "Avventurati nelle ⟦Burning Steppes=Steppe Ardenti⟧ e recupera 10 Scheggia Elementale Fratturata per la ierofante Theodora Mulvadania.\n\nRicordi che Theodora ha indicato i golem e gli elementali della regione come fonte di queste schegge.", "Le macchine si sono fatte notare durante le nostre prime incursioni nella ⟦Searing Gorge=Gorgia Rovente⟧. Indagando più a fondo abbiamo scoperto che venivano importate dalle ⟦Burning Steppes=Steppe Ardenti⟧, forse dai ⟦Blackrock Depths=Sotterranei di Roccianera⟧. Ed è per questo che abbiamo bisogno di te, {name}.\n\nIl tuo primo compito è avventurarti nelle ⟦Burning Steppes=Steppe Ardenti⟧ e recuperare schegge elementali dagli automi di roccia e dalle creazioni di roccia minori della regione. Quando ne avrai raccolte abbastanza, torna da me e ne stabilirò l'origine.", "Non prendere questo compito alla leggera, {name}!", "<Theodora dispone i frammenti davanti a sé.>\n\n<Theodora esamina con cura i frammenti attraverso un enorme monocolo.>\n\nInteressante. Incise nella struttura portante di ciascuno di questi frammenti ci sono... delle iniziali.", 0x87eb97c7, 0x95075dfa, 0xa054896b, 0x52f4b0fd, 0xc32121eb, "....." },
  [4062] = { "L'ascesa delle macchine", "Porta il ⟦Elemental Shard Sample=Campione di Scheggia Elementale⟧ a Lotwil Veriatus.\n\nRicordi che Theodora ha detto che Lotwil si trovava in un accampamento a est.", "G.L.A.\n\nSono queste le «iniziali» impresse sulle schegge elementali. Sotto le iniziali c'è una specie di indicazione di grado. I congegni che hai distrutto nelle ⟦Burning Steppes=Steppe Ardenti⟧ erano di «Grado IV». Suppongo che sia un grado basso.\n\nPorta questo campione di scheggia a Lotwil Veriatus, nell'accampamento a est. È uno studioso di una certa fama nel campo delle scienze elementali. Potrebbe aiutarci nella nostra ricerca.", "Cos'hai lì, {race}?", "<Il volto di Lotwil diventa bianco.>\n\nIo... io conosco questi segni.", 0x87eb97c7, 0x155232bd, 0xd8672ae4, 0x2ed65f2f, 0x11fdab04, "....." },
  [4063] = { "L'ascesa delle macchine", "Trova e uccidi ⟦Golem Lord Argelmach=Argelmach il Signore dei Golem⟧. Porta la sua testa a Lotwil. Dovrai anche raccogliere 10 Nucleo Elementale Intatto dai Ragereaver Golem e dai Warbringer Construct che proteggono Argelmach. Lo sai perché hai poteri psichici.", "Non può essere Argelmach! Argelmach è stato ucciso dieci anni fa. Come posso esserne sicuro? Sono stato io a ucciderlo.\n\nEra un nano spregevole, deciso a piegare il lavoro di tutta la mia vita ai suoi scopi diabolici. A quanto pare i malvagi trovano sempre un modo per sfuggire alla giustizia.\n\nSe questa è opera di Argelmach, allora va distrutto. Mi servono dei campioni delle sue ultime creazioni. Con i campioni giusti, forse riuscirò a fermare questa rivolta. Le creazioni proteggono Argelmach nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧.", "Era lui? Era davvero vivo?", "Cos'è questo?!? Questa testa non è di carne. È una specie di creazione Ferroscuro: un'ombra di Argelmach... UN'ALTRA macchina! Sospetto che la tua distruzione di Argelmach durerà poco, perché presto un altro sorgerà a prendere il «suo» posto.", 0x87eb97c7, 0x4c4bd657, 0xccd90590, 0xa58db9f2, 0xa4be27b1, "....." },
  [4081] = { "UCCIDERE A VISTA: ⟦Dark Iron Dwarves=Nani Ferroscuro⟧", "Avventurati nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e distruggi quei vili aggressori!\n\nIl signore della guerra Goretooth vuole che tu uccida 15 Anvilrage Guardsman, 10 Anvilrage Warden e 5 Anvilrage Footman. Torna da lui quando avrai completato il compito.", "Per ordine del signore della guerra Goretooth, comandante della Kargath Expeditionary Force:\n\nTutte le forze del generale Angerforge nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧, nessuna esclusa, devono essere annientate.\n\nGli uomini di Angerforge sono assassini spietati, responsabili del massacro della 109ª divisione della Kargath Expeditionary Force. Si avvertono gli eroi di usare estrema cautela nell'affrontare questi bruti.\n\nChiunque distrugga la prima linea delle forze del generale Angerforge nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧ riceverà un tributo.", "Che c'è, {race}? Non vedi che ho un plotone da comandare?", "Questo primo colpo dovrebbe stropicciare un po' i pantaloni ad Angerforge. Ora muoviti, soldato. Ho lavoro da sbrigare, battaglie da pianificare, nemici da schiacciare!\n\nControlla gli avvisi di taglia per altro lavoro.", 0x5b57c381, 0xfbf1c67a, 0x1bb891cb, 0x436990d6, 0xad38613a, "....." },
  [4082] = { "UCCIDERE A VISTA: alti ufficiali ⟦Dark Iron=Ferroscuro⟧", "Avventurati nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e distruggi i vili aggressori!\n\nIl signore della guerra Goretooth vuole che tu uccida 10 Anvilrage Medic, 10 Anvilrage Soldier e 10 Anvilrage Officer. Torna da lui quando avrai finito.", "Per ordine del signore della guerra Goretooth, comandante della Kargath Expeditionary Force:\n\nIl capo della divisione ricognizione della K.E.F., il gran maestro Lexlort, è tornato con notizie sul luogo in cui si trovano gli alti ufficiali ⟦Dark Iron=Ferroscuro⟧. Oltre un cancello chiuso, vicino al cuore della città, addestrano le loro forze per annientare i nostri uomini. Raggiungi i ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e distruggili!\n\nIl compimento di questa missione sarà ricompensato con un tributo.", "Ancora tu? Devo ammetterlo, {name}: sei tenace.", "Angerforge è senza dubbio... arrabbiato. Torna da me quando riceverai un terzo tributo e procederemo con l'Operazione: Morte ad Angerforge. Non posso entrare nei dettagli di ciò che comporta, ma sappi che qualcuno ci lascerà la pelle.", 0x98649479, 0xa3a116e9, 0x1f5265bd, 0x707ace6a, 0x7dc27660, "....." },
  [4083] = { "Il calice spettrale", nil, nil, "Il calice spettrale fluttua nell'aria, alzandosi e abbassandosi lentamente... come al ritmo di un cuore morente.", "Le gemme non fanno alcun rumore mentre cadono nelle profondità del calice...", 0x37a37884, nil, nil, 0x2d8e572b, 0x0ae3e7e4, ".mm.." },
  [4084] = { "Cuore d'argento", "Raccogli 11 ⟦Silvery Claws=Artigli Argentei⟧ e 1 ⟦Irontree Heart=Cuore di Troncoferro⟧ per ⟦Eridan Bluewind=Eridan Brezzastrale⟧ nel ⟦Felwood=Vilbosco⟧.", "Non conosco la persona di cui parli, {name}.\n\nMa non temere: se il tuo amico era in viaggio per trovarmi, so bene cosa desiderava.\n\nNel cuore del ⟦Un'Goro Crater=Cratere di Un'Goro⟧ dimora il male nella sua forma più pura. Questo male ha l'aspetto di un elementale chiamato ⟦Blazerunner=Fiammafulgida⟧... protetto da un'aura che nessuno può dissolvere...\n\nNessuno... tranne chi ha il potere sufficiente per farlo. Posso insegnarti questo potere, {name}.\n\nPrima, però, fa' come ti chiedo. Raccogli 11 ⟦Silvery Claws=Artigli Argentei⟧ e 1 ⟦Irontree Heart=Cuore di Troncoferro⟧ dalle creature del ⟦Felwood=Vilbosco⟧, poi torna.", "Posso dirti di più sul potere necessario per sconfiggere ⟦Blazerunner=Fiammafulgida⟧, ma prima devi raccogliere ciò che mi serve.", "Molto bene, {name}. Vedo che fai sul serio nell'aiutare il tuo amico.", 0x04c078b5, 0xe44cde37, 0xbdff1829, 0x1712c10d, 0xb4e28896, "....." },
  [4101] = { "Purificare il ⟦Felwood=Vilbosco⟧", "Porta 15 ⟦Blood Amber=Ambra Sanguigna⟧ ad ⟦Arathandris Silversky=Arathandris Cielargento⟧, nel ⟦Felwood=Vilbosco⟧.", "Le piante danno vita al ⟦Felwood=Vilbosco⟧, eppure anche loro subiscono la contaminazione della corruzione. Conosco modi per purificarle, ma non posso cedere un simile sapere a chi non conosco o di cui non mi fido. Dimostrami che aiuterai davvero la causa del ⟦Cenarion Circle=Circolo Cenariano⟧!\n\nA nord si trova la Caverna di Troncoferro. Gli elementali Warpwood che vi si trovano ormai non possono più essere purificati. Ti chiedo di portarmi la loro linfa, che chiamano ambra sanguigna, così che io possa studiarla nella speranza di salvare altre forme di vita qui.", "So che il ⟦Felwood=Vilbosco⟧ soffre, {name}: io soffro insieme a lui! Non posso cedere nelle mie convinzioni; se il sapere che possiedo finisse nelle mani sbagliate, sarebbe la rovina per tutto il ⟦Felwood=Vilbosco⟧.\n\nPortami l'ambra sanguigna estratta dagli elementali Warpwood uccisi e mi fiderò abbastanza di te da metterti a parte di un modo per combattere la corruzione.", "Quest'ambra sanguigna servirà a trovare un modo per sconfiggere la corruzione presente nel ⟦Felwood=Vilbosco⟧. Mi hai dimostrato di essere dispost<o/a> a fare tutto il necessario per il ⟦Cenarion Circle=Circolo Cenariano⟧. Ora mi fido di te, amico.\n\nPuò sembrare strano che uccidere gli elementali ti abbia fatto guadagnare la mia fiducia, ma il fine di salvare innumerevoli esseri senzienti deve giustificare i mezzi che usiamo. Ora tu e io possiamo concentrarci sulla salvaguardia della vita grazie agli unguenti che so preparare.\n\n{name}, è giunto il momento di purificare il ⟦Felwood=Vilbosco⟧.", 0x4b5f131b, 0x9a189c39, 0xc8b99dee, 0xb41117a7, 0xe78c0555, "....." },
  [4102] = { "Purificare il ⟦Felwood=Vilbosco⟧", "Porta 15 ⟦Blood Amber=Ambra Sanguigna⟧ a ⟦Maybess Riverbreeze=Maybess Brezza Marina⟧, nel ⟦Felwood=Vilbosco⟧.", "Le piante danno vita al ⟦Felwood=Vilbosco⟧, eppure anche loro subiscono la contaminazione della corruzione. Conosco modi per purificarle, ma non posso cedere un simile sapere a chi non conosco o di cui non mi fido. Dimostrami che aiuterai davvero la causa del ⟦Cenarion Circle=Circolo Cenariano⟧!\n\nA nord si trova la Caverna di Troncoferro. Gli elementali Warpwood che vi si trovano ormai non possono più essere purificati. Ti chiedo di portarmi la loro linfa, che chiamano ambra sanguigna, così che io possa studiarla nella speranza di salvare altre forme di vita qui.", "So che il ⟦Felwood=Vilbosco⟧ soffre, {name}: io soffro insieme a lui! Non posso cedere nelle mie convinzioni; se il sapere che possiedo finisse nelle mani sbagliate, sarebbe la rovina per tutto il ⟦Felwood=Vilbosco⟧.\n\nPortami l'ambra sanguigna estratta dagli elementali Warpwood uccisi e mi fiderò abbastanza di te da metterti a parte di un modo per combattere la corruzione.", "Quest'ambra sanguigna servirà a trovare un modo per sconfiggere la corruzione presente nel ⟦Felwood=Vilbosco⟧. Mi hai dimostrato di essere dispost<o/a> a fare tutto il necessario per il ⟦Cenarion Circle=Circolo Cenariano⟧. Ora mi fido di te, amico.\n\nPuò sembrare strano che uccidere gli elementali ti abbia fatto guadagnare la mia fiducia, ma il fine di salvare innumerevoli esseri senzienti deve giustificare i mezzi che usiamo. Ora tu e io possiamo concentrarci sulla salvaguardia della vita grazie agli unguenti che so preparare.\n\n{name}, è giunto il momento di purificare il ⟦Felwood=Vilbosco⟧.", 0x4b5f131b, 0xcc6dd0b9, 0xc8b99dee, 0xb41117a7, 0xe78c0555, "....." },
  [4120] = { "La forza della corruzione", "⟦Talo Thornhoof=Talo Zoccolo Spinoso⟧, all'⟦Camp Mojache=Accampamento Mojache⟧ a Feralas, vuole che tu uccida 12 Angerclaw Grizzly e 12 Felpaw Ravager a ⟦Felwood=Vilbosco⟧.", "Da cacciatore, mi sforzo di emulare i punti di forza che vedo nei miei avversari. È possibile volgere la battaglia a proprio favore semplicemente conoscendo bene il nemico, {name}.\n\nIn un luogo chiamato ⟦Felwood=Vilbosco⟧, a nord di ⟦Ashenvale=Valtetra⟧, le creature sono state contaminate da una sostanza chiamata Vil. Gli orsi e i lupi ne sono impazziti, ma credo che siano anche diventati ancora più forti.\n\nVa', {name}. Raggiungi ⟦Felwood=Vilbosco⟧ e affronta queste bestie. Scopri da te se sono davvero forti come credo.", "Tutto ciò che è stato toccato dal Vil emana uno strano bagliore verde... Sento che è malvagio, ma al tempo stesso molto potente.", "Dalle tue descrizioni sembra che le creature mostrino una ferocia cieca...\n\nResta all'erta, {name}. Sarebbe nel tuo interesse saperne di più sulla corruzione. Conosci sempre il tuo nemico.", 0x8cd381ae, 0xb24931f9, 0xa1cc7468, 0xd42eceb7, 0xda615740, "....." },
  [4121] = { "Una situazione precaria", "Scorta il tuo prigioniero, Grark Lorkrub, attraverso le ⟦Burning Steppes=Steppe Ardenti⟧ e il ⟦Blackrock Mountain=Massiccio Roccianera⟧ fino alla ⟦Searing Gorge=Gorgia Rovente⟧.\n\nRicordi che Lexlort ha detto che i suoi uomini aspetteranno dall'altra parte per prendere in custodia Grark.\n\nDovrai anche consegnare le ⟦Thorium Shackles=Manette di Torio⟧ a Lexlort.", "Credi davvero di arrivare al punto d'incontro con me in custodia? Ti aspettavi sul serio di entrare in una fortezza ⟦Blackrock=Roccianera⟧ pesantemente fortificata e catturare una delle loro risorse più preziose senza che nessuno e niente si accorgesse della tua presenza?\n\nSarai distrutt<o/a>!", "Prenderò io questo sudicio traditore, {name}.", "Il tuo eroismo non passerà inosservato, {name}. Ti sei guadagnat<o/a> questo tributo. Il signore della guerra ti parlerà ora dell'ultima missione.", 0x8fd5dbe7, 0xf6e011d7, 0x41c7f16e, 0x2213bc0d, 0xfb5709db, "....." },
  [4122] = { nil, "Raggiungi le ⟦Burning Steppes=Steppe Ardenti⟧ e trova Grark Lorkrub. Ricordi che Lexlort ha detto che l'hanno visto l'ultima volta in un'enorme fortezza ⟦Blackrock=Roccianera⟧.\n\nQuando trovi Grark Lorkrub, usa le ⟦Thorium Shackles=Manette di Torio⟧ per legarlo, poi riportalo attraverso il ⟦Blackrock Mountain=Massiccio Roccianera⟧ fino alla ⟦Searing Gorge=Gorgia Rovente⟧. Gli uomini di Lexlort aspetteranno dall'altra parte per prendere in custodia Grark.", "L'ho seguito attraverso la ⟦Searing Gorge=Gorgia Rovente⟧, dentro la montagna e fino alle ⟦Burning Steppes=Steppe Ardenti⟧. Quel traditore è stato colto con le mani nel sacco mentre dava agli orchi ⟦Blackrock=Roccianera⟧ informazioni vitali sulle nostre operazioni quotidiane. Parlo di Grark Lorkrub.\n\nOra se ne sta nelle ⟦Burning Steppes=Steppe Ardenti⟧, al sicuro sotto la loro protezione... o almeno così crede.\n\nPrendi queste manette, {name}. Trova Grark, mettigli le manette e conducilo attraverso il ⟦Blackrock Mountain=Massiccio Roccianera⟧. Fallo e il tributo sarà tuo.", nil, "Non vedi il potere che otteniamo unendoci alla legione di ⟦Blackrock=Roccianera⟧?", 0xf4017ef8, 0x5d91f069, 0xe8e67229, nil, 0x08e246b4, "e..m." },
  [4123] = { "Il ⟦The Heart of the Mountain=Cuore della Montagna⟧", "Porta il Cuore della Montagna a ⟦Maxwort Uberglint=Maxwort Granscintilla⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Da anni cerco una certa gemma. Si chiama Cuore della Montagna ed è grande quanto il tuo pugno! I nani ⟦Dark Iron=Ferroscuro⟧ la tengono chiusa nel loro caveau e, per quanto io ci provi, non vogliono vendermela.\n\nQuindi devo ricorrere alla forza.\n\nFatti strada combattendo fino al caveau inferiore dei ⟦Blackrock Depths=Sotterranei di Roccianera⟧, scassina la cassaforte segreta e prendi il Cuore. Per farlo dovrai sconfiggere il sorvegliante Doomgrip, che non comparirà finché non avrai aperto tutti gli scrigni delle reliquie del caveau!\n\nBuona fortuna.", "Hai il Cuore della Montagna? Per me il suo valore non ha limiti.", "Hai il Cuore! Incredibile! È ancora più bello di quanto immaginassi!\n\nTi prego, {name}, prendi questo come pagamento!", 0x64cd6d04, 0x5c6ba9a4, 0x7e785515, 0x5e154cee, 0x0c1b5cb9, "....." },
  [4124] = { "Il corriere scomparso", "Parla con ⟦Ginro Hearthkindle=Ginro Cuorfavilla⟧ alla Roccaforte di Piumaluna.", "Un mio collaboratore, ⟦Ginro Hearthkindle=Ginro Cuorfavilla⟧, cerca aiuto per ritrovare un corriere e i pacchi che trasportava. È passata una settimana o giù di lì da quando il corriere è scomparso; le nostre ricerche non hanno dato frutti, e siamo a un punto morto. Purtroppo ho dovuto dichiarare il corriere disperso in missione.\n\nSe hai tempo e mezzi da dedicarci, ti prego, parla con Ginro. Dovrebbe essere qui nella roccaforte, forse nei suoi alloggi.", nil, "Ti manda Latro, immagino. Anche se a questo punto credo sia una causa persa, accetterò qualsiasi aiuto tu possa offrirmi. Devo ammetterlo... sarò felice quando potrò mettermi il cuore in pace su questa faccenda. Ogni giorno parto per le terre selvagge di Feralas in cerca di tracce di Raschal, e ogni sera torno senza nulla da mostrare per i miei sforzi, a parte denti di gnoll e delusione.", 0x05891b2b, 0xd64f6ee6, 0x6914d46a, nil, 0xadd3e8c1, "...m." },
  [4125] = { "Il corriere scomparso", "Trova la barca del corriere da qualche parte lungo la costa di Feralas.", "È passata circa una settimana da quando Raschal, il corriere, è partito per Thalanaar. Conosce bene Feralas; è con noi da quando la generale Feathermoon ha guidato qui le forze di spedizione. So che il suo piano era prendere una barca a remi lungo la costa e cercare di attraversare il sud di Feralas per evitare l'accampamento dell'⟦Horde=Orda⟧.\n\nIo non sono riuscito a trovare la sua barca, ma forse tu ci riuscirai. Forse è nascosta, o forse è stata affondata. In ogni caso, potrebbe contenere un indizio su dove si trovi. Se scopri qualcosa, ti prego, fammelo sapere.", nil, "Hai trovato quella che sembra una barca a remi distrutta. Attraverso l'acqua un po' fangosa vedi grossi squarci che crivellano il lato di babordo; la barca è ridotta quasi alla sua semplice ossatura di legno. Qualunque cosa l'abbia distrutta, probabilmente ha cercato di spezzarla in due. Sul lato di tribordo è dipinto un piccolo stemma della Roccaforte di Piumaluna.\n\nNel fango alla base della barca, un luccichio metallico attira la tua attenzione...", 0x05891b2b, 0xbe904bf7, 0x2af52f5d, nil, 0x30d69719, "...m." },
  [4126] = { nil, "Porta la ⟦Lost Thunderbrew Recipe=Ricetta Perduta della Birratuono⟧ a ⟦Ragnar Thunderbrew=Ragnar Birratuono⟧, a Kharanos.", "I nani ⟦Dark Iron=Ferroscuro⟧, guidati da quel furfante di ⟦Hurley Blackbreath=Hurley Fiatonero⟧, hanno rubato una delle migliori ricette dei Thunderbrew, la Thunderbrew Lager. Che canaglie! Non meritano una birra così buona!\n\n{name}, ho un compito difficile per te. Va' nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧, distruggi tutti i barili di Thunderbrew Lager che trovi e riportaci la nostra ricetta della Thunderbrew Lager!\n\nTi prego, riprendi quella ricetta, anche se dovessi mettere sottosopra i ⟦Blackrock Depths=Sotterranei di Roccianera⟧ per farlo!", "Hai la ricetta, {name}? Non sopporto l'idea che quei nani ⟦Dark Iron=Ferroscuro⟧ bevano la birra della mia famiglia!", "L'hai trovata! Ben fatto! E spero che tu abbia dato una bella lezione a quei Ferroscuro e a ⟦Hurley Blackbreath=Hurley Fiatonero⟧!\n\nI Thunderbrew sono al tuo servizio, {name}. Sei <un/una> <eroe/eroina> tra gli eroi!", 0xc4008466, 0x93309524, 0x5d695408, 0x489de26e, 0x8e13a0d0, "e...." },
  [4127] = { "Il relitto della barca", "Torna alla Roccaforte di Piumaluna e mostra a ⟦Ginro Hearthkindle=Ginro Cuorfavilla⟧ il ⟦Discarded Knife=Coltello Scartato⟧ che hai trovato.", "Passando la mano nel fango, le tue dita sfiorano il manico di un coltello. Sembra ben tenuto, e si potrebbe supporre che chiunque fosse sulla barca l'abbia perso. Forse il grosso pezzo mancante della barca ha qualcosa a che fare con la perdita.\n\nPrendi il coltello, ricordando che ⟦Ginro Hearthkindle=Ginro Cuorfavilla⟧, alla Roccaforte di Piumaluna, ti ha chiesto di tornare da lui con qualsiasi indizio trovato. Hai però la sensazione di non essere del tutto sol<o/a> nell'acqua...", "Ah, bentornat<o/a>, {name}. Spero che tu sia riuscit<o/a> a scoprire qualche indizio sulla sorte di Raschal, per quanto tragica possa essere.", "Interessante... Credo che questo sia il coltello di Raschal. Dici di averlo trovato sul fondo, insieme alla sua barca? Be', il solo ritrovamento del coltello potrebbe non bastare a collegarlo alla scomparsa di Raschal; abbiamo però un'opzione insolita per cercare di saperne di più.\n\nHai mai sentito parlare di psicometria?", 0x7d02beea, 0x85c0f895, 0x3c45061d, 0xbc63d551, 0xd54492e1, "....." },
  [4128] = { nil, "Parla con ⟦Ragnar Thunderbrew=Ragnar Birratuono⟧.", "Ehi, {name}. Ho sentito che ⟦Ragnar Thunderbrew=Ragnar Birratuono⟧ è furioso perché qualcuno gli ha rubato la birra. Cerca avventurieri valorosi ed è disposto a pagare bene.\n\nParla con Ragnar, se ti interessa. È alla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧ di Kharanos, a Dun Morogh.", nil, "Altroché se sono arrabbiato! Mi hanno derubato! Derubato di una delle nostre ricette di famiglia! Come si permettono! Come se non avessi già abbastanza motivi per odiare i nani ⟦Dark Iron=Ferroscuro⟧! Adesso, oh... adesso sì che se la vedranno brutta!", 0x8b04a24f, 0x902b7d45, 0x4b5d97c0, nil, 0x5a0ef227, "e..m." },
  [4129] = { "Il coltello svelato", "Porta il ⟦Discarded Knife=Coltello Scartato⟧ a ⟦Quintis Jonespyre=Quintis Tordigiada⟧, alla Roccaforte di Piumaluna.", "Il druido residente della roccaforte, ⟦Quintis Jonespyre=Quintis Tordigiada⟧, ha alcune capacità... insolite. Una di queste è la psicometria: la capacità di rivelare la storia di un oggetto toccandolo. Non chiedermi come faccia; per me è magia che non capisco e che preferisco non capire. So però due cose: uno, l'ho vista funzionare, e due, quello scansafatiche è in debito con me.\n\nPorta il coltello a Quint, su nella sua casetta sull'albero, e digli da parte mia che il suo debito al Kalimdor Hold 'Em sarà saldato se fa le sue magie su quel coltello.", "Ti manda Ginro, eh?\n\nLe mie letture psicometriche sono piuttosto spossanti per la mente... ma lo sono anche le mie perdite al Kalimdor Hold 'Em. Qui alla roccaforte mi chiamano \"il Re delle Batoste\". Sfortunato a carte... fortunato nel padroneggiare i segreti della natura, immagino.\n\nComunque, certo che lo farò. Potrebbe essere proprio la svolta che ci serve per scoprire la sorte di Raschal. Se mi passi il coltello, possiamo cominciare.", "Grazie, {name}.\n\nLa psicometria non è certo un'arte esatta, ma in passato l'ho usata per far luce su situazioni che altri avevano dato per perse. Credo che usarla sul coltello che hai trovato ci darà un'idea di cosa è successo a Raschal.\n\nCi vorrà solo un momento, ma non è quello che definirei un compito facile per chi lancia incantesimi. Abbi pazienza.", 0x5a2b17b8, 0x98645dbc, 0x01a82e3d, 0xea41a841, 0x24cb6162, "....." },
  [4130] = { "Lettura psicometrica", "Parla con ⟦Ginro Hearthkindle=Ginro Cuorfavilla⟧ alla Roccaforte di Piumaluna.", "Mi gira ancora un po' la testa, scusa. Comunque, ho avuto alcune visioni utili.\n\nRaschal prende due grandi zaini di cuoio dalla sua barca e si addentra verso l'interno; poi però torna alla barca. Vedo scalpi di gnoll... si è imbattuto in alcuni gnoll, Raspalegno, credo che si chiamino. È molto preoccupato, quasi terrorizzato, per qualcosa. Tanto che non si accorge degli elementali dell'acqua che si formano alle sue spalle. Le immagini... si fermano qui.\n\nDevo riposare, scusa {name}. Racconta a Gin quello che ho visto. Deve saperlo.", nil, "Grazie per avermi riferito le visioni di Quint, {name}. Cercherò di ricordarmi di essere un po' più indulgente con lui la prossima volta che giochiamo a carte.\n\nRaschal sa difendersi in uno scontro, e gli gnoll non sono certo qualcosa che lo farebbe preoccupare, figuriamoci terrorizzare. Comunque, forse tu e i tuoi potete agire in base a queste nuove informazioni e ottenere la svolta di cui abbiamo disperatamente bisogno.", 0xf6ce658b, 0xd64f6ee6, 0x74d0882e, nil, 0x42b23019, "...m." },
  [4131] = { "Gli gnoll Raspalegno", "Cerca negli accampamenti degli gnoll Raspalegno, nel sud di Feralas, tracce degli effetti personali del corriere o del corriere stesso.", "I nostri \"amici\" Raspalegno potrebbero aver fatto fuori Raschal, alla fine, ma qualcosa mi dice che non è andata così. Comunque, sono il posto migliore da cui cominciare a cercare.\n\nVorrei avere un'idea più chiara di cosa fare, ma per ora tutto ciò che ho è: 'Cerca negli accampamenti dei Raspalegno, vai.' So però che gli gnoll tengono gli oggetti che razziano e se li contendono; forse si sono imbattuti negli zaini di cui parlava Quint. Nelle ricerche passate non avevo rischiato uno scontro frontale, ma con la visione di Quint, io dico: falli a pezzi.", nil, "Appesi a un albero lì vicino ci sono due grandi zaini di cuoio. Ognuno porta sul davanti una piccola insegna della Roccaforte di Piumaluna...", 0xb9f65bac, 0x9cdc696a, 0x64b79ecf, nil, 0xed276df7, "...m." },
  [4132] = { "Operazione: morte ad Angerforge", "Raggiungi i ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e uccidi ⟦General Angerforge=Generale Forgiarabbia⟧! Torna dal signore della guerra Goretooth quando avrai finito.", "Hai fatto un lavoro esemplare, {name}. Ora è il momento di affidarti la tua ultima missione.\n\nIl generale Angerforge, il ⟦Dark Iron=Ferroscuro⟧ responsabile del coordinamento degli attacchi contro la 109ª divisione della K.E.F. e del massacro delle nostre forze, deve essere consegnato alla giustizia.\n\nSarà senza dubbio la tua missione più estenuante ma, se ci riuscirai, sarai ricompensat<o/a> generosamente.", "Ci siamo sbarazzati del Macellaio di ⟦Blackrock=Roccianera⟧?", "Finalmente! Il furfante è stato consegnato alla giustizia! Sei una persona straordinaria, {name}. Indossa questo medaglione come simbolo della tua salda dedizione all'⟦Horde=Orda⟧ e alla K.E.F.", 0xc3b1887e, 0xfcb068b5, 0x66477d79, 0x27ab1409, 0x9feb7e5c, "....." },
  [4133] = { nil, "Parla con la maestra delle ombre Vivian Lagrave, a Kargath.", "La maestra delle ombre Vivian Lagrave ha bisogno dei tuoi servigi. Si trova nelle ⟦Badlands=Maleterre⟧, nell'avamposto orchesco di Kargath, e sta seguendo le voci su una certa birra prodotta dai nani ⟦Dark Iron=Ferroscuro⟧ dei ⟦Blackrock Depths=Sotterranei di Roccianera⟧.\n\nParla con Vivian. Ti aspetta.", nil, "Grazie di essere venut<o/a>, {name}. Questo posto non è privo di un fascino austero, ma manca delle comodità dell'Apothecarium.\n\nBasta con i convenevoli. Passiamo agli affari, d'accordo?", 0x55a2ff51, 0xafae59a2, 0xf2e1d493, nil, 0x684ce66c, "e..m." },
  [4134] = { "⟦Lost Thunderbrew Recipe=Ricetta Perduta della Birratuono⟧", "Porta la ⟦Lost Thunderbrew Recipe=Ricetta Perduta della Birratuono⟧ a Vivian Lagrave, a Kargath.", "Si dice che il ⟦Dark Iron=Ferroscuro⟧ ⟦Hurley Blackbreath=Hurley Fiatonero⟧ abbia rubato la ricetta di una birra. Questa birra, la Thunderbrew Lager, darebbe a chi la beve grande forza e coraggio. Vogliamo studiarla. Forse troveremo altri usi per le sue virtù... usi più in linea con gli obiettivi dei Reietti.\n\nAddentrati nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧, trova Hurley, sottraigli la ricetta della Thunderbrew Lager e portamela.\n\nE per trovarlo, forse dovrai attirarlo minacciando la sua preziosa birra.", "Hai la ricetta della Thunderbrew Lager, {name}?", "Molto bene. Manderò questa ricetta all'Apothecarium perché venga studiata, e col tempo ne sveleremo i segreti. Un giorno i nani dell'⟦Alliance=Alleanza⟧ potrebbero vedere le virtù di questa bevanda usate contro di loro!\n\nLo trovo terribilmente divertente. Forse la morte influisce sul senso dell'umorismo... non credi?", 0x748bf69d, 0x933801cd, 0x81bea919, 0x7e3d89d6, 0x4e029e8d, "....." },
  [4135] = { "La ⟦The Writhing Deep=Fossa Fremente⟧", "Ora che hai scoperto dove Raschal è stato visto l'ultima volta, continua a cercare lui o i suoi resti nella Fossa Fremente. Secondo il biglietto, si trova a sud degli accampamenti degli gnoll Raspalegno.", "Negli zaini ci sono due cose: la prima è un pacco di merci destinato a Thalanaar, la seconda un biglietto scritto in fretta a un lettore sconosciuto.\n\nIl biglietto parla della scoperta di insidiose creature simili a insetti a sud degli accampamenti degli gnoll, in un luogo chiamato Fossa Fremente. L'autore sentiva il bisogno di indagare di persona, come se fosse una grave minaccia per tutta Feralas. Il biglietto è firmato: \"Raschal di Feathermoon\".\n\nSembra che tu abbia trovato il luogo dove è finito Raschal.", nil, "Hai scoperto un grosso baccello di natura aliena. La superficie del baccello sembra mucosa, anche se qua e là spuntano protuberanze indurite. Il baccello è alto e largo abbastanza da contenere facilmente un umanoide... e dalla debole sagoma umanoide visibile attraverso la sua pelle, deduci che è proprio ciò che racchiude.", 0x7b083e72, 0xaa66fc0f, 0xc369aa3c, nil, 0x656d0a45, "...m." },
  [4136] = { nil, "Porta la ⟦Ribbly's Head=Testa di Ribbly⟧ a ⟦Yuka Screwspigot=Yuka Giravite⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Mio fratello Ribbly è sempre stato un peso per la sua famiglia: prendeva i nostri soldi e li sprecava in un progetto dopo l'altro.\n\nBe', il suo ultimo progetto dev'essere stato il peggiore, perché il barone Revilgaz della ⟦Booty Bay=Baia del Bottino⟧ ha appena messo una taglia sulla testa del povero Ribbly. Non puoi immaginare quanto questo renda felici gli Screwspigot! Il nostro piccolo Ribbly finalmente vale qualcosa!\n\nMa ora si è nascosto, giù nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧. Ti prego, trovalo e portalo da me!\n\nOppure, se non vuole venire, va bene lo stesso... portami solo la sua testa.", "Hai Ribbly? O almeno un pezzo di lui?", "Ah! L'hai trovato! E... a quanto pare il mio fratellino non voleva venire senza fare storie. Peccato. Mi sarebbe piaciuto vedere la sua faccia quando gli avrei detto che volevamo consegnarlo a Revilgaz.\n\nGrazie, {name}. Hai reso la mia famiglia molto felice. E Ribbly non è mai sembrato tranquillo come adesso.", 0x67d4d005, 0x59fd1d36, 0xbb53d4bb, 0xb98234d6, 0x2665856f, "e...." },
  [4141] = { "Muigin e Larion", "Raccogli 15 Bloodpetal e torna da Muigin.", "Vedi Larion laggiù? È colpa SUA se siamo qui!\n\nGli avevo detto che stavamo sbagliando strada, ma pensi che mi abbia ascoltato? E ci crederesti che è lui quello che non mi rivolge la parola? Be', finché non cambia idea, divertiamoci un po' alle sue spalle.\n\nHai notato quelle strane creature simili a piante qui intorno? Non portano altro che guai, davvero, ma credo che, addestrandole a dovere, potrei fargli obbedire ai comandi.\n\nPrima di tutto, però, mi servono dei campioni da studiare. Pensi di poterne raccogliere qualcuno?", "Larion avrà quel che si merita, poco ma sicuro!", "Spero che non ti abbiano dato troppi problemi, {name}. Io cerco di stargli alla larga: sono selvagge!\n\nHo provato a saltarne una... e mi ha attaccato! Le piante non dovrebbero comportarsi così!", 0x3b600e39, 0x56ce26b8, 0x8d143ea4, 0x196febdb, 0x8ed4db5d, "....." },
  [4142] = { "Una visita a Gregan", "Porta un Bloodpetal a ⟦Gregan Brewspewer=Gregan Sputabirra⟧ a Feralas.", "Non so bene cosa pensare di questo, {name}. Le piante... sembrano avere un minimo di intelligenza.\n\nPerò non sono un esperto. Ma conosco qualcuno che lo è!\n\nVa' nel nord di Feralas e cerca un mio amico che si chiama ⟦Gregan Brewspewer=Gregan Sputabirra⟧. È un esperto di queste cose.\n\nSono sicuro che Gregan potrà darci una mano. Lo troverai in mezzo alla natura selvaggia: non è il tipo da vivere in una grande città.", "Vivo qui fuori, nella foresta... In pace.\n\nAlmeno, così credevo. Ricevo più visite qui che quando vivevo a ⟦Ironforge=Forgiardente⟧!", "Petalorosso, eh? Mmm... Be', farai meglio a spiegarmi il piano, poi ti dirò se posso aiutarti o no.", 0x36b0a2e1, 0x0a57e80f, 0x0530df19, 0x0370b6ea, 0x794b85cc, "....." },
  [4143] = { "Una nube malvagia", "Raccogli 5 campioni di ⟦Atal'ai Haze=Nuvola degli Atal'ai⟧, poi torna da Muigin nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "A dire il vero, {name}, non ho mai visto piante come queste nei miei viaggi. Forse dovrei fare un salto in questo cratere...\n\nComunque, credo di sapere esattamente cosa cerca Muigin: la ⟦Atal'ai Haze=Nuvola degli Atal'ai⟧. È una roba orribile, difficile da raccogliere, ma è proprio ciò che gli serve per controllare quei piccoli mostri.\n\nDovrai visitare il Tempio di Atal'Hakkar, nella ⟦Swamp of Sorrows=Palude del Dolore⟧. La ⟦Atal'ai Haze=Nuvola degli Atal'ai⟧ si può raccogliere dai Deep Lurker, dai Murk Worm o dalle melme che si trovano lì. Buona fortuna, {name}!", "Larion ancora non mi rivolge la parola! Sa proprio come portare rancore.", "Lo ammetto, toccare quella roba mi fa un po' esitare, {name}! Ma se Gregan dice che funzionerà, sono disposto a provarci!", 0xea486465, 0xf2e06255, 0x87555936, 0x26b31bb5, 0x02785b23, "....." },
  [4144] = { "Germogli di Petalorosso", nil, nil, "Ecco il piano, {name}: va' fuori a raccogliere qualche germoglio di petalorosso, sai, le piante che non sono ancora spuntate del tutto, e portali qui. Poi vedrò cosa riesce a fare la nuvola degli Atal'ai.\n\nPenserai che sono vendicativo... E in effetti avresti ragione!\n\nLa verità è che conosco la via d'uscita da qui, ma finché Larion non ammetterà che ho ragione io, resto proprio qui!\n\nQuindi via, trova quei germogli di petalorosso e divertiamoci un po'!", "O la va o la spacca, {name}! Questo attirerà l'attenzione di Larion!", 0xa017fdce, nil, nil, 0x0a863215, 0xb43bdc2e, ".mm.." },
  [4145] = { "Larion e Muigin", "Caccia 5 Bloodpetal Lasher, 5 Bloodpetal Thresher, 5 Bloodpetal Flayer e 5 Bloodpetal Trapper per Larion al ⟦Marshal's Refuge=Rifugio dei Grant⟧.", "Vedi Muigin laggiù? È colpa SUA se ci siamo persi!\n\nIo ero quello che conosceva la strada, ma lui ha insistito che conosceva una scorciatoia, e siamo finiti qui!\n\nCome se non bastasse, ora continua a mandarmi le sue pazze piante infestanti a darmi fastidio. Sono così arrabbiato che non ho intenzione di rivolgergli la parola tanto presto, ma queste pesti sono troppe da sopportare.\n\nPerché non cominciamo col ridurre le sue scorte? Va' a caccia di qualche Petalorosso, poi torna da me.", "Muigin deve chiedermi scusa prima che io torni a parlargli!", "Grazie per l'aiuto, {name}, ma temo di avere brutte notizie...", 0xc8a99c67, 0xd07fc75c, 0x91ec51ee, 0x8777962b, 0x630db9da, "....." },
  [4146] = { "Carburante per il folgoratore", "Consegna il ⟦Unloaded Zapper=Folgoratore Scarico⟧ e 5 campioni di ⟦Atal'ai Haze=Nuvola degli Atal'ai⟧ a Larion al ⟦Marshal's Refuge=Rifugio dei Grant⟧.", "Sei fortunat<o/a>, {name}! Mentre Marvon era via ho lavorato a qualche esperimento tutto mio, e uno di questi è un folgoratore d'insetti a corto raggio. Con qualche piccola modifica, dovrebbe essere perfetto per liberarti di quelle pesti di Petalorosso.\n\nPosso darti uno dei miei prototipi di folgoratore, ma il carburante dovrai raccoglierlo tu. La Nuvola degli Atal'ai che serve al folgoratore puoi trovarla nel Tempio di Atal'Hakkar. È dai Deep Lurker, dai Murk Worm o dalle melme che dovrai prenderla.", "È sfiancante, {name}. Quelle cose non mi lasciano in pace!", "Allora, Marvon non c'era? Be', fammi vedere cos'hai, comunque.", 0xce60817d, 0x19bd60e0, 0xb4760e21, 0xcda34d1b, 0xde182db0, "....." },
  [4147] = { "L'officina di Marvon", "Raggiungi l'officina di Marvon Rivetseeker a ⟦Ratchet=Porto Paranco⟧.", "Sono riuscito a spiare cosa stava facendo Muigin, e quelle maledette cose le sta proprio coltivando laggiù!\n\nCredo che l'unica soluzione sia... no, non andare a parlargli... Ma che ti salta in mente? La soluzione è contrattaccare!\n\nCi servirà l'aiuto del mio amico Marvon, che ha un'officina a ⟦Ratchet=Porto Paranco⟧. Sono sicuro che riuscirà a costruire un qualche congegno che ci aiuti.", nil, "Marvon è via da parecchio tempo ormai, {name}. È andato a Tanaris a studiare alcune antiche rovine troll.\n\nAllora, cos'è che hai detto che ti serviva?", 0x5c3474ce, 0x419285da, 0x9670b486, nil, 0x1f082263, "...m." },
  [4148] = { "Il ⟦Bloodpetal Zapper=Folgoratore di Petalorosso⟧", nil, nil, "Perché il folgoratore funzioni, serve un campione della creatura bersaglio. Va' nel cratere e raccogli un germoglio di petalorosso. Poi potrò tararlo sui piccoli amici di Muigin...\n\nSe non fosse così testardo, saremmo già sulla via di casa... Ma fino ad allora dovrò solo dimostrargli che il suo scherzetto non mi tocca affatto!", "Sembra che funzionerà alla perfezione, {name}. Ora ricorda: se vedi uno di quei parassiti nei paraggi, non esitare a usare il folgoratore!", 0xfd71cf63, nil, nil, 0x10421a0e, 0x60d9e5d7, ".mm.." },
  [4161] = { "La ricetta dei kaldorei", "Raccogli 7 Piccola Zampa di Ragno per Zarrin a Dolanaar.", "Tanto tempo fa, gli elfi della notte erano chiamati kaldorei, un nome che significa \"figli delle stelle\". Conoscere il passato è un passo importante nel tuo cammino di {class}, {name}, quindi ascolta bene ciò che ho da dirti.\n\nI kaldorei sono sempre stati molto orgogliosi del loro rapporto armonioso con la natura. Questo significa che prendiamo dalla natura solo ciò che è necessario, e che restituiamo in egual misura. Questo equilibrio ci ha dato molto, {name}.\n\nVa' e raccogli sette zampe di ragno piccolo, non una di più, e torna da me.", "Ricorda l'equilibrio, {name}. Voglio che tu sviluppi una comprensione e una forte empatia per le foreste viventi.", "Ricorda sempre ciò che ti ho mostrato oggi, {name}. Fai parte dell'equilibrio che gli elfi della notte si sforzano di mantenere intatto, anche nei tempi difficili.", 0xc790841a, 0x7c7f5405, 0x2a2ed2f9, 0xb7a98f7e, 0xbe9fad73, "....." },
  [4181] = { "⟦Goblin Engineering=Ingegneria dei Goblin⟧", "Se vuoi saperne di più sull'⟦Goblin Engineering=Ingegneria dei Goblin⟧, porta il ⟦Manual of Engineering Disciplines=Manuale delle Discipline Ingegneristiche⟧ a ⟦Nixx Sprocketspring=Nixx Oliamolla⟧, a ⟦Gadgetzan=Meccania⟧.", "L'ingegneria di livello esperto si divide in due discipline distinte: quella degli gnomi e quella dei goblin. Ti parlo dell'Ingegneria dei Goblin solo perché sono un istruttore onesto. Ai goblin piace costruire cose che esplodono, e raramente si curano di ciò che sta in mezzo... nemmeno di se stessi.\n\n{name}, leggi questo manuale. Se vuoi imparare a farti saltare in aria, portalo a ⟦Nixx Sprocketspring=Nixx Oliamolla⟧, a ⟦Gadgetzan=Meccania⟧. Ricorda: l'iscrizione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati che sia ciò che vuoi prima di completare il suo compito.", "Le reclute fresche le fiuto come fiuto un'ottima polvere esplosiva: a un miglio di distanza. Sei venut<o/a> per imparare a padroneggiare l'esplosione?", "Be', {name}, hai fatto bene a cercare la mia guida! Qualsiasi sprovveduto può diventare esperto nelle basi dell'ingegneria: gli gnomi e la loro casa radioattiva, Gnomeregan, ne sono la prova. Ma per padroneggiare la disciplina dell'⟦Goblin Engineering=Ingegneria dei Goblin⟧ ci vogliono una mente forte e una mano ferma (e sottolineo FERMA).\n\nTieni le orecchie dritte, {name}, e forse imparerai qualcosa.", 0x4ccb3e9c, 0x84f932f9, 0x52e16ce5, 0x21f4153d, 0xad63c1bf, "....." },
  [4182] = { "La minaccia dei dragoidi", "Uccidi 15 Black Broodling, 10 ⟦Black Dragonspawn=Dragobestia Nero⟧, 4 ⟦Black Wyrmkin=Dragonoide Nero⟧ e 1 ⟦Black Drake=Draco Nero⟧. Torna da ⟦Helendis Riverhorn=Helendis Sinuocorno⟧ quando avrai finito.", "La vita nelle ⟦Burning Steppes=Steppe Ardenti⟧ è piena di conflitti.\n\nGuarda questo posto! Sappiamo ben poco di cosa sia successo a questi edifici, ma sappiamo che un tempo, prima della grande esplosione, tutto questo faceva parte della catena montuosa di ⟦Redridge=Crestarossa⟧.\n\nBasta lamentarsi! Abbiamo un problema, {name}. Avrai notato i dragoidi sotto questa cresta. Ci serve aiuto per respingerli. Uccidine quanti più puoi e torna da me. Se ci riesci, forse potremo parlare d'altro.", "Come va la caccia ai draghi?", "Una strage superba, {name}. Ora che sappiamo che sai cavartela con i dragoidi, possiamo parlare di questioni più urgenti.", 0xdfeea486, 0xc3006198, 0xb7f67c45, 0x19b535d2, 0x8c7f9f97, "....." },
  [4183] = { "I veri padroni", "Raggiungi ⟦Lakeshire=Borgolago⟧ e consegna la ⟦Helendis Riverhorn's Letter=Lettera di Helendis Sinuocorno⟧ al magistrato Solomon.", "Abbiamo sempre pensato che gli orchi ⟦Blackrock=Roccianera⟧ fossero il prodotto della loro educazione selvaggia. Ciò che abbiamo trovato qui, nella loro terra, racconta un'altra storia.\n\nÈ vero, è la sete di sangue e di conflitto a dar loro forza, ma sono i draghi dello Stormo dei Draghi Neri a controllare gli orchi ⟦Blackrock=Roccianera⟧. Sospettiamo che sia lo Stormo dei Draghi Neri ad alimentare la loro rabbia e la loro ostilità.\n\nPorta questa lettera al magistrato Solomon. Saprà lui cosa fare.\n\n<Helendis ti consegna una lettera sigillata.>", "Salute, {name}. Ci siamo già incontrati? Hai un'aria vagamente familiare.", "<Il magistrato Solomon apre la lettera sigillata di Helendis e comincia a leggere.>", 0xbd06798d, 0xed52da00, 0x543942a4, 0x4e21dce5, 0xd73bb7e3, "....." },
  [4184] = { "I veri padroni", "Raggiungi ⟦Stormwind=Roccavento⟧ e consegna l'appello di Solomon al gran signore Bolvar Fordragon.\n\nBolvar risiede nel Castello di ⟦Stormwind=Roccavento⟧.", "Sono notizie cupe, {name}. Scoprire che i nostri nemici mortali sono solo pedine di una minaccia molto più grande è scoraggiante. ⟦Lakeshire=Borgolago⟧ non potrebbe mai sopravvivere a un attacco congiunto degli orchi ⟦Blackrock=Roccianera⟧ e dello Stormo dei Draghi Neri. Se ⟦Lakeshire=Borgolago⟧ cadesse sotto questa minaccia, poi cadrebbe ⟦Darkshire=Borgoscuro⟧, e dopo? ⟦Goldshire=Borgodoro⟧? ⟦Stormwind=Roccavento⟧ stessa?\n\nDevi portare subito queste informazioni al gran signore Bolvar Fordragon, a ⟦Stormwind=Roccavento⟧! Se questo non basta a meritare l'aiuto di ⟦Stormwind=Roccavento⟧, niente lo farà e tutto sarà perduto.", "Cosa ti porta al Castello di ⟦Stormwind=Roccavento⟧?", "Draghi? Impossibile!", 0xbd06798d, 0x7d939500, 0x5a607832, 0x46dba375, 0xdc21b8a7, "....." },
  [4185] = { "I veri padroni", "Parla con il gran signore Bolvar Fordragon dopo aver parlato con ⟦Lady Katrana Prestor=Dama Katrana Prestor⟧.", "Solomon dipinge un quadro desolante. Eppure non possiamo permetterci di mandare in aiuto di ⟦Lakeshire=Borgolago⟧ le nostre truppe, già sparpagliate, sulla base di semplici congetture. Mi servono prove di queste affermazioni prima di poter agire.\n\nParla con Lady Prestor, {name}. È una donna colta e sa molto di draghi e dragoidi. Potrebbe fare luce sulla situazione.", "<Bolvar ti osserva con attenzione.>", "<Bolvar si prende il mento tra le dita, come immerso in profondi pensieri.>\n\nPur rispettando la posizione di Lady Prestor, credo che esista una soluzione a questo dilemma che potrebbe mettere a tacere tutte le nostre preoccupazioni.", 0xbd06798d, 0x1c7cac7b, 0x0605fa2a, 0xf573156f, 0xb8069479, "....." },
  [4186] = { "I veri padroni", "Porta il Bolvar's Decree al magistrato Solomon a ⟦Lakeshire=Borgolago⟧.", "Ti nomino vicesceriffo facente funzione di ⟦Stormwind=Roccavento⟧, {name}.\n\nTorna dal magistrato Solomon a ⟦Lakeshire=Borgolago⟧ e consegnagli questo decreto.", "Notizie da Bolvar?", "Poteva andare peggio, suppongo...\n\n<Il magistrato Solomon ti squadra.>\n\nSembra che il destino di ⟦Lakeshire=Borgolago⟧ poggi interamente sulle tue spalle.\n\n<Noti che il magistrato Solomon sbatte rapidamente le palpebre. Sembra che stia piangendo.>", 0xbd06798d, 0xd9291348, 0x8fe82101, 0x29467338, 0xdaa3533e, "....." },
  [4201] = { "Il filtro d'amore", "Porta 4 Gromsblood, 10 Vena d'Argento Gigante e la ⟦Nagmara's Filled Vial=Fiala Piena di Nagmara⟧ alla padrona Nagmara nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧.", "Oh, le pene d'amore! Il mio caro soldato semplice Rocknot è immune al mio fascino. Sono respinta! C'è da impazzire!\n\nDevi aiutarmi! Noi succubi sappiamo molto dell'amore, e posso preparare una pozione capace di abbattere le mura di ferro attorno al cuore di Rocknot. Per prepararla mi servono questi ingredienti: l'erba gromsblood, Vene d'Argento Giganti dai giganti delle rupi di Azshara e acqua dal cratere delle Sorgenti Calde di Golakka, a Un'Goro. Puoi mettere l'acqua in questa fiala.\n\nTi prego, {name}, aiuta una povera anima nella sua ricerca della felicità!", "Hai gli ingredienti? Il vuoto nel mio cuore minaccia di divorarmi!", "Oh, ce l'hai fatta! Ora posso preparare la mia pozione e usarla su Rocknot. Finalmente cederà al mio fascino!\n\nGrazie, {name}. Sei <un/una> <campione/campionessa> dell'amore!", 0x0c588f7b, 0x0039f407, 0x77c49719, 0x918f01f8, 0x128e9506, "....." },
  [4223] = { "I veri padroni", "Parla con il maresciallo Maxwell nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "<Il magistrato Solomon sospira.>\n\nDevi tornare nelle ⟦Burning Steppes=Steppe Ardenti⟧, {name}. Come vicesceriffo di ⟦Stormwind=Roccavento⟧, dovrai fare rapporto al maresciallo Maxwell. Buona fortuna.", nil, "<Il maresciallo Maxwell ride.>", 0xbd06798d, 0xb198a748, 0x6a799072, nil, 0xc32699c8, "...m." },
  [4224] = { "I veri padroni", "Parla con ⟦Ragged John=John il Malconcio⟧ per scoprire la sorte del maresciallo Windsor, poi torna dal maresciallo Maxwell quando avrai finito.\n\nRicordi che il maresciallo Maxwell ti ha detto di cercarlo in una grotta a nord.", "Cosa? Credevi di essere <il/la> prim<o/a>? Quanti soldati dobbiamo ancora perdere prima che ⟦Stormwind=Roccavento⟧ si muova?\n\nAvevamo raccolto un'enorme quantità di informazioni sulla minaccia dei ⟦Blackrock=Roccianera⟧ prima di perdere il nostro comandante, il maresciallo Windsor. Con il maresciallo Windsor se ne sono andate tutte le nostre preziose informazioni.\n\nCi serve quella documentazione. Parla con ⟦Ragged John=John il Malconcio⟧, {name}. Era con Windsor quando sono stati attaccati da una banda di predoni ⟦Blackrock=Roccianera⟧. L'ultima volta è stato visto in una grotta a nord.", "Hai già parlato con John?", "Avrei potuto avvertirti, ma che divertimento ci sarebbe stato?", 0xbd06798d, 0xe71a4237, 0xeaa13190, 0xc653067b, 0xc3b308c7, "....." },
  [4241] = { "Il maresciallo Windsor", "Raggiungi il ⟦Blackrock Mountain=Massiccio Roccianera⟧, a nord-ovest, ed entra nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧. Scopri che fine ha fatto il maresciallo Windsor.\n\nRicordi che ⟦Ragged John=John il Malconcio⟧ ha detto che Windsor è stato trascinato in una prigione.", "Quindi quel codardo buono a nulla dice che Windsor è vivo, eh?\n\nPreparati, vicesceriffo: andrai a cercarlo. Se Windsor è vivo, devi riportarlo indietro. Se è morto, voglio una prova.\n\n<Maxwell ride.>\n\nScommetto che cominci a stancarti di sentirtelo dire, vero?", nil, "Dov'è? Lo ammazzo!", 0xfc494245, 0x3384adf6, 0xeaea3da0, nil, 0x512c23ab, "...m." },
  [4242] = { "Speranza perduta", "Dai la brutta notizia al maresciallo Maxwell.", "Bolvar è un idiota. Stavo raccogliendo le sue preziose «prove» per potergliele ficcare in gola.\n\nÈ un buffone cieco. La prova sta a due passi da lui e non la vede.\n\nQuanto ai miei dati, sono perduti. Spariti. Irrecuperabili.\n\nSe mai troverò Ironfoe e uscirò da questo labirinto, la mia prima tappa sarà ⟦Stormwind=Roccavento⟧, per piantare il mio martello in mezzo agli occhi di quel rettile.\n\nLasciami, {name}.", nil, "A quanto pare è impazzito.\n\n<Maxwell china il capo in segno di lutto.>\n\nÈ un peccato che un guerriero un tempo fiero e nobile sia ridotto a un pazzo farneticante. IMMAGINO che siamo finiti in un vicolo cieco...\n\nDevo ricompensarti per i tuoi sforzi fin qui, {name}.", 0x18d81581, 0xaf9e4272, 0x1149b9ac, nil, 0x9d83dbab, "...m." },
  [4243] = { "Sulle tracce di ⟦A-Me 01=E-Mi 01⟧", "Trova ⟦A-Me 01=E-Mi 01⟧ nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Purtroppo è successo qualcosa a una delle mie invenzioni migliori. Hai visto gli scoiattoli meccanici, vero? Ecco, per avvicinarmi alle scimmie del ⟦Un'Goro Crater=Cratere di Un'Goro⟧ ho creato una scimmia meccanica che si mescolasse ai loro simili: la chiamo ⟦A-Me 01=E-Mi 01⟧.\n\nAl posto degli occhi ha gemme divinatorie, così potevo vedere tutto ciò che vedeva lei. È arrivata alla ⟦Fungal Rock=Roccia del Fungo⟧, la tana delle scimmie, poco a est di qui, ed è lì che ho perso il contatto. L'ultima cosa che ho visto è stato uno dei loro maschi alfa che le correva incontro per salutarla!\n\nPuoi aiutarmi a ritrovarla?", nil, "Esaminando ⟦A-Me 01=E-Mi 01⟧, noti due enormi ammaccature che rovinano quello che Karna considera evidentemente un congegno ben costruito. Un'ammaccatura decora la spalla di ⟦A-Me 01=E-Mi 01⟧, l'altra è sulla testa.\n\nIndagando più a fondo, sembra che nei suoi componenti non scorra alcuna energia.", 0x7c38c0dd, 0x54e97f2d, 0x2acc1457, nil, 0xd5a67418, "...m." },
  [4244] = { "Sulle tracce di ⟦A-Me 01=E-Mi 01⟧", "Trova un ⟦Mithril Casing=Rivestimento di Mithril⟧ e torna da ⟦A-Me 01=E-Mi 01⟧, nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Indagando ancora un po', trovi un pannello che si apre scorrendo. Sopra alcuni cavi c'è scritto chiaramente: \"Sostituire il ⟦Mithril Casing=Rivestimento di Mithril⟧ e spegnere e riaccendere\".\n\nMentre ti prendi un momento per rimettere a posto il pannello, ti chiedi se sarà davvero così semplice riparare ⟦A-Me 01=E-Mi 01⟧ e riportarla da ⟦Karna Remtravel=Karna Errasogni⟧, vicino al Rifugio dei Grant.\n\nSolo provando lo saprai.", "Il pannello in cui va inserito il rivestimento di mithril è ancora ben chiuso. Il resto di ⟦A-Me 01=E-Mi 01⟧ rimane inerte.", "Togli di nuovo il pannello dalla schiena di A-Me 01 ed estrai con cura il vecchio rivestimento di mithril, che sembra bruciato. Quello nuovo scivola facilmente al suo posto. Se il problema era davvero il rivestimento di mithril, non ti resta che spostare l'interruttore su \"Spento\" e poi di nuovo su \"Acceso\".", 0x7c38c0dd, 0xbfa92269, 0x13b407a4, 0xcc306a17, 0xaabfcb7d, "....." },
  [4245] = { "Sulle tracce di ⟦A-Me 01=E-Mi 01⟧", "Riaccompagna ⟦A-Me 01=E-Mi 01⟧ da ⟦Karna Remtravel=Karna Errasogni⟧, nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Controllando di essere pront<o/a> a riaccompagnare ⟦A-Me 01=E-Mi 01⟧ da ⟦Karna Remtravel=Karna Errasogni⟧, sposti l'interruttore su \"Spento\". Dopo un'altra occhiata intorno per assicurarti che nessuno dei gorilla stia arrivando, ti prepari a vedere che cosa succede quando riporti l'interruttore su \"Acceso\".\n\nÈ la tua ultima occasione... sei sicur<o/a> di volerlo fare?", "Sei riuscit<o/a> ad aiutare A-Me? Il rivestimento di mithril distrutto di cui parlavi era una buona ipotesi sul guasto. Sono sicura che se lo sostituisci si riattiverà e potrà tornare a casa.", "Oh, ce l'hai fatta! Meraviglioso! Grazie, {name}.\n\nOh, la mia povera A-Me. Guarda quante ammaccature. Con un po' di lavoro la rimetteremo in perfetta efficienza.\n\nGrazie ancora, {name}. Lo apprezzo davvero.", 0x7c38c0dd, 0x7bc069c4, 0xef525037, 0xd8a1a554, 0xa0ae5ea0, "....." },
  [4261] = { "Lo spirito antico", "Scorta Arei in salvo, poi parla con ⟦Kayneth Stillwind=Kayneth Ventocalmo⟧ a ⟦Forest Song=Cantaselva⟧, nella parte orientale di ⟦Ashenvale=Valtetra⟧.", "Un tempo ⟦Felwood=Vilbosco⟧ era una terra pacifica e serena... finché la Legione non se ne impadronì. Gli infernali, la distruzione, il caos...\n\nIl teschio di Gul'dan fece sì che qui nessuno venisse risparmiato. Tutto cadde preda della corruzione.\n\nAncora oggi, da spirito, mi ritrovo in trappola, a sopportare la sofferenza di questa terra. Aiutami a ritrovare la strada di casa. Ti prego, {name}, dimmi che guiderai uno spirito antico lontano da qui, dove potrà finalmente riposare.\n\nQuando avrò ritrovato la libertà, cerca ⟦Kayneth Stillwind=Kayneth Ventocalmo⟧, un druido che vive a ⟦Forest Song=Cantaselva⟧, a est.", "Che cosa hai visto in questa terra corrotta?", "Sì, {name}. ⟦Felwood=Vilbosco⟧ ha attraversato molte sofferenze. Grazie per ciò che hai fatto.\n\nUn giorno forse potremo strappare ⟦Felwood=Vilbosco⟧ alla corruzione; ogni gesto gentile aiuta.", 0xf60d4691, 0xf3e6d0be, 0x898bc0e8, 0xb22926ad, 0x5a009e5c, "....." },
  [4262] = { nil, "Uccidi ⟦Overmaster Pyron=Maestro Supremo Piron⟧ e torna da Jalinda Sprig.\n\nRicordi che Jalinda parlava di Pyron a guardia della cava. Forse dovresti cercare lì?", "Gli ultimi cinque maghi che ho mandato a ficcanasare nel ⟦Blackrock Mountain=Massiccio Roccianera⟧ sono tornati belli croccanti, con una permanente arancione da gnomo, o peggio.\n\n<Jalinda raccoglie un po' di cenere da terra e la lascia andare nell'aria.>\n\nUn bastardo in particolare, ⟦Overmaster Pyron=Maestro Supremo Piron⟧, sembra creare parecchi problemi. Dobbiamo eliminare quell'elementale, così che la nostra squadra di spedizione possa farsi strada nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧!\n\nFa la guardia all'ingresso della cava di ⟦Blackrock=Roccianera⟧.", "<Jalinda sembra fissarti la testa.>", "Incendius? Oh, cielo...", 0x3d05b08b, 0xc6e54e09, 0x41ef67d4, 0xfe41a547, 0x1d836ddd, "e...." },
  [4263] = { nil, "Trova ⟦Lord Incendius=Sire Incendius⟧ nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e distruggilo!", "Sei sicur<o/a> che Pyron abbia detto «Incendius» quando è morto?\n\n<Jalinda deglutisce a fatica.>\n\nSi dice che lord Incendius sia un servitore di Ragnaros! Oh, cielo, oh, cielo... e adesso cosa facciamo?\n\nCredi di poter affrontare un'altra missione? Non ho nessun altro da mandare, {name}!\n\nNon riusciremo mai a far entrare una squadra se Incendius continua a far risorgere Pyron dalle ceneri.\n\nDovrai trovare e distruggere lord Incendius!", "Il mostro è morto??", "Oh, cielo! Sei <sicuro/sicura> che Incendius abbia detto «Ragnaros»?\n\n<Jalinda ti porge qualcosa e ti dà un colpetto sul polso mentre sprofonda nei suoi pensieri.>", 0x0aa8e793, 0x60dd505c, 0x47a4390d, 0x20a3fc8b, 0x0d0d9cfd, "e...." },
  [4264] = { "⟦A Crumpled Up Note=Nota Spiegazzata⟧", "Forse ti sei imbattut<o/a> in qualcosa che il maresciallo Windsor vorrebbe vedere. Dopotutto, forse c'è ancora speranza.", "La nota è coperta di macchie. Il testo è a malapena leggibile, ma riesci a distinguere quanto segue:\n\n...dolce ironia...\n\n...la caduta dell'⟦Alliance=Alleanza⟧ spezzata...\n\n...se non fosse per la diligenza del generale Angerforge, forse non avremmo mai scoperto lo schema della cifratura...\n\n...Argelmach ha quasi finito di decifrare gli appunti di Windsor.\n\nIl nostro signore sorgerà dalle profondità e schiaccerà chiunque rimanga...\n\n-Imperatore Dagran Thaurissan.", "<Il maresciallo Windsor osserva la nota che hai in mano.>\n\nCos'hai lì, {name}?", "<Il maresciallo Windsor prende la nota e comincia a leggere.>", 0x9789540e, 0x96684b0f, 0xbb86b357, 0x156cf5b2, 0xdaeb689e, "....." },
  [4265] = { "Liberato dall'alveare", "Libera Raschal dall'alveare degli Zukk'ash.\n\nTorna da ⟦Ginro Hearthkindle=Ginro Cuorfavilla⟧ alla Roccaforte di Piumaluna e digli che Raschal è vivo e sta bene.", "Quando lo tocchi, il baccello si apre un poco e rivela un elfo della notte, sorprendentemente ancora vivo. Sembra in buona salute, anche se profondamente stordito. Mentre lo aiuti a scendere dal baccello, si rianima.\n\n\"Grazie a Elune, mi hai salvato, amico! Io... io sono Raschal, e mi sono risvegliato paralizzato dentro questo baccello dopo che questi insetti mi hanno sopraffatto. Ti ha mandato la roccaforte?\"\n\nSembra che tu abbia trovato il corriere scomparso!", "Hai qualcosa da riferire, {name}?", "Bentornat<o/a> a casa, {name}. Raschal si è presentato poco fa e mi ha raccontato cos'è successo.\n\nIo... no, l'intera roccaforte non sa nemmeno come cominciare a ringraziarti per la tua grande impresa; Raschal sarebbe morto senza il tuo aiuto tempestivo, e ce lo hai dato senza nemmeno un accenno a un compenso da mercenario. Porti il segno di <un/una> ver<o/a> eroe. Sappi che in ⟦Ginro Hearthkindle=Ginro Cuorfavilla⟧ avrai sempre un amico.", 0xe090d26e, 0xc1b8edb5, 0x3c699a4e, 0x2ff3a2d1, 0x73a57ae8, "....." },
  [4266] = { "Accoglienza da eroe", "Parla con ⟦Shandris Feathermoon=Shandris Piumaluna⟧ alla Roccaforte di Piumaluna.", "{name}, la generale ⟦Shandris Feathermoon=Shandris Piumaluna⟧ vorrebbe parlarti di persona. Senza dubbio vuole ringraziarti per il servizio reso alla roccaforte, ma so che vuole anche parlarti delle creature insettoidi che tu e Raschal avete affrontato nel sud di Feralas. I rapporti su quegli insetti Zukk'ash sono... a dir poco spaventosi.\n\nLa generale Feathermoon ti aspetta nell'edificio principale.", nil, "{name}, ti ringrazio di cuore per l'aiuto che ci hai dato. Il tuo coraggio di fronte a forze soverchianti meriterebbe una ricompensa mille volte più grande. Tuttavia, spero che accetterai questa a nome dell'intera roccaforte.\n\nOra, se permetti... vorrei chiedere il tuo aiuto ancora una volta. Alla luce della scoperta dell'alveare degli Zukk'ash qui a Feralas, credo che tu sia la scelta migliore per questa missione.", 0xfc173165, 0x7bd0a992, 0xf15db714, nil, 0x846faacd, "...m." },
  [4267] = { "L'ascesa dei silitidi", "Porta il ⟦Raschal's Report=Rapporto di Raschal⟧ a ⟦Gracina Spiritmight=Gracina Granspirito⟧ a Darnassus.", "Ti affido una copia del rapporto che Raschal ha redatto sull'infestazione del sud-est di Feralas. Mentre il rapporto principale viene archiviato a Darnassus, voglio che tu consegni questa copia a una collaboratrice del Protectorate. Si chiama ⟦Gracina Spiritmight=Gracina Granspirito⟧; è una sacerdotessa che risiede nel ⟦Temple of the Moon=Tempio della Luna⟧ a Darnassus. Conosce bene questo genere di creature, e se ricevesse questo rapporto ne trarremmo tutti beneficio.\n\nPuoi andare. Buona fortuna, {name}; che Elune vegli su tutti noi.", "Benvenut<o/a> in questo tempio benedetto, amico. Il tuo arrivo dalla Roccaforte di Piumaluna mi era stato predetto. Hai il rapporto che ⟦Shandris Feathermoon=Shandris Piumaluna⟧ ti ha chiesto di portare?", "Noi elfi della notte conosciamo il terrore descritto in questo rapporto. Shandris ha fatto bene a mandare da me questo rapporto, e te.\n\nQueste creature divoreranno Feralas in fretta; sono a dir poco una delle peggiori minacce che dovremo mai affrontare. Gli insetti che tu e il corriere avete incontrato sono noti come silitidi. Sono semplici strumenti di una delle più grandi minacce che l'⟦Horde=Orda⟧ e l'⟦Alliance=Alleanza⟧ dovranno mai affrontare.\n\nPrego che avremo la risolutezza di sconfiggerli prima che ci distruggano.", 0x50a8e84e, 0x39f5732a, 0xda5712a8, 0x26cf8b80, 0x993d1f4d, "....." },
  [4281] = { "Una consegna per Thalanaar", "Porta l'Undelivered Parcel a Falfindel Waywarder, a Thalanaar.", "Questo pacco di merci che hai trovato negli accampamenti degli gnoll Raspalegno doveva essere consegnato alla piccola stazione di posta di Thalanaar, nel sud-est di Feralas. Qualunque sia stata la sorte del corriere scomparso, il compito di consegnare il pacco resta incompiuto.\n\nEsaminando il pacco con attenzione, noti un nome scritto a mano sulla confezione: \"Falfindel Waywarder\". Forse è lui il destinatario finale del pacco.", "Benvenut<o/a> a Thalanaar, {class}. Ti serve aiuto di qualche tipo?", "Sia lodata Elune, la consegna dalla Roccaforte di Piumaluna è finalmente arrivata!\n\nLa tua presenza qui mi fa pensare che forse a Raschal, il nostro solito corriere, sia capitata una brutta sorte. Spero che tutto si risolva. So che di recente i Raspalegno sono diventati molto agitati per qualcosa che arriva da sud. Forse è caduto vittima delle terre selvagge laggiù; fa' attenzione, amico.\n\nIn ogni caso, grazie ancora. Ecco il compenso per la consegna di questo pacco.", 0x86751311, 0x715b3184, 0x7c56c873, 0xc22061a9, 0x3e39cede, "....." },
  [4282] = { "Un briciolo di speranza", "Riporta le ⟦Marshal Windsor's Lost Information=Informazioni Perdute del Maresciallo Windsor⟧.\n\nIl maresciallo Windsor crede che le informazioni siano in mano a ⟦Golem Lord Argelmach=Argelmach il Signore dei Golem⟧ e a ⟦General Angerforge=Generale Forgiarabbia⟧.", "<Il maresciallo Windsor agita la nota, eccitato.>\n\nTi rendi conto di cosa significa, {name}?\n\nForse non è tutto perduto! Da quel che riesco a capire, le informazioni sono in mano a due nani ⟦Dark Iron=Ferroscuro⟧: il generale Angerforge e il signore dei golem, Argelmach. Ho la sensazione che non ce le consegneranno solo perché lo chiediamo gentilmente.\n\nSpero che tu sia pront<o/a> a combattere.\n\nVa' e trova questi due furfanti! Distruggili e riportami le mie informazioni perdute.", "Presto questo grande inganno sarà finito.", "<Il maresciallo Windsor ti strappa di mano le due tavolette.>\n\nDobbiamo andarcene da qui!", 0x7552658d, 0x79cbd014, 0x9c91d3ba, 0x9e2f8766, 0x6fc11e3f, "....." },
  [4283] = { "CINQUANTA! SÌ!", "Oralius vuole 50 Medaglione dei ⟦Blackrock=Roccianera⟧. È molto probabile che questi medaglioni si trovino sugli orchi delle ⟦Burning Steppes=Steppe Ardenti⟧.", "Ti svelo un piccolo segreto, soldato. Avvicinati un po'.\n\nSONO L'UNICO SANO DI MENTE QUI!\n\nGuarda questa gente! Ci crederesti che sono tutti matti!? Eppure è così! SVITATI! PAZZI!\n\n<Oralius abbassa la voce.>\n\nTeniamolo tra me, te e il mio amico, il capitano Winky.\n\n<Oralius afferra l'aria e stringe.>\n\nComunqueeee... Colleziono distintivi da abbinare alla mia collezione di orecchie di ogre. Il gusto del giorno è l'Orco. Cinquanta. VAI!\n\n<Oralius soffia in un corno.>\n\nSPEDISCI!", "<Oralius parla dentro un orecchio di ogre mozzato piuttosto grande.>\n\nSteppe Ardenti a base, rispondete, base.", "Ce l'hai fatta! La tua ricompensa è: GRATTAMI LA PANCIA! DAI! GRATTALA!", 0x49e363b1, 0x91b56472, 0xed66611f, 0x3c92225b, 0x6d088a18, "....." },
  [4284] = { "Cristalli di potere", "Raccogli 7 Cristalli Energetici per ciascun colore: rosso, blu, giallo e verde. Portali a J.D. Collie, al ⟦Marshal's Refuge=Rifugio dei Grant⟧.", "Sono sicuro che li hai notati, {name}. Sono dappertutto!\n\nDi cosa sto parlando? Ma dei cristalli, naturalmente!\n\nI cristalli... Sono sparsi in tutto il cratere. Quasi tutti li ignorano, ma ho la strana sensazione che racchiudano un potere. È da un po' che ci faccio esperimenti qui, ma non riesco a trovare niente. Be', almeno non ancora.\n\nSenti, sto finendo i cristalli che ho qui: pensi di poterne raccogliere altri per me?", "Me lo sento, sono sulla pista giusta, {name}!", "Ora potrò continuare i miei esperimenti! Grazie, {name}.", 0xedd2dec0, 0xc0276810, 0x019c0134, 0x003104a5, 0x9e8cf347, "....." },
  [4285] = { "Il pilastro settentrionale", "Scopri dove si trova il Pilastro di Cristallo settentrionale nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "A cosa potranno mai servire? Non riesco a togliermelo dalla testa!\n\nMi sta facendo impazzire l'idea che le voci che ho sentito sui pilastri di cristallo siano tutte vere. Chiamami credulone, ma di solito credo a qualunque cosa mi si racconti.\n\nComunque, ho sentito dire che uno dei pilastri di cristallo è piuttosto vicino. Da qualche parte a nord... Ti prego, trovalo, {name}. Io lo so che esistono.", "Hai visitato il pilastro, {name}?", "Lo so che le storie sono vere, {name}.", 0xf3d0a1fe, 0x2bb1828c, 0x8de93a1a, 0x621cc580, 0x3f0cf7a7, "....." },
  [4286] = { "La roba buona", "Raggiungi i ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e recupera 20 Marsupio dei ⟦Dark Iron=Ferroscuro⟧. Torna da Oralius quando avrai finito. Presumi che i nani ⟦Dark Iron=Ferroscuro⟧ dei ⟦Blackrock Depths=Sotterranei di Roccianera⟧ portino con sé questi aggeggi chiamati «marsupi».", "Il capitano Winky dice che i Ferroscuro nei Sotterranei hanno tutta la roba buona. Non è vero, Winky?\n\n<Oralius fa del suo meglio per imitare un pirata.>\n\nARRR, COMPARE! È COSÌ!\n\nVisto cosa intendo? Devi entrare là dentro e riportarmi qualche campione della roba buona.\n\nEntra là dentro e muovi le chiappe!", "Adesso non ho tempo, {name}. Io e Winky abbiamo una riunione.", "<Oralius comincia a frugare nella montagna di marsupi.>\n\nOH, MERAVIGLIOSO!\n\n<Oralius infila il suo nasone nel mucchio e annusa.>\n\nDELIZIOSO! Guarda quante belle cose!\n\nPrendine uno per te, {name}. Ce n'è per tutti.", 0x03b00c96, 0xacbdd946, 0xa0176a01, 0x0f33f571, 0x49389889, "....." },
  [4287] = { "Il pilastro orientale", "Scopri dove si trova il Pilastro di Cristallo orientale nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Durante la mia permanenza qui ho sentito strane voci su misteriosi pilastri che si troverebbero nelle zone selvagge del cratere, {name}. Immagino che siano piuttosto grandi, con l'interno rivestito di cristalli.\n\nAnche se non ne ho mai visto uno, non posso fare a meno di pensare che le voci siano vere, e che i pilastri abbiano qualcosa a che fare con tutti i cristalli che abbiamo trovato.\n\nPerché allora non mi aiuti a placare la mia curiosità? A quanto pare ce n'è uno nella zona orientale del cratere. Pensi di riuscire a trovarlo?", "Hai visitato il pilastro, {name}?", "Un'Goro è un posto così strano, {name}. Quando entri nel cratere, è come trovarsi in un mondo completamente diverso...", 0x4dda2441, 0xf431d0bd, 0x88915476, 0x621cc580, 0x1d19888e, "....." },
  [4288] = { "Il pilastro occidentale", "Scopri dove si trova il Pilastro di Cristallo occidentale.", "Finora i miei esperimenti non hanno dato alcun risultato positivo, {name}. Non posso fare a meno di sperare che tu trovi una soluzione cercando uno dei pilastri di cui ho sentito parlare.\n\nForse se combinassimo certi colori presso di loro... ma sto correndo troppo. Prima troviamoli!\n\n{name}, cerca nella zona occidentale del cratere; si dice che un pilastro si trovi da qualche parte da quelle parti.", "Hai visitato il pilastro, {name}?", "Lungo i fianchi del cratere ci sono molte zone nascoste. Prova a esplorare i sentieri tortuosi, se non ti viene in mente nessun altro posto dove cercare, {name}.", 0xa0dbd578, 0xb2bb5879, 0x47fd20e0, 0x621cc580, 0xc9cda7e2, "....." },
  [4289] = { "Le scimmie di Un'Goro", "Porta 2 Pelle di ⟦Un'Goro Gorilla=Gorilla di Un'Goro⟧, 2 Pelle di ⟦Un'Goro Stomper=Pestatore di Un'Goro⟧ e 2 Pelle di ⟦Un'Goro Thunderer=Tuonatore di Un'Goro⟧ a ⟦Torwa Pathfinder=Torwa Trova Vie⟧, all'ingresso del ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Questo cratere ospita molte creature strane: sembrano versioni più nobili delle creature che si trovano nella mia terra natale e oltre. Non so spiegarlo, ma questo luogo grida il nome della Madre Terra. Le rendo omaggio ogni volta che seguo le tracce di una delle sue splendide creature attraverso la conca.\n\nSe anche tu vuoi provare l'illuminazione che accompagna un'impresa simile, va' a nord. Lì troverai grandi scimmie che mettono alla prova la forza di qualsiasi mortale. Portami le loro pelli... dimostra la tua forza.", "Le creature di qui ti hanno già battut<o/a>, {name}?\n\nNon lasciarti scoraggiare così facilmente. Seguire le tracce delle scimmie di Un'Goro e sconfiggerle non è un compito semplice, nemmeno per un grande cacciatore.", "Dunque hai dimostrato di essere forte, abbastanza forte da battere le grandi scimmie di Un'Goro: bene. La sfida era piccola rispetto a Lar'korwi, ma non ti toglierò il merito di una vittoria così grande.\n\nQueste pelli diventeranno splendidi abiti per la mia tribù. Mi hai aiutato e ti sei dimostrat<o/a> degn<o/a>.\n\nPrima di partire per un altro compito, rendiamo lode alla Madre Terra e ringraziamo gli spiriti delle scimmie che hai ucciso: devono sapere che la loro morte non sarà vana.", 0xfa7981d5, 0x51ba79b0, 0x8a6c2536, 0x9a5e61a3, 0x1acd5cfd, "....." },
  [4290] = { "Il pasto di Lar'korwi", "Trova la carcassa dell'ultima preda di Lar'korwi e ruba un ⟦Piece of Threshadon Carcass=Pezzo di Carcassa di Plesiosauro⟧, poi torna da ⟦Torwa Pathfinder=Torwa Trova Vie⟧ nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Una volta, tanto tempo fa, un mio fratello prese un po' di carne da una delle prede di Lar'korwi. Allora non lo sapeva, ma Lar'korwi lo vide dalla foresta. Lar'korwi seguì mio fratello per giorni, distruggendo tutto ciò che toccava. Mio fratello, spaventato, alla fine decise di fuggire dal cratere e lasciarsi Lar'korwi alle spalle.\n\nLar'korwi lo uccise non lontano da questo punto.\n\nSe vuoi provocare Lar'korwi, trova una sua preda fresca e prendine un po' di carne.\n\nPoi torna da me.", "Non prendere alla leggera le mie parole, {name}. Se vuoi davvero affrontare questa creatura, devi essere prudente... e astuto. Ci vorranno grande forza e grande intuito per stanare Lar'korwi e sconfiggerlo.", "Questo andrà benissimo, {name}. Pare che Lar'korwi mangi bene di questi tempi. Anche se mi chiedo dove abbia trovato un plesiosauro da queste parti. Strano.\n\nIn ogni caso, lo terrò io finché non sarai pront<o/a> ad affrontare la bestia. Non preoccuparti per la mia incolumità: sono sicuro che hai fatto arrabbiare Lar'korwi abbastanza da non uccidermi prima di aver assaggiato la tua carne.", 0x0e9e1295, 0x8910cd62, 0x518db117, 0xa0cac4a3, 0x76953a16, "....." },
  [4291] = { "L'odore di Lar'korwi", "Porta 2 Ghiandola di Feromoni di Devasauro a ⟦Torwa Pathfinder=Torwa Trova Vie⟧, vicino all'ingresso del ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "A dire il vero mi sorprende che non sia ancora venuto a cercarti, {name}. Ma va tutto bene, perché ho un ultimo piano che porterà il mostro da noi.\n\nEssere il maschio dominante dà a Lar'korwi il diritto di accoppiarsi con qualunque femmina scelga, e ne sceglie molte. Troverai molte uova di devasauro a ovest di qui. Avvicinati e dovresti provocare l'attacco delle sue compagne. Le femmine emettono un odore terribile da una ghiandola nella testa, che fa capire ai maschi che sono pronte ad accoppiarsi. Portami due di quelle ghiandole.", "Sta' attent<o/a>, {name}. Avvicinarti a un qualunque nido di uova provocherà di sicuro le madri... anche se ti sei già procurat<o/a> una ghiandola da una di loro. Le madri possono essere letali quanto lo stesso Lar'korwi quando lottano per proteggere i piccoli. Ma se ci riesci, avremo un modo sicuro per far uscire Lar'korwi dal suo nascondiglio.", "Ah, ottimi esemplari, {name}. Le due ghiandole che hai trovato dovrebbero essere perfette per attirare Lar'korwi allo scoperto. Non vedo l'ora di sapere come finirà il tuo scontro con il mostro. È una creatura enorme, con artigli affilati come le lame migliori. Lo guarderai negli occhi e conoscerai la morte.", 0x8285d67b, 0xd133ef44, 0xa84a2745, 0xe71cf681, 0x056dbb9f, "....." },
  [4292] = { "L'esca per Lar'korwi", "Usa il contenuto della ⟦Torwa's Pouch=Sacca di Torwa⟧ per evocare Lar'korwi e sconfiggilo. Poi porta la ⟦Lar'korwi's Head=Testa di Lar'korwi⟧ a ⟦Torwa Pathfinder=Torwa Trova Vie⟧, vicino all'ingresso del ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Questa sarà la parte più difficile, perché il piano è piuttosto complicato. A nord di qui troverai un piccolo sentiero che sale sulle montagne. È lì che ho visto Lar'korwi l'ultima volta. Capirai di essere nel posto giusto dalle tante ossa di creature enormi che un tempo si aggiravano da quelle parti. Prendi la carne che hai recuperato e mettila lì. Poi strofina sulla carne questa miscela che ho preparato. Se le due esche mescolate insieme non attireranno Lar'korwi, allora non conosco altro che possa farlo.", "Non lasciarti sopraffare dalla paura, {name}. La paura è la grande traditrice... devi restare forte!\n\nPrendi la carne, mettila nella piccola valle e poi usaci sopra la ghiandola. Solo allora la morte verrà a cercarti.", "Sia lodata la Madre Terra! Ce l'hai fatta! Onore a te, {name}. Hai dimostrato di essere <un/una> grande <cacciatore/cacciatrice> a tutti gli effetti. Il tuo spirito è forte. Il tuo coraggio non ha eguali. E la tua forza si è temprata. Mi inchino alla tua abilità.\n\nSolo i più grandi dei miei antenati avrebbero potuto compiere un'impresa tanto incredibile. Congratulazioni.", 0xd073bce4, 0xadd6eb61, 0xf65328ef, 0xe006d62f, 0x9534f0ab, "....." },
  [4293] = { "Un campione di melma...", "Raccogli Campioni di Melma di ⟦Felwood=Vilbosco⟧ da una qualsiasi delle melme di ⟦Felwood=Vilbosco⟧. Poi, con l'attrezzatura per le analisi accanto al chimico Fuely a ⟦Undercity=Sepulcra⟧, scopri quali dei tuoi campioni sono i più corrotti. Porta al chimico Fuely 5 Campione di ⟦Felwood=Vilbosco⟧ Corrotto tra quelli che trovi.", "⟦Felwood=Vilbosco⟧ è una foresta molto a nord delle ⟦Barrens=Savane⟧, ancora più lontana di ⟦Ashenvale=Valtetra⟧. Lì si trovano melme tutt'intorno a pozze d'acqua benedette dal tocco del Vil. Il Flagello ha decimato la zona con attacchi di Infernali e altre magie demoniache: si dice che le melme siano risalite dalla terra durante quegli attacchi.\n\nRaccogli campioni delle melme di ⟦Felwood=Vilbosco⟧ e useremo l'attrezzatura per le analisi qui accanto a me per creare un gruppo di controllo per i nostri test sugli altri campioni che raccoglierai.", "Mi servono almeno cinque campioni corrotti per il nostro gruppo di controllo, {name}. Continua a raccogliere campioni di melma di ⟦Felwood=Vilbosco⟧ finché non potrai darmi ciò che ci serve. Lo decreta Lady Sylvanas...", "Ah, eccellente. Questi campioni andranno benissimo. Ti ringrazio per l'aiuto.\n\nUna volta raccolti tutti i campioni di melma, potremo stabilire di più. Comincio a sospettare che l'intuizione di Lady Sylvanas non solo fosse corretta, ma più acuta di quanto persino lei potesse prevedere. Questi campioni sono molto interessanti. Solo a vedere come hanno reagito ai miei composti... mmm, sì, dovremo senz'altro indagare a fondo.", 0xdbdc006f, 0xb587688e, 0x0d16c5f9, 0xc2957eaf, 0x175de1db, "....." },
  [4294] = { "... e una partita di melma", "Raccogli i Campioni di Melma di Un'Goro da una qualsiasi delle melme del ⟦Un'Goro Crater=Cratere di Un'Goro⟧. Poi, con l'attrezzatura di analisi accanto al chimico Fuely a ⟦Undercity=Sepulcra⟧, scopri quali campioni sono i più puri. Porta 5 Campione di Un'Goro Puro al chimico Fuely.", "Hai mai sentito parlare del ⟦Un'Goro Crater=Cratere di Un'Goro⟧, {name}? Si trova vicino al deserto di Tanaris ed è un luogo magnifico: rigoglioso, vivo, pieno di creature e di piante.\n\nÈ lì che devi andare. Mi è giunta voce che quel posto sembra del tutto incontaminato da mani estranee. Gli esploratori ne stanno scoprendo i segreti proprio adesso.\n\nVorrei analizzare le melme e le poltiglie che vivono laggiù. Se è vero che non sono corrotte, vorrei vedere come si sono evolute creature del genere.", "Sì, {name}? Come procede la tua ricerca?", "Davvero straordinario, {name}. Questo ⟦Un'Goro Crater=Cratere di Un'Goro⟧ nasconde molti più segreti di quanto pensassi. Chissà cos'altro scopriremo proseguendo con le analisi.\n\nSemplicemente straordinario... guarda la purezza di questi campioni. Mm, mi chiedo cosa possa significare. Sembrano di natura elementale, ma... c'è qualcosa di più. Mi ricordano... gli Dei Antichi. Ne abbiamo trovato tracce in tutta Azeroth, e ora mi chiedo se queste creature non siano in qualche modo legate a loro.\n\nDovremo fare altre analisi.", 0xa4fddbb0, 0x533a2b32, 0x6aa87710, 0x63b9f804, 0xa18a1676, "....." },
  [4295] = { "La birra di Rocknot", nil, nil, "Oh, birra! Ucciderei per un po' di birra dei ⟦Dark Iron=Ferroscuro⟧!! Presto, sto tornando sobrio! Lo so perché la sobrietà mi annebbia la vista... e ti fa somigliare a <un/una> {race} che ho fatto fuori la settimana scorsa!", "Cos'è questo? Ah! Ha l'odore della birra dei ⟦Dark Iron=Ferroscuro⟧! L'alcol mi ha annebbiato la vista, ma capisco che tu, <signore/signora>, sei <un/una> <vero/vera> <amico/amica>!", 0x086856d2, nil, nil, 0xa2c71db2, 0x0d80f610, ".mm..", nil, nil, nil, nil, 0xb3506339 },
  [4296] = { "La Tablet of the Seven", "Porta la ⟦Tablet Transcript=Trascrizione della Tavoletta⟧ a ⟦Maxwort Uberglint=Maxwort Granscintilla⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Sono venuto nelle ⟦Burning Steppes=Steppe Ardenti⟧ seguendo le leggende dei Sette. Erano nani di grande sapere e potere, e se hai sapere e potere, la ricchezza arriva di sicuro.\n\nÈ questo che voglio. La ricchezza!\n\nSe riusciamo a scoprire di più sui Sette, forse possiamo arricchirci insieme. Si dice che le Rovine di Thaurissan custodiscano la Tablet of the Seven, che racchiude il sapere degli antichi nani. Trova la tavoletta, copiane il testo e portamelo. Scopriamo insieme i suoi segreti!", "Hai gli scritti dei Sette, {name}? Hai scoperto i segreti della loro tavoletta?", "Ah, hai trovato la tavoletta! E la tua trascrizione è eccellente! Sei sicur<o/a> di essere <un/una> {class} e non uno scriba?\n\nEcco a te, {name}. Ecco il pagamento che ti avevo promesso.", 0x863c0b42, 0xc0b00f60, 0x910aab7a, 0x793ccb86, 0xfcd7e593, "....." },
  [4297] = { "Pappa per il piccolo", "Porta 5 Costato di ⟦Silvermane Stalker=Inseguitore Peloargento⟧ ad ⟦Agnar Beastamer=Agnar Forgiabestie⟧, nelle Entroterre.", "I draghi fatati sono onnivori: vuol dire che mangiano sia carne sia vegetali. Se quest'uovo deve schiudersi, è meglio farci trovare pronti. Un buon pasto per questi piccoletti sono i costati di carne, crudi e succosi, che tu ci creda o no. Non sono mai riuscito a scoprire perché, ma ha qualcosa a che fare con i piani di Elune per gli elfi... forse dovevano esserne i protettori o qualcosa del genere, che ne so.\n\nPer ora all'uovo ci penso io; perché non mi procuri dei bei costati di inseguitore Peloargento da fargli mangiare quando si sarà schiuso?", "Trovata la carne, {name}? Il tuo uovo qui è quasi pronto a schiudersi. Se il piccolo non fa un primo pasto come si deve, potrebbe non superare la prima settimana, e mi dispiacerebbe davvero.\n\nNon posso mentirti, {name}. Ti invidio per aver avuto quest'uovo. Non farmi pentire di averti dato una mano così.", "Questi andranno benissimo e, se non sbaglio, il tuo uovo è quasi pronto a schiudersi. Che effetto fa? Sai, stai per diventare <padre/madre>! Ah ah, non pensavi di doverti prendere una responsabilità simile, eh?", 0xccaca750, 0xe072dedf, 0xc37f8279, 0x2f58b6a1, 0xcba4d08b, ".....", nil, nil, nil, nil, 0x797e01c8 },
  [4298] = { "Diventare genitore", "Parla con ⟦Agnar Beastamer=Agnar Forgiabestie⟧ nelle Entroterre.", "Accidenti, era molto più pronto di quanto pensassi...", nil, "Ecco, prendi l'uovo... meglio che ce l'abbia tu, così si lega a te e ti considera <il/la> sua <papà/mamma>.\n\nCongratulazioni, {name}. Sei diventat<o/a> genitore... più o meno.", 0xd65f6783, 0xc7b43955, 0x0bc0ac2d, nil, 0xcca17ed2, "...m.", nil, nil, nil, nil, 0x08e439a2 },
  [4300] = { "Armi a lama d'osso", "Porta 8 Artiglio Bianco di Devasauro a Jes'rimon a Orgrimmar.", "Mmm, forse c'è qualcosa che puoi fare per la Mano, ora che me ci penso. Sì, Jes'rimon può usare il tuo aiuto, sicuro.\n\nNel ⟦Un'Goro Crater=Cratere di Un'Goro⟧ ci sono raptor con artigli mortali. Alcuni di quei raptor a volte hanno artigli bianchi invece che neri come la morte. La Mano ha... clienti... a cui piacciono armi fatte con questi artigli. Portami tanti di quegli artigli bianchi e io ti paga buone monete. Se fai abbastanza in fretta, forse io ti aiuta anche in altri modi.", "I miei clienti non sono tanto pazienti, {name}. Hai già preso qualche artiglio?", "Ah, questi vanno bene. Grazie, {name}. E tu sei qui molto prima del bisogno... questo è bene.\n\nForse noi ti fa forgiare un'arma con gli artigli. Che ne dici?", 0x57afe43e, 0x119beaa0, 0x33cb001a, 0x38e4d27f, 0x6de4c6b4, "....." },
  [4301] = { "Il possente U'cha", "Porta la ⟦U'cha's Pelt=Pelle di U'cha⟧ a ⟦Torwa Pathfinder=Torwa Trova Vie⟧, all'ingresso del ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Mentre esploravi Un'Goro, ho visto altre cose che un possente cacciatore come te apprezzerebbe. Una di queste era una scimmia enorme tra gli altri gorilla a nord. Sei già stat<o/a> in quella grotta, ma questa volta, se accetterai il mio compito, mi chiedo se sopravviverai all'incontro.\n\nLo chiamo U'cha, ed è uno dei più grandi figli della Madre Terra, su questo non c'è dubbio. Sconfiggi U'cha e portami la sua pelle. Fallo, e difenderò il tuo diritto di chiamarti un grande cacciatore.", "U'cha... quella bestia era magnifica. Enorme e rossa, con denti grandi come pugnali. Braccia spesse come tronchi d'albero, e veloce come qualsiasi leone di montagna abbia mai visto. Dovresti considerarti fortunat<o/a> ad aver trovato una simile prova di coraggio: il mio popolo poteva passare generazioni senza vedere una creatura del genere.", "Ben fatto, {name}. Questo mi rallegra. Oggi hai compiuto una grande impresa.\n\nU'cha era una delle scimmie più grandi che abbia mai visto. Il fatto che tu abbia superato la sua forza dice molto della tua... e del tuo coraggio.\n\nÈ giusto che ti dia questo in segno di rispetto. Te lo sei guadagnato.", 0xd10aceeb, 0x9d4e6ce7, 0x99670aa0, 0x644bd43d, 0xba2c7c24, "....." },
  [4321] = { "Venirne a capo", "Parla con J.D. Collie tra un momento.", "Le informazioni che mi hai dato sui pilastri sono molto interessanti...\n\nDammi un momento per fare qualche calcolo, {name}. Riparlami tra un attimo e dovrei poterti dare la risposta che stavamo cercando.", nil, "Bene, {name}. È affascinante... Posso solo sperare che i miei diagrammi siano corretti! Ho raccolto tutto in questo manuale, che puoi tenere.\n\nOra credo di poter rispondere a qualunque domanda tu abbia sui cristalli, {name}.", 0x676aa57e, 0x91c74f07, 0x1f2e2222, nil, 0x8af10634, "...m." },
  [4322] = { "Evasione!", "Aiuta il maresciallo Windsor a recuperare il suo equipaggiamento e a liberare i suoi amici. Se ci riesci, torna dal maresciallo Maxwell.", "Dobbiamo andarcene da qui, {name}. Aiutami a recuperare il mio equipaggiamento dal deposito delle provviste e a liberare i miei amici. Se riusciamo a uscire di qui, dovrai raggiungere il ⟦Morgan's Vigil=Presidio di Morgan⟧ e parlare con il maresciallo Maxwell. Ti darà ulteriori istruzioni.", "Sembri esaust<o/a>, {name}. Forse dovresti sederti accanto al fuoco e rilassarti.", "Incredibile, {name}. Semplicemente incredibile. Windsor è passato di qui come una furia nemmeno cinque minuti fa. Fa affermazioni grandiose, ma sostiene che siano supportate dalle sue prove. Ora è diretto a ⟦Stormwind=Roccavento⟧ per affrontare Bolvar e... Lady Prestor.", 0xa1d51782, 0xb27d7145, 0xea606ce3, 0x1cb565cf, 0x3080767e, "....." },
  [4324] = { nil, "Parla con ⟦Yuka Screwspigot=Yuka Giravite⟧ nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Anche se il mio fratellino Ribbly è stato un buono a nulla per tutta la vita, credo che finalmente valga qualcosa! Ma... potremmo aver bisogno del tuo aiuto per incassare il nuovo valore di Ribbly.\n\nMia sorella Yuka lo cerca da settimane e l'ha seguito fino alle ⟦Burning Steppes=Steppe Ardenti⟧. Mi ha mandato un messaggio chiedendo qualche aiutante a pagamento.\n\nAllora, che ne dici? Vuoi dare una mano? Se sì, parla con mia sorella. La troverai rintanata nel ⟦Flame Crest=Cimiero Ardente⟧, una grotta a nord-ovest del ⟦Dreadmaul Rock=Masso dei Maglioinfame⟧.", nil, "Sì, sto cercando mio fratello. Dobbiamo trovarlo e riportarlo indietro, povero caro.\n\nMa se non riusciamo a portarlo tutto intero... allora basterà la sua testa.", 0xefbe9d01, 0x2a4bb9fd, 0x67943a49, nil, 0x307322ac, "e..m." },
  [4341] = { nil, "Raggiungi i ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e trova ⟦Kharan Mighthammer=Kharan Fortebraccio⟧.\n\nIl re ha detto che Kharan è tenuto prigioniero laggiù: forse dovresti cercare una prigione.", "Sei <stato/stata> tra le fumanti rovine di Thaurissan? Ti è capitato di imbatterti in un miserabile babbeo di nome ⟦Kharan Mighthammer=Kharan Fortebraccio⟧? Il nano che avrebbe dovuto vegliare sulla mia bambina!\n\n<Il re singhiozza.>\n\nE ora lei non c'è più, {name}!\n\nHo fatto rivoltare le Steppe da cima a fondo ai miei uomini. L'unico indizio che hanno su dove si trovi mia figlia è che potrebbe essere nei Sotterranei. Per quanto ne so, potrebbe essere morta!\n\nPare che Kharan sia tenuto prigioniero laggiù... trovalo! Voglio risposte!", nil, "Ti prego, lascia che ti spieghi.", 0xfe80aadb, 0xe86ea627, 0x6a2356bf, nil, 0x0d7b100b, "e..m." },
  [4342] = { "Il racconto di Kharan", "Ascolta ⟦Kharan Mighthammer=Kharan Fortebraccio⟧ mentre racconta la sua storia.", "Ti prego, ascoltami prima di giudicarmi!", "Lasciami finire di raccontare la mia storia.", "Come vedi, non avrei potuto fare nulla.", 0x0a682832, 0x0f6bf74a, 0x58166ce6, 0x58f6bd04, 0x0cb1cd70, "....." },
  [4361] = { "Latore di cattive notizie", "Torna a ⟦Ironforge=Forgiardente⟧ e porta la brutta notizia a re Magni Bronzebeard.", "Devi riportare queste informazioni a re Magni, {name}. Lui saprà cosa fare!", nil, "<Re Magni batte il pugno con rabbia.>", 0x122e45b2, 0xfdee527e, 0x8f5b34e1, nil, 0xc4bc22b7, "...m." },
  [4362] = { "Il destino del regno", "Torna nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e salva la principessa Moira Bronzebeard dalle grinfie malvagie dell'imperatore Dagran Thaurissan.", "A quanto pare il mio vecchio avversario, Dagran Thaurissan, tiene me e il regno di ⟦Ironforge=Forgiardente⟧ alla sua mercé.\n\nForse sei la mia ultima speranza, {name}. Devi salvare la mia cara figlia, Moira!\n\nC'è un solo modo per essere certi di spezzare l'incantesimo che Thaurissan ha lanciato su Moira: ucciderlo.\n\nE, {name}, non farle del male! Ricorda, è controllata da Thaurissan! Ciò che potrebbe fare o dire è frutto del malvagio incantesimo di Thaurissan!", nil, "<La principessa Bronzebeard piange la perdita dell'imperatore Dagran Thaurissan.>\n\nPerché???", 0x38ebdf89, 0x02d49ae4, 0xfd892b70, nil, 0x6bf03c5b, "...m." },
  [4363] = { "La sorpresa della principessa", "Torna a ⟦Ironforge=Forgiardente⟧ e parla con re Magni Bronzebeard.", "Thaurissan era un nano grande e onorevole. Hai rovinato la mia vita e quella del figlio che porto in grembo!\n\n<Pensi che la principessa Bronzebeard possa ancora soffrire per gli effetti residui dell'incantesimo dell'imperatore.>\n\nTorna a ⟦Ironforge=Forgiardente⟧ e di' a mio padre che l'erede del regno di ⟦Ironforge=Forgiardente⟧ sarà un nano ⟦Dark Iron=Ferroscuro⟧.\n\nChe lo approvi o no, così sarà.", nil, "<Re Magni Bronzebeard è visibilmente sconvolto.>\n\nSembra che Thaurissan abbia vinto, persino da morto.\n\nPuoi andare, {name}. Prima di partire, scegli la tua ricompensa dal tesoro reale.\n\n<Re Bronzebeard sprofonda nel trono a rimuginare su questa bizzarra piega degli eventi.>", 0xb23f23f9, 0x48ee78a7, 0x22918331, nil, 0x7dd3a9ac, "...m." },
  [4402] = { "Lo ⟦Cactus Apple Surprise=Sformato di Mele di Cactus⟧ di Galgar", "Porta a Galgar 10 Mela di Cactus. Ricordi che ha detto che si trovano vicino ai cactus.", "Fa proprio caldo qui nella ⟦Valley of Trials=Valle delle Sfide⟧.\n\n<Galgar si asciuga la fronte.>\n\nSe solo avessi qualche mela di cactus, potrei preparare il mio famoso sformato di mele di cactus! Niente ti rinfresca più in fretta di un pezzo di quella delizia.\n\nFacciamo così, {name}. Se mi porti 10 mele di cactus, ti preparerò qualche porzione di sformato di mele di cactus da portare nelle tue avventure, e in più un manuale di addestramento gratis. Se ti interessa, trovi le mele di cactus vicino alle piante di cactus qui intorno.", "Hai finito di raccogliere le mele di cactus?", "Magnifico, {name}! Come promesso, ecco il tuo sformato di mele di cactus. Scegli anche uno di questi manuali di addestramento. Ne ho in abbondanza per tutti.", 0xaed68386, 0x6d1de7e5, 0x567922ac, 0x15808a02, 0x967033b1, "....." },
  [4421] = { "La corruzione dei Giadafulgida", "Uccidi 11 Jadefire Felsworn, 9 Jadefire Shadowstalker, 9 Jadefire Rogue e Xavathras. Torna da ⟦Eridan Bluewind=Eridan Brezzastrale⟧ nel ⟦Felwood=Vilbosco⟧ quando avrai finito.", "Non sono in molti a cercare avventure qui... La corruzione del Vilbosco è diffusa e non risparmia nessuno.\n\nCome membro della ⟦Emerald Circle=Fede di Smeraldo⟧ cerco di guarire questa terra, ma c'è chi vuole che continui a marcire.\n\nParlo dei satiri Giadafulgida che dimorano a nord-ovest di qui, nelle ⟦Ruins of Constellas=Rovine di Constellas⟧. Guidati da un satiro particolarmente crudele di nome Xavathras, continuano a diffondere il morbo a ogni creatura che incontrano.\n\nDobbiamo difendere questa terra che un tempo era nostra. Sconfiggi Xavathras e distruggi i suoi servitori.", "La corruzione qui fa impazzire le creature...", "Liberare il ⟦Felwood=Vilbosco⟧ da Xavathras è solo il primo passo di un lungo percorso. Ci vorrà molto lavoro per riparare i danni che sono stati fatti qui.\n\nSento che qui è all'opera qualcosa di molto più grande dei soli satiri, ma solo il tempo ci rivelerà la verità...", 0x4b5dd118, 0x6b29d3b7, 0x71742f9e, 0x3f3ed819, 0x74334cac, "....." },
  [4441] = { "Antichi avvinti dal vil", "Raggiungi Darnassus e usa la ⟦Eridan's Vial=Fiala di Eridan⟧ per raccogliere una ⟦Vial of Blessed Water=Fiala d'Acqua Benedetta⟧ al ⟦Temple of the Moon=Tempio della Luna⟧. Torna da Eridan con la fiala piena.", "Il flauto che hai trovato è stato intagliato da un antico protettore, uno dei treant alleati che hanno sempre protetto fedelmente gli Elfi della Notte.\n\nI satiri sono riusciti a corrompere tutto ciò con cui sono entrati in contatto, compresi gli antichi che avevano fatto del ⟦Felwood=Vilbosco⟧ la loro casa. Con l'uso del vil, lo spirito dell'antico è stato vincolato e torturato, senza mai essere del tutto liberato. Il vil legame che hai trovato è senza dubbio collegato.\n\nDobbiamo cercare di purificare il flauto, {name}. Portami dell'acqua benedetta dal ⟦Temple of the Moon=Tempio della Luna⟧, a Darnassus.", "Spero che l'acqua liberi lo spirito dell'antico e gli permetta di trovare pace.", "Grazie, {name}. Ora dobbiamo pregare di riuscire a rimediare al danno che è stato fatto...", 0x0bf2df61, 0x19deb1d0, 0x245cd7a7, 0x4938e970, 0x591e149b, "....." },
  [4442] = { "Purificato!", "Parla di nuovo con Eridan tra un momento.", "Con l'acqua di Elune cercherò di purificare il flauto. Dobbiamo porre fine a questa sofferenza...\n\nChe Elune guidi le mie mani e il mio cuore.\n\nParlami di nuovo tra un momento.", nil, "Con l'acqua benedetta ho potuto spezzare il legame tra il flauto e lo spirito dell'antico. Credo però che, se usassi questo flauto in un luogo sacro, potresti riuscire a evocare gli spiriti degli antichi.\n\nPotresti provare con le rovine nella parte meridionale del ⟦Irontree Woods=Bosco di Troncoferro⟧. Un tempo molti treant corrotti abitavano quella zona, ed è possibile che vi dimorino ancora, anche in forma di spirito.", 0xfb3352f9, 0x6d69af82, 0x50ae36f3, nil, 0xfb97c620, "...m." },
  [4449] = { "In trappola!", "Uccidi 8 Dark Iron Geologist e porta 15 pezzi di ⟦Silk Cloth=Tessuto di Seta⟧ alla persona chiusa nel gabinetto nella ⟦Searing Gorge=Gorgia Rovente⟧.", "Ehi! Ehi, tu! Vieni qua!\n\nDevi darmi una mano. Scappavo da quei nani ⟦Dark Iron=Ferroscuro⟧ e mi sono nascosto qui dentro per non farmi vedere. Maledetti geologi bastardi e le loro arti magiche! Devono avermi visto nascondermi, perché un attimo dopo hanno chiuso la porta e mi hanno lasciato qui dentro.\n\nDai una lezione a quei geologi! Oh... e mi procureresti qualche pezzo di tessuto di seta per... per... niente.", "Non ho tutto il giorno! Portami quei pezzi di tessuto di seta! Cioè, i geologi. Prendi quei geologi! Si meritano di sentire la mia... beh... la tua ira.", "Oh, fantastico! E pure morbido al tatto!\n\nCosa? Ah, già... i geologi. Gliele hai suonate, eh? Non so come ringraziarti, {name}. Così avrò un po' di tempo per finire qui dentro... Grazie ancora, {name}.", 0xab9278e3, 0xc0a43cff, 0xc422c491, 0x13a88031, 0x98779dfb, "....." },
  [4450] = { "Il registro da Tanaris", "Prendi la copia del Libro Mastro di Ferrofiz, poi trova gli oggetti elencati prima di andare da ⟦Krinkle Goodsteel=Krinkle Ferrofiz⟧ a Tanaris.", "Ah, sai che c'è? Questo mi fa venire in mente una cosa.\n\nTi va di finire un lavoretto che avevo preso quando ero a Tanaris? È facile...\n\nKrinkle Goodsteel, a ⟦Gadgetzan=Meccania⟧, cercava della roba che si trova qui nella ⟦Searing Gorge=Gorgia Rovente⟧ e in qualche altro posto. Magari potresti dare un'occhiata alla lista e poi portargli tutto?\n\nSe ti interessa, ti faccio scivolare il suo registro sotto la porta. Prendilo e, quando avrai raccolto tutto, riportagli la roba che vuole.", "Sì, sì? Cosa posso fare per te, {race}? Sono molto occupato e ho tanti clienti che chiedono i miei servigi. Magari puoi sbrigarti. Non voglio essere scortese, ma non ho proprio tempo se devo mettermi in pari con tutto il lavoro.", "Oh, ti sei degnat<o/a> di fare un po' del lavoro che avevo chiesto. Eccellente. E io che pensavo che volessi chiedermi di fabbricarti qualcosa.\n\nSono tutti perfetti... e c'è tutto. Grazie, {class}.\n\nForse non guasterebbe darti una piccola ricompensa... mmh, cosa potrebbe esserti utile.", 0xfa56f393, 0xfbaa0d2b, 0xccb4891c, 0x920e8057, 0x3d8ac6bb, "....." },
  [4451] = { "La chiave della libertà", "Esplora la ⟦Searing Gorge=Gorgia Rovente⟧ e trova un uso per la Grimesilt Outhouse Key che hai trovato.", "La piccola chiave d'ottone sembra piuttosto semplice... L'unica cosa che la distingue sono alcune parole incise sulla testa:\n\n\"Latrina dei ⟦Dark Iron=Ferroscuro⟧ - Non duplicare.\"\n\nNon hai idea di che cosa significhi né di dove possa portarti.", "*coff coff*\n\nChi è? Non vedi che sono occupato?", "Ma guarda un po'! Come diavolo hai fatto?! Hai trovato la chiave! Lo sapevo che quei maledetti Ferroscuro la nascondevano, dopo avermi chiuso qua dentro! Grazie mille, {name}. Sei <il/la> migliore! Adesso gira la chiave e fai uscire il vecchio Locheed!", 0x1d423cb0, 0xdf1d614f, 0xe0aab529, 0xd1c3c55d, 0x30438394, "....." },
  [4485] = { "Il Tome of Nobility", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Salve, {name}. Vedo che la tua dedizione resta salda, come la tua fede.\n\nCredo sia giunto il momento che tu parli con Duthorian Rall a ⟦Stormwind=Roccavento⟧. Ci sono altre lezioni che devi imparare, e sento che sei <pronto/pronta>.\n\nCercalo nella ⟦Cathedral of Light=Cattedrale della Luce⟧ e, {name}, prendi sul serio queste lezioni. Hai raggiunto la tua posizione con umiltà e duro lavoro: non deluderci diventando arrogante.\n\nStammi bene.", nil, "Ah, sei tornat<o/a> alla Cattedrale, {name}. Bene. Di recente sono successe molte cose, e vorrei chiedere il tuo aiuto, se ti dimostrerai <degno/degna>.\n\nCi sono in giro molti nemici infidi. Avrò bisogno del tuo aiuto per fermarli.", 0x2923ea98, 0x0f3ca705, 0x454c6c6f, nil, 0x47e1bbd2, "...m." },
  [4486] = { "Il Tome of Nobility", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Bene, bene, bene, guarda <il/la> possente paladin<o/a> in tutta la sua regalità.\n\nScusa, {name}, non volevo offenderti... è che a volte divento un po' geloso quando vedo alcune delle imprese che hai compiuto. Tiza dice che è il mio punto debole, e le ho giurato che ci avrei lavorato su. Solo che a volte è dura, capisci?\n\nMa il motivo per cui volevo parlarti è che Duthorian Rall, a ⟦Stormwind=Roccavento⟧, ha fatto sapere che ti aspetta nella ⟦Cathedral of Light=Cattedrale della Luce⟧ quando sarai <pronto/pronta>. Sembrava importante. Sembrava che stesse succedendo qualcosa.", nil, "Ah, sei tornat<o/a> alla Cattedrale, {name}. Bene. Di recente sono successe molte cose, e vorrei chiedere il tuo aiuto, se ti dimostrerai <degno/degna>.\n\nCi sono in giro molti nemici infidi. Avrò bisogno del tuo aiuto per fermarli.", 0x2923ea98, 0x0f3ca705, 0x3240aaf3, nil, 0x47e1bbd2, "...m.", nil, nil, 0x381e65db, nil, nil },
  [4487] = { "L'evocazione del vildestriero", "Parla con Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "Ah, bene, sei qui. Ti avevo mandato dietro <una/un> <succube/infernale> per attirare la tua attenzione, ma a quanto pare sei arrivat<o/a> prima che ti trovasse. Poco importa.\n\nUltimamente si parla del tuo potere crescente: un bene per te, forse un male per altri. Ma sono dettagli irrilevanti. Il punto è che credo tu abbia dato prova di te, e quindi meriti... eh eh... una sorta di benedizione.\n\nSopra ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧, troverai un uomo di nome Strahad. Credo che le vostre strade si siano già incrociate.", nil, "Dunque hai deciso di onorarmi di nuovo della tua presenza. Che gentilezza.\n\nI miei accoliti si chiedevano se saresti mai venut<o/a>. Ho detto loro che non c'era alcun dubbio. Quando si tratta di potere, ne sei attratt<o/a> come una falena dalla fiamma.", 0x5220fbc8, 0x0c866240, 0xf53d45e1, nil, 0x23773eba, "...m.", nil, nil, 0xe53a38b3, nil, nil },
  [4488] = { "L'evocazione del vildestriero", "Parla con Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "Ah, {name}, ti sei degnat<o/a> di onorarci della tua presenza. Che meraviglia!\n\nSpero che tu non ti aspetti anche di essere servit<o/a> e riverit<o/a>. Il tuo potere cresce in fretta, ma quanto a vera conoscenza e comprensione sei ancora un cucciolo. Se non stai attent<o/a>, la corruzione travolgerà te e la tua debole volontà.\n\nMa vengo al punto: Strahad vuole parlarti. Risiede ancora nella sua torre che domina ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧. Ti consiglio di non metterci troppo.", nil, "Dunque hai deciso di onorarmi di nuovo della tua presenza. Che gentilezza.\n\nI miei accoliti si chiedevano se saresti mai venut<o/a>. Ho detto loro che non c'era alcun dubbio. Quando si tratta di potere, ne sei attratt<o/a> come una falena dalla fiamma.", 0x5220fbc8, 0x0c866240, 0x22753d85, nil, 0x23773eba, "...m." },
  [4489] = { "L'evocazione del vildestriero", "Parla con Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "Tu, {race}! Vieni qui!\n\nSei tu <quello/quella> che chiamano {name}, vero?\n\nLo immaginavo. Sarò breve: il tuo potere sta crescendo, e la cosa non è passata inosservata. E ora è giunto il momento che i tuoi sforzi siano ricompensati.\n\nVa' nelle ⟦Barrens=Savane⟧. Lì, sopra ⟦Ratchet=Porto Paranco⟧, troverai Strahad Farsan: forse ti ricordi di lui? Vuole scambiare due parole con te. Io non perderei tempo.", nil, "Dunque hai deciso di onorarmi di nuovo della tua presenza. Che gentilezza.\n\nI miei accoliti si chiedevano se saresti mai venut<o/a>. Ho detto loro che non c'era alcun dubbio. Quando si tratta di potere, ne sei attratt<o/a> come una falena dalla fiamma.", 0x5220fbc8, 0x0c866240, 0x9e1f9f00, nil, 0x23773eba, "...m." },
  [4490] = { "L'evocazione del vildestriero", "Parla con Strahad Farsan a ⟦Ratchet=Porto Paranco⟧ per imparare a evocare un vildestriero.", "Vorrei darti una ricompensa per la tua pazienza e il tuo duro lavoro. Ma sappi questo: in futuro il potere di evocare un vildestriero sarà molto più difficile da ottenere. Dovrai guadagnartelo... e non sarà facile.\n\nPer ora, va' con il potere di evocare una simile creatura e usalo come meglio credi.", nil, "Buona fortuna, {name}. Non vedo l'ora di rivederti in futuro.", 0x5220fbc8, 0x7950b530, 0x285bb1cf, nil, 0x2dc44b87, "...m." },
  [4491] = { "Un piccolo aiuto dagli amici", "Accompagna Ringo da ⟦Spraggle Frock=Spraggle Pinzapersa⟧ al ⟦Marshal's Refuge=Rifugio dei Grant⟧.\n\nSe Ringo sviene, usa la ⟦Spraggle's Canteen=Borraccia di Spraggle⟧ per rianimarlo.", "Uff... Che caldo...\n\nStavo esplorando questa zona quando, all'improvviso, il caldo è diventato insopportabile. Devo avere un colpo di calore.\n\nTi prego, aiutami a tornare dal mio amico Spraggle al ⟦Marshal's Refuge=Rifugio dei Grant⟧. Credo di stare abbastanza bene da seguirti fin lì.\n\nMi sento un po' frastornato, quindi se dovessi svenire di nuovo, spruzzami addosso un po' d'acqua dalla borraccia di Spraggle. Dovrebbe funzionare, spero...", "Ringo mi ha fatto stare così in pensiero...", "Ringo non è in gran forma, {name}, ma sono felice di riaverlo tutto intero!\n\nGrazie per averlo trovato.", 0x299595aa, 0x19fb72e7, 0xaf0b31ee, 0x99c6cdef, 0x642cc87e, "....." },
  [4492] = { "Disperso!", "Trova Ringo al ⟦Fire Plume Ridge=Rilievo del Magma Colante⟧.", "Devi aiutarmi, {name}! Il mio amico Ringo è partito un po' fa per esplorare il vulcano a sud di qui, ed è via da troppo tempo. Sono davvero preoccupato per lui.\n\nPensi di riuscire a trovarlo? Perché non porti con te la mia borraccia? Se trovi Ringo, di sicuro ne avrà bisogno!", "Co... Cosa?", "Oh... Sono così felice che qualcuno mi abbia trovato...", 0x45101ee2, 0x080f5567, 0xc9277091, 0x3b72f2ea, 0xe7945f5f, "....." },
  [4493] = { "La marcia dei silitidi", "Parla con l'alchimista Pestlezugg a ⟦Gadgetzan=Meccania⟧.", "Sembrerebbe che lo scopo dei silitidi, anzi, la loro ragion d'essere, sia divorare sul loro cammino tutto ciò che non appartiene al loro ecosistema. Hanno un unico obiettivo, ed è per questo che sono una grave minaccia per ogni forma di vita su Azeroth.\n\nCiò che abbiamo visto finora non è che la fase iniziale. Sospetto che la loro forza venga da più in profondità a Kalimdor: dal ⟦Un'Goro Crater=Cratere di Un'Goro⟧. Va' a ⟦Gadgetzan=Meccania⟧, nel deserto di Tanaris, e parla con l'alchimista Pestlezugg. Raccontagli la mia teoria; di certo ci aiuterà a combattere i silitidi.", nil, "Sì, avevo capito che ti ha mandato Gracina. La tua esperienza nella lotta contro queste bestiacce non ha prezzo; per quanto ne so, nessuno ha mai avuto a che fare con la loro specie. Quanto all'idea di Gracina che il ⟦Un'Goro Crater=Cratere di Un'Goro⟧ sia il loro cuore... forse è così. Un'Goro è una giungla misteriosa e pericolosa a ovest di qui. Forse è anche un passo avanti per capire che cosa siano davvero i silitidi.", 0x38486200, 0x2fa7b4e6, 0xff4ae737, nil, 0x2146fcf0, "...m." },
  [4494] = { "La marcia dei silitidi", "Parla con l'alchimista Pestlezugg a ⟦Gadgetzan=Meccania⟧.", "Sembrerebbe che lo scopo dei silitidi, anzi, la loro ragion d'essere, sia divorare sul loro cammino tutto ciò che non appartiene al loro ecosistema. Hanno un unico obiettivo, ed è per questo che sono una grave minaccia per ogni forma di vita su Azeroth.\n\nCiò che abbiamo visto finora non è che la fase iniziale. Sospetto che la loro forza venga da più in profondità a Kalimdor: dal ⟦Un'Goro Crater=Cratere di Un'Goro⟧. Va' a ⟦Gadgetzan=Meccania⟧, nel deserto di Tanaris, e parla con l'alchimista Pestlezugg. Raccontagli la mia teoria; di certo ci aiuterà a combattere i silitidi.", nil, "Sì, avevo capito che ti ha mandato Zilzibin. La tua esperienza nella lotta contro queste bestiacce non ha prezzo; per quanto ne so, nessuno ha mai avuto a che fare con la loro specie. Quanto all'idea di Zil che il ⟦Un'Goro Crater=Cratere di Un'Goro⟧ sia il loro cuore... forse è così. Un'Goro è una giungla misteriosa e pericolosa a ovest di qui. Forse è anche un passo avanti per capire che cosa siano davvero i silitidi.", 0x38486200, 0x2fa7b4e6, 0xff4ae737, nil, 0x482c0f64, "...m." },
  [4495] = { "Un buon amico", "Trova Iverron presso la caverna a nord.", "Un mio amico di nome Iverron di solito viene a trovarmi ogni giorno alla stessa ora. La cosa strana è che oggi non si è proprio visto: anzi, è in ritardo di parecchie ore.\n\nLo ammetto, sono un po' preoccupata, {name}. Iverron passa molto tempo vicino alla caverna a nord, e sono sicura che sai quanto sia pericolosa: ragni, ovunque!\n\nSe per caso vai da quelle parti, però, potresti tenere gli occhi aperti?", nil, "Sono così felice che tu mi abbia trovato, {name}. Come sapevi che ero qui?", 0xc68e1991, 0xa973ef17, 0xfa034016, nil, 0x8083d57b, "...m." },
  [4496] = { "Pasticci nella giungla", "Porta una ⟦Gorishi Scent Gland=Ghiandola Odorosa di Gorishi⟧ e 5 ⟦Un'Goro Soil=Terreno di Un'Goro⟧ all'alchimista Pestlezugg a ⟦Gadgetzan=Meccania⟧.", "Le mie ricerche mi hanno rivelato che i silitidi sono come le api: distruggi la regina dell'alveare e gli altri dovrebbero finire nel caos. Preparerò un'esca per far uscire la regina; una volta evocata, toccherà a te abbatterla.\n\nPrima, però, ci servono dei reagenti: non vogliamo che tu vada a combinare pasticci nella giungla senza essere pront<o/a>. Va' a ovest, trova l'alveare dei silitidi nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧ e prendi una ghiandola odorosa da uno degli insetti. Mi serviranno anche alcuni campioni del terreno di Un'Goro.", "Trovare una ghiandola odorosa adatta potrebbe richiedere un po': la ghiandola non dev'essere danneggiata, ma il modo per procurarsela non aiuta di certo. Quanto al terreno, immagino che dovrebbe essere abbastanza facile da trovare.\n\nComunque, hai le cose che mi servono per preparare l'esca?", "La ghiandola odorosa, ah, sì. La membrana sembra intatta: eccellente. Il terreno, sì, dovrebbe andare benissimo. Con le mie aggiunte speciali dovrei riuscire a macinare tutto in un'esca perfetta.\n\nDammi un momento per preparare l'esca, {name}. Quando sarà pronta potremo passare alla fase successiva, che spero fermerà i silitidi prima che invadano ⟦Gadgetzan=Meccania⟧... e il resto di Kalimdor.", 0x2350d0d6, 0x8547f48e, 0x28e51686, 0x27edc253, 0xaac7c66b, "....." },
  [4501] = { "Attenti agli pterrordattili", "Uccidi 10 Pterrordax e 15 ⟦Frenzied Pterrordax=Pterrordattilo Furioso⟧, poi parla con ⟦Spraggle Frock=Spraggle Pinzapersa⟧ al ⟦Marshal's Refuge=Rifugio dei Grant⟧.", "Cercasi: un abile combattente che affronti la minaccia degli pterrordattili che abitano il ⟦Un'Goro Crater=Cratere di Un'Goro⟧. Il loro numero cresce e stanno diventando un pericolo per chi viaggia nella zona.\n\nRiduci la popolazione uccidendo 10 pterrordattili e 15 pterrordattili frenetici.\n\nUna volta completato il compito, parla con ⟦Spraggle Frock=Spraggle Pinzapersa⟧ per ricevere una ricompensa.", "A dire il vero, non ero poi così preoccupato per quelle strane creature... finché un giorno non l'ho visto scritto sul fianco di una grossa pietra.\n\nATTENTI AGLI PTERRORDATTILI\n\nChi può averlo scritto? Non lo so, ma è troppo inquietante per ignorarlo!", "Ho un terrore folle degli pterrordattili di qui! Grazie per averne ridotto il numero, {name}. Ora forse mi sentirò abbastanza al sicuro da avventurarmi fuori dal ⟦Marshal's Refuge=Rifugio dei Grant⟧.", 0x53856929, 0xe5836a22, 0x4432659d, 0x84afa51a, 0x3ed95181, "....." },
  [4502] = { "Attività vulcanica", "Raccogli 9 campioni di ⟦Un'Goro Ash=Cenere di Un'Goro⟧ dagli elementali del fuoco attorno al vulcano del ⟦Un'Goro Crater=Cratere di Un'Goro⟧ e portali a ⟦Liv Rizzlefix=Liv Smontacavi⟧, a ⟦Ratchet=Porto Paranco⟧.", "Come apprendista di ⟦Marvon Rivetseeker=Marvon Cercachiodi⟧ ho imparato tantissimo. Ma è via da così tanto tempo che penso di mettermi a fare qualche esperimento per conto mio.\n\nDi recente ho letto del ⟦Un'Goro Crater=Cratere di Un'Goro⟧ e della strana attività vulcanica al centro del cratere. Credo che si potrebbe imparare molto, se solo riuscissi a procurarmi un po' della cenere degli elementali che ci vivono.\n\nTi dispiacerebbe raccoglierne un po' per me, se passi da quelle parti?", "È vero che il vulcano di Un'Goro è attivo? Sono sicura che con un po' di cenere del vulcano potrei imparare molto, {name}.", "Questi campioni saranno perfetti per i miei studi! Grazie, {name}! Te lo prometto, sarai <il/la> prim<o/a> a cui racconterò le mie scoperte.", 0xb735cc5c, 0xc791dada, 0xdc9ab232, 0x9ccfa2b9, 0x7d596c83, "....." },
  [4503] = { "La macchina volante di Shizzle", "Raccogli 8 Scaglia Palmata di Diemetradonte e 8 Scaglia Palmata di Pterrordattilo per Shizzle al ⟦Marshal's Refuge=Rifugio dei Grant⟧.", "Sto costruendo una macchina volante!\n\nNon ho modo di andarmene da qui, e non ho il minimo senso dell'orientamento. Prenderei un grifone o una viverna per tornare a ⟦Gadgetzan=Meccania⟧, ma quelle bestie mi spaventano a morte.\n\nAllora, mi aiuti? Mi restano da costruire solo le ali, e pensavo che le scaglie palmate degli pterrordattili e dei diemetradonti sarebbero perfette. Non ho nessuna intenzione di affrontarne uno, ma tu sembri parecchio tost<o/a>. Perché non ci provi?", "Ogni grande veicolo ha bisogno di un nome... Pensavo di chiamarlo... Pwned!", "Sì, queste scaglie sono perfette. Con queste riuscirò di sicuro a far decollare la mia macchina volante!\n\nGrazie!", 0x267b2e06, 0x07ea7cd0, 0xb8dc58ea, 0x99435350, 0x3a81d220, "....." },
  [4504] = { "Superappiccicoso", "Raccogli 12 campioni di ⟦Super Sticky Tar=Pece Appiccicosissima⟧ per Tran'rek a ⟦Gadgetzan=Meccania⟧.", "Cerco sempre un modo rapido per guadagnare un pezzo d'oro, {name}. Se mi aiuti con la mia ultima idea, ti darò una piccola parte del profitto. Che ne dici?\n\nLo sapevo!\n\nVa' alle pozze di catrame nel nord del ⟦Un'Goro Crater=Cratere di Un'Goro⟧ e raccoglimi un po' di catrame. Non un catrame qualsiasi, però: devi prenderlo dalle bestie che vivono attorno alle pozze. Il catrame normale semplicemente non è abbastanza appiccicoso.\n\nLe creature simili a piante hanno clorofilla nella pelle e, mescolata al catrame, la rende appiccicosissima!", "Tran'rek ha colpito ancora: questa colla appiccicosissima farà furore!", "Sì, questa pece è proprio quel che ci vuole...\n\nEhi, aspetta un attimo, le mie mani... non riesco a staccarle...\n\nForse non è stata una grande idea. Oh, ma aspetta! Un solvente per pece appiccicosissima! È lì che ci sono i veri soldi!", 0xd1b6e98f, 0xec2b0406, 0x8cd19f90, 0x59876396, 0x73171fdd, "....." },
  [4505] = { "Il pozzo della corruzione", "Raccogli un campione d'acqua corrotta dal pozzo lunare dei satiri Giadafulgida e portalo a Winna Hazzard all'⟦Bloodvenom Post=Accampamento di Sanguemarcio⟧.", "C'è chi dice che io sia eccezionalmente crudele... Ma in verità è solo un forte desiderio di vedere l'⟦Horde=Orda⟧ guadagnare un vantaggio sull'⟦Alliance=Alleanza⟧, con ogni mezzo possibile.\n\nIl mio ultimo interesse è un pozzo lunare nelle ⟦Ruins of Constellas=Rovine di Constellas⟧, a sud di qui, custodito dai satiri Giadafulgida. Il pozzo lunare, un tempo simbolo di rinascita per quegli insopportabili Elfi della Notte, ora è corrotto e viene usato per generare altri satiri.\n\nHo un'idea, {name}, e vorrei un campione dell'acqua... per il mio piccolo amico felino qui.", "È della massima importanza. Ora mettiti in cammino.", "Molto bene. Dobbiamo trovare un modo per usare questa corruzione contro i nostri nemici...", 0xd948deaa, 0x6a143d3b, 0x5ad7ea0d, 0x38afa674, 0x772286f3, "....." },
  [4506] = { "Felini corrotti", "Porta il gattino di Winna al pozzo lunare corrotto, liberalo, poi riportalo a Winna.\n\nUna volta tornat<o/a> da Winna, clicca sul gatto per consegnarlo a Winna.", "Quest'acqua corrotta può tornarci utile, {name}. Con appena un po' d'acqua il mio gattino è raddoppiato di dimensioni e sembra più forte... in qualche modo. Questi gatti potrebbero rivelarsi utili...\n\nEcco, {name}. Prendi questo trasportino e libera il gattino che c'è dentro accanto al pozzo lunare nelle ⟦Ruins of Constellas=Rovine di Constellas⟧. Eh, eh... Sono sicura che i risultati ti piaceranno!\n\nRiportami il gatto e farò in modo che tu non abbia perso il tuo tempo.", "Non dirmi che non puoi tornare laggiù! Muoviti!", "Eccellente!\n\nI Reietti ricorreranno a qualsiasi mezzo pur di schiacciare l'Alleanza! L'acqua corrotta si rivelerà di certo utile nei nostri sforzi futuri...", 0x3471adc0, 0xa46e77d2, 0xc2880cd5, 0x262eaecc, 0x136d0228, "....." },
  [4507] = { "Il pedone mangia la regina", "Sconfiggi la ⟦Gorishi Hive Queen=Regina dell'Alveare Gorishi⟧ quando viene evocata.\n\nPorta il Cervello della Regina Gorishi all'alchimista Pestlezugg a ⟦Gadgetzan=Meccania⟧.", "Ecco l'esca. All'interno delle gallerie dell'alveare dovrebbe esserci una specie di cristallo. Pensiamo che i silitidi lo usino come una sorta di dispositivo di sintonia per l'intero alveare. Quanto a dove possa trovarsi, direi di provare nelle incubatrici all'interno dell'alveare.\n\nUsare l'esca sul cristallo dovrebbe stanare la regina, ma ti avverto: probabilmente sarà protetta da diverse guardie. Elimina la regina e prendile il cervello. Per quanto possa sembrare disgustoso, abbiamo un disperato bisogno di studiarlo. Buona fortuna, {name}!", "Procurarci il cervello della regina per le nostre ricerche è assolutamente indispensabile. Da quanto abbiamo appreso, crediamo che questi silitidi siano molto probabilmente controllati da un'intelligenza maligna. Rabbrividisco al pensiero di cosa possa controllare qualcosa di insidioso come i silitidi, {name}.", "Fantastico, {name}! Oggi abbiamo ottenuto una bella vittoria. Ci vorrà un po' di tempo per capire fino in fondo cosa abbiamo tra le mani, ma lo useremo bene, non preoccuparti.\n\nQuanto ai silitidi, dubito sinceramente che questa fosse tutta la loro presenza. È una soluzione fin troppo pulita, mi dispiace dirlo.", 0x185f555f, 0xe9357e57, 0xb0de715f, 0xf8dbbd41, 0xc01ee2cb, "....." },
  [4508] = { "La quiete prima della tempesta", "Porta il ⟦Pestlezugg's Un'Goro Report=Rapporto su Un'Goro di Rollabomba⟧ a ⟦Gracina Spiritmight=Gracina Granspirito⟧ a Darnassus.", "Le mie recenti scoperte e ciò che abbiamo appreso qui oggi devono arrivare in mani che possano davvero farci qualcosa. Per quanto siamo pieni di risorse qui a ⟦Gadgetzan=Meccania⟧, non possiamo farcela da soli.\n\nPorta il mio ultimo rapporto a ⟦Gracina Spiritmight=Gracina Granspirito⟧, a Darnassus; è ancora al ⟦Temple of the Moon=Tempio della Luna⟧, giusto? Ha amici tra i pezzi grossi dell'⟦Alliance=Alleanza⟧; se riusciamo a coinvolgerli in questa faccenda, {name}, forse ne usciremo vivi.", "Sono degli sciocchi, {name}! Non riescono nemmeno a pensare di guardarsi attorno in cerca di una minaccia più grande; il loro odio irrazionale per l'⟦Horde=Orda⟧ sarà la fine di tutti noi. Non so quante altre prove posso dar loro della minaccia dei silitidi, a meno di gettarli in uno degli alveari perché vedano con i loro occhi!\n\nScusami, hai notizie da sottopormi?", "Lo apprezzo sinceramente, ma non so a cosa ci servirà. L'⟦Alliance=Alleanza⟧ ignora le minacce che non vengono dall'⟦Horde=Orda⟧, e persino i nostri capi qui a Darnassus non riescono a mettersi d'accordo su cosa sia esattamente questa minaccia. Sciocchi come ⟦Fandral Staghelm=Fandral Elmocervo⟧ sostengono che i silitidi non siano affatto la minaccia di un antico passato che io dico. La sua ignoranza è superata solo dalla sua arroganza.\n\nHai visto la minaccia con i tuoi occhi, {name}. Dobbiamo restare decisi a sconfiggere i silitidi!", 0x2a848062, 0xe0364cff, 0x0d4c87af, 0xd512ebbd, 0xe92de08c, "....." },
  [4509] = { "La quiete prima della tempesta", "Porta il ⟦Pestlezugg's Un'Goro Report=Rapporto su Un'Goro di Rollabomba⟧ a ⟦Zilzibin Drumlore=Zilzibin Suonapelli⟧ a Orgrimmar.", "Le mie recenti scoperte e ciò che abbiamo appreso qui oggi devono arrivare in mani che possano davvero farci qualcosa. Per quanto siamo pieni di risorse qui a ⟦Gadgetzan=Meccania⟧, non possiamo farcela da soli.\n\nPorta il mio ultimo rapporto a ⟦Zilzibin Drumlore=Zilzibin Suonapelli⟧, a Orgrimmar; è ancora al suo posto nella parte alta del Drag, giusto? Ha amici che contano nell'⟦Horde=Orda⟧; se riusciamo a coinvolgerli in questa faccenda, {name}, forse ne usciremo vivi.", "Sono degli sciocchi, {name}! Non riescono nemmeno a pensare di guardarsi attorno in cerca di una minaccia più grande; il loro odio irrazionale per l'⟦Alliance=Alleanza⟧ sarà la nostra rovina. Non so quante altre prove posso dar loro della minaccia dei silitidi, a meno di gettarli in uno degli alveari perché vedano con i loro occhi!\n\nScusami, hai notizie da sottopormi?", "Lo apprezzo sinceramente, ma non so a cosa ci servirà. L'⟦Horde=Orda⟧ ignora le minacce che non vengono dall'⟦Alliance=Alleanza⟧. Thrall in persona potrebbe agire se gli venissero presentati i fatti, ma è assediato da ogni parte da consigli contrastanti. Questi sciocchi ci farebbero rincorrere la nostra coda immaginaria, se pensassero che così potremmo cogliere l'⟦Alliance=Alleanza⟧ alla sprovvista!\n\nHai visto la minaccia con i tuoi occhi, {name}. Dobbiamo restare decisi a sconfiggere i silitidi!", 0x2a848062, 0x1e85f786, 0x601e9659, 0x0198e913, 0x22547659, "....." },
  [4510] = { "La quiete prima della tempesta", "Porta il ⟦Bank Voucher=Buono della Banca⟧ a Idriana, nella banca di Darnassus.", "{name}, il tuo aiuto è stato inestimabile. Verrà il momento, senza dubbio, in cui ti chiederò di nuovo aiuto contro i silitidi. Dobbiamo assimilare ciò che abbiamo imparato a Un'Goro; temo che la mia ipotesi che i silitidi provenissero da Un'Goro ora si riveli sbagliata... e che in realtà ci sia una presenza molto più forte da qualche parte.\n\nPorta questo biglietto a Idriana, in banca. Ti darà qualcosa dal mio caveau, da considerare un segno della mia gratitudine. Grazie per il tuo aiuto, <valoroso/valorosa> {class}.", "Elune'adore, {class}. Cosa posso fare per te oggi?", "Questo buono della banca mi autorizza a prelevare un oggetto dal conto di Gracina Spiritmight presso di noi e a consegnartelo. Direi che le congratulazioni sono d'obbligo!", 0x2a848062, 0xc67f689d, 0xbe332e09, 0xd9a6df82, 0xd0305231, "....." },
  [4511] = { "La quiete prima della tempesta", "Porta il ⟦Bank Voucher=Buono della Banca⟧ a Karus, nella banca di Orgrimmar.", "{name}, senza di te non saremmo arrivati fin qui. Verrà presto il momento, senza dubbio, in cui ti chiederò di nuovo aiuto contro i silitidi. Dobbiamo assimilare ciò che abbiamo imparato a Un'Goro; temo che la mia ipotesi che i silitidi provenissero da Un'Goro ora si riveli sbagliata... e che in realtà ci sia una presenza molto più forte da qualche parte.\n\nPorta questo biglietto a Karus, in banca. Ti darà qualcosa dal mio caveau, da considerare un segno della mia gratitudine. Grazie per il tuo aiuto, possente {class}.", "Zug zug! In cosa posso aiutarti oggi, {class}?", "Questo buono della banca mi autorizza a prelevare un oggetto dal conto di Zilzibin Drumlore presso di noi e a consegnartelo. Direi che le congratulazioni sono d'obbligo!", 0x2a848062, 0x789ea047, 0x50b303f1, 0x33b26f32, 0xd21bc1a3, "....." },
  [4512] = { "Un po' di melma fa molta strada", "Porta 6 Contenitore Pieno di ⟦Cursed Ooze=Melma Maledetta⟧ e 6 Contenitore Pieno di ⟦Tainted Ooze=Melma Corrotta⟧ a ⟦Laris Geardawdle=Laris Perdiruote⟧ a ⟦Ironforge=Forgiardente⟧.", "Ma la cosa che ho studiato di più sono le melme. Lo so che sembra strano, ma sono dappertutto!\n\nNon molto tempo fa ho aiutato una signora a Menethil a ritrovare la sua borsa: se l'erano mangiata le melme. Ho visto membri della Royal Apothecary Society di ⟦Undercity=Sepulcra⟧ raccogliere campioni di quella roba. Voglio sapere perché! Da dove vengono?\n\nHo sentito che ce ne sono altre a ⟦Felwood=Vilbosco⟧. Mi servono campioni delle melme di lì per portare avanti la mia ricerca. Ti darò dei contenitori: usali per prelevare un campione dalle creature morte.", "Alcuni degli esperimenti che ho fatto sono affascinanti. Credo che con un po' più di lavoro riuscirò a capire la natura di queste creature e che ruolo abbiano avuto nello sviluppo della vita su Azeroth... sempre che c'entrino qualcosa.\n\nUna delle mie teorie principali, che non piace a molti, è l'idea che melme e fanghiglie siano legate alla creazione di questo pianeta... quasi come se ne fossero una secrezione.\n\nMa non posso dimostrarla né confutarla finché non avrò altri campioni.", "Risultati incredibili, {name}! Ti sei avvicinat<o/a> abbastanza da prelevare un campione di quelle cose corrotte e non sembri neanche malridott<o/a>! Grazie. Oh, questi campioni saranno perfetti. Non vedo l'ora di cominciare a testarli.\n\nSe ho ragione, potrei diventare uno dei più grandi scienziati della Lega degli Esploratori!\n\nCosì dimostrerò a tutti i nani che non è stato un errore accogliere noi gnomi a ⟦Ironforge=Forgiardente⟧ dopo l'incidente di Gnomeregan.", 0xfc215fb1, 0xd9cd31fb, 0x14c48c9e, 0x0f89427d, 0xfa6bff92, "....." },
  [4513] = { "Un po' di melma fa molta strada", "Porta 10 Contenitore Pieno di Campioni Puri a ⟦Laris Geardawdle=Laris Perdiruote⟧ a ⟦Ironforge=Forgiardente⟧.\n\nSe hai difficoltà a trovarli, prova a farti dare altri indizi da Laris.", "Mi serviranno altri campioni, {name}. Ma... e non so come dirlo... devono essere campioni puri. Lo so, lo so. «Che cosa vuol dire puro, Laris?» Non ne sono sicuro. So che questi sono corrotti... proprio come il ⟦Felwood=Vilbosco⟧. Ed è per questo che la mia intuizione è così importante. Le melme sembrano adattarsi... assumere le caratteristiche della zona in cui si trovano. Dovrò trovare campioni non contaminati. Ma dove? Dove?!\n\nBah! {name}, prendi questi contenitori, nel caso ne trovassi qualcuno per conto tuo.", "Quante cose da considerare. Ma cosa significa? E che effetto ha sulla vita della gente di Azeroth?", "L'hai trovato? {name}, sei un vero tesoro. La tua dedizione e il tuo aiuto sono stati magnifici e non potrei mai ringraziarti abbastanza.\n\nTi prego, prendi questo per il disturbo. Ho del lavoro da fare, ma sono sicuro che, se tornerai più avanti, avrò di nuovo bisogno dei tuoi servigi.\n\nGrazie. Grazie davvero.", 0xfc215fb1, 0xb6a37702, 0xf58e5302, 0x8ddc9857, 0xcbbdacd0, "....." },
  [4521] = { "Guardiani selvaggi", "⟦Trull Failbane=Trull Buonasorte⟧, nel ⟦Felwood=Vilbosco⟧, vuole che tu uccida 15 Raging Owlbeast e 15 Ragged Owlbeast.", "⟦Winterspring=Fontefredda⟧ si trova appena oltre i Mordilegno, a nord-est del ⟦Felwood=Vilbosco⟧. Ci sei mai <stato/stata>?\n\nHo sentito dire che la regione è piena di creature chiamate silvagufi. Si sa che queste bestie custodiscono dei segreti: segreti degli elfi della notte.\n\nDobbiamo scoprire cosa si nasconde a ⟦Winterspring=Fontefredda⟧.\n\nHo sentito che i silvagufi cenciosi si trovano appena a sud della strada, e che ce ne sono altri, detti silvagufi furiosi, al centro di ⟦Winterspring=Fontefredda⟧. Sbarazzatene e apri l'accesso alla regione.", "Torna a fare rapporto quando avrai portato a termine il compito che ti ho affidato.", "Ottime notizie, {name}. Con queste bestie tolte di mezzo possiamo cominciare a spingerci più a fondo in ⟦Winterspring=Fontefredda⟧. Sei <pronto/pronta> per altro?", 0x4ae5e0ac, 0x27c2851b, 0xd7791e02, 0xdf2686fc, 0xde1fc110, "....." },
  [4542] = { "Messaggio per il ⟦Freewind Post=Presidio di Ventolibero⟧", "Porta il ⟦Urgent Message=Messaggio Urgente⟧ al guardiacolli Longhorn al ⟦Freewind Post=Presidio di Ventolibero⟧.", "<Viaggiatore/Viaggiatrice> <coraggioso/coraggiosa>, i centauri hanno intensificato i loro attacchi in questa zona. Il ⟦Freewind Post=Presidio di Ventolibero⟧ deve sapere subito di queste nuove scorrerie! Cerca il guardiacolli Longhorn al ⟦Freewind Post=Presidio di Ventolibero⟧, a sud-est, e consegnagli questo messaggio urgente.\n\nE sta' <attento/attenta>: evita il clan dei ⟦Grimtotem=Totem Truce⟧ qui vicino... ultimamente si comportano in modo strano con noi.", "Che cosa vuoi, {class}? Un messaggio urgente... per me?", "Altre cattive notizie! Questi centauri hanno passato il limite! Hanno assalito una delle mie carovane di rifornimenti e massacrato tutto il gruppo. È un oltraggio, e non resterà impunito!", 0xc0420527, 0xf4ee9842, 0x3bc2e3b4, 0x48656749, 0x3b14844c, "....." },
  [4581] = { nil, "Porta il ⟦Shindrell's Note=Messaggio di Shindrell⟧ a ⟦Kayneth Stillwind=Kayneth Ventocalmo⟧ a ⟦Forest Song=Cantaselva⟧.", "Il druido ⟦Kayneth Stillwind=Kayneth Ventocalmo⟧ mi ha mandato un messaggio. Vorrebbe un rapporto su ciò che accade lungo la nostra costa e nelle foreste intorno ad Astranaar. Teme che una corruzione si stia diffondendo per ⟦Ashenvale=Valtetra⟧... e forse ha ragione.\n\nEcco, portagli il mio rapporto. Lo troverai nel santuario di ⟦Forest Song=Cantaselva⟧, nei ⟦Nightsong Woods=Boschi del Canto Notturno⟧, a est.", "Hai qualcosa per me?", "Ah, il rapporto di Shindrell! Mille grazie, {name}. Shindrell è una brava sentinella, coraggiosa e acuta. Devo leggerlo per cercare indizi di una malvagità che temo si stia diffondendo per ⟦Ashenvale=Valtetra⟧.", 0x9dc5369f, 0x412eac24, 0x2655e857, 0x38f32e8a, 0x7f079b03, "e...." },
  [4601] = { "La Lavatutto 5200!", "Inserisci un Grime-Encrusted Item nella Lavatutto 5200, e assicurati di avere tre monete d'argento per avviare la macchina.", "Questo marchingegno spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice «La Lavatutto 5200», seguita da un testo:\n\n«Sporcizia e incrostazioni rovinano i tuoi gioiellini? La Lavatutto 5200 rimette lo splendore nello splendidoso! Inserisci l'oggetto che vuoi pulire e deposita tre monete d'argento nella fessura. Concedi alla Lavatutto 5200 un momento per l'operazione, e voilà! I tuoi oggetti di valore usciranno puliti e scintillanti!»", "A quanto pare il congegno ha bisogno di un qualche oggetto incrostato di sporcizia da pulire e di tre monete d'argento per mettersi in funzione. Se ci sono entrambe le cose, la Lavatutto 5200 dovrebbe funzionare...", "Inserisci l'oggetto incrostato di sporcizia e tre monete d'argento nella Lavatutto 5200. La macchina si risveglia in un tentativo frenetico di eliminare la sporcizia dall'oggetto sconosciuto. Dal cuore della macchina arrivano rumori violenti e assordanti di sbattimento. Il telaio di metallo del bestione cigola e geme mentre sobbalza da una parte all'altra...", 0x7df37d0f, 0xa77d0758, 0x66b0513f, 0x38e80812, 0x55272153, "....." },
  [4602] = { "La Lavatutto 5200!", "Inserisci un Grime-Encrusted Item nella Lavatutto 5200, e assicurati di avere tre monete d'argento per avviare la macchina.", "Questo marchingegno spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice «La Lavatutto 5200», seguita da un testo:\n\n«Sporcizia e incrostazioni rovinano i tuoi gioiellini? La Lavatutto 5200 rimette lo splendore nello splendidoso! Inserisci l'oggetto che vuoi pulire e deposita tre monete d'argento nella fessura. Concedi alla Lavatutto 5200 un momento per l'operazione, e voilà! I tuoi oggetti di valore usciranno puliti e scintillanti!»", "A quanto pare il congegno ha bisogno di un qualche oggetto incrostato di sporcizia da pulire e di tre monete d'argento per mettersi in funzione. Se ci sono entrambe le cose, la Lavatutto 5200 dovrebbe funzionare...", "Inserisci l'oggetto incrostato di sporcizia e tre monete d'argento nella Lavatutto 5200. La macchina si risveglia in un tentativo frenetico di eliminare la sporcizia dall'oggetto sconosciuto. Dal cuore della macchina arrivano rumori violenti e assordanti di sbattimento. Il telaio di metallo del bestione cigola e geme mentre sobbalza da una parte all'altra...", 0x7df37d0f, 0xa77d0758, 0x66b0513f, 0x38e80812, 0x55272153, "....." },
  [4605] = { "La Lavatutto 5200!", nil, nil, nil, "Così come era partita, la Lavatutto 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\" e la sua bocca si apre a spirale verso l'alto. Dentro la Lavatutto 5200 c'è una scatoletta legata con un fiocchetto. A quanto pare la macchina incarta l'oggetto dopo averlo liberato dalla sua crosta di sporcizia. Anche se la macchina non avesse funzionato, almeno ora l'oggetto è incartato in una bella scatola.\n\nBe', c'è un modo per scoprire se l'ha pulito o no...", 0x7df37d0f, nil, nil, nil, 0x6b359458, ".mmm." },
  [4606] = { "La Lavatutto 5200!", nil, nil, nil, "Così come era partita, la Lavatutto 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\" e la sua bocca si apre a spirale verso l'alto. Dentro la Lavatutto 5200 c'è una scatoletta legata con un fiocchetto. A quanto pare la macchina incarta l'oggetto dopo averlo liberato dalla sua crosta di sporcizia. Anche se la macchina non avesse funzionato, almeno ora l'oggetto è incartato in una bella scatola.\n\nBe', c'è un modo per scoprire se l'ha pulito o no...", 0x7df37d0f, nil, nil, nil, 0x6b359458, ".mmm." },
  [4621] = { "Ohè, ammiraglio!", "Uccidi ⟦Fleet Master Seahorn=Contrammiraglio Corno Marino⟧ e ⟦Baron Revilgaz=Barone Granbottino⟧ della ⟦Booty Bay=Baia del Bottino⟧, poi torna dall'ammiraglio Firallon a bordo del Velo Cremisi, al largo della costa della Valle di Rovotorto.", "Ascoltami bene, lupo di mare... è il potere della ⟦Booty Bay=Baia del Bottino⟧ che impedisce a noi Velerosse di navigare dove ci pare e di prenderci quel che vogliamo per diritto di saccheggio. Se tu piantassi un coltello nell'ammiraglio Seahorn, non avremmo mai più grane con le navi della ⟦Booty Bay=Baia del Bottino⟧. Se tu piantassi un coltello nel barone Revilgaz, non dovremmo mai più sottostare alla loro legge.\n\nSe vuoi diventare ammiraglio onorario tra noi (sì, AMMIRAGLIO), pianterai un coltello in tutti e due, come ho detto. Ora va', <ragazzo/ragazza>, e torna da me quando avrai fatto il lavoro.", "Sei già di ritorno, maledetto marinaio! Hai fatto come t'ho ordinato? Se ci deludi, finirai a camminare sull'asse.\n\nArrrrr...", "Ohè... ammiraglio {name}! Sei <un/una> pirata tra i pirati!\n\nMi scalda il cuore darti questo cappello. Non ne troverai mai un altro uguale da nessuna parte, e chiunque ti guardi vedrà che sei un ammiraglio della flotta dei Velerosse!", 0x22df4694, 0x5d734ecb, 0x9f88e019, 0xdddf99b1, 0x25634252, ".....", nil, nil, 0x9519df18, nil, nil },
  [4641] = { "Il tuo posto nel mondo", "Parla con Gornek. Ricordi che Kaltunk ha segnato sulla tua mappa dove si trova e ti ha detto che Gornek risiede nell'Antro del Tirocinio, un edificio a ovest.", "Finalmente hai l'età giusta, {name}... l'età per combattere nel nome dell'⟦Horde=Orda⟧. Per conquistare per la gloria del Capoguerra.\n\nSì...\n\n<Kaltunk ti squadra.>\n\nAndrai benissimo.\n\nSenza dubbio vorresti trovare un grande drago o un demone e strangolarlo a mani nude, ma forse sarebbe saggio cominciare con qualcosa di meno... pericoloso.\n\n<Kaltunk ride.>\n\nPresentati a Gornek: dovrebbe poterti affidare un compito più adatto a <un/una> giovane {class}. Troverai Gornek nell'Antro del Tirocinio, a ovest.", nil, "Un'altra recluta di Kaltunk, eh?\n\nSiamo messi proprio male se questo è il meglio che l'⟦Horde=Orda⟧ sa produrre. Non importa. Quando penseremo che sei pront<o/a> a lasciare la Valle, sarai <un/una> <fiero/fiera> <guerriero/guerriera> dell'⟦Horde=Orda⟧.", 0x3e605db7, 0x4dc50313, 0xfe9369ec, nil, 0x37f5f90f, "...m." },
  [4642] = { "Fusione di influenze", "Porta un ⟦Merged Ooze Sample=Campione di Melma Unita⟧ al chimico Fuely, a ⟦Undercity=Sepulcra⟧.", "Ecco della melma racchiusa in un contenitore, creata dai campioni del ⟦Felwood=Vilbosco⟧ che hai recuperato. Porta il contenitore al ⟦Un'Goro Crater=Cratere di Un'Goro⟧ e trova una melma pura... la varietà primordiale andrà benissimo. Quando sarai abbastanza vicin<o/a>, libera la melma dal contenitore e vediamo cosa pensano l'una dell'altra.\n\nAl termine dell'esperimento, portami un campione di ciò che resta. Ti aspetterò qui, all'Apothecarium.", "Come procede l'esperimento, {name}? Continuerò a studiare i campioni che mi hai procurato: comincio a capire perché Lady Sylvanas sia così interessata a queste creature. Se fanno davvero parte degli Dei Antichi, chissà come potremmo usarle a nostro vantaggio.", "Oh, eccellente, {name}. Davvero eccellente.\n\nChe storia. Chi avrebbe pensato che le due interagissero in questo modo... Dovrò dedicare più tempo a studiare i fattori ambientali che causano cambiamenti in queste creature.\n\nPer ora continuerò le mie ricerche. Forse ci risentiremo presto. Fino ad allora, ti auguro ogni bene.", 0x78c0ed12, 0x710ae697, 0x8a377911, 0x01bad1fb, 0x78cc8d43, "....." },
  [4681] = { "Trascinata a riva", "Recupera i ⟦Sea Turtle Remains=Resti di Tartaruga di Mare⟧ dalla Skeletal Sea Turtle nelle acque a ovest di Auberdine, poi torna ad Auberdine e parla con ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧.", "Quella creatura spiaggiata non è un caso isolato qui a ⟦Darkshore=Rivafosca⟧. Ce ne sono altre lungo la costa e perfino in acqua. Vorrei che tu ne esaminassi un'altra di cui siamo a conoscenza; è stata segnalata in acqua, proprio a ovest di Auberdine, vicino a una nave affondata. Torna da me con qualunque cosa tu riesca a recuperare che possa aiutare le nostre ricerche.\n\nInoltre, durante i tuoi viaggi potresti trovare altre creature. Se dovessi scoprire qualcosa, ti prego, faccelo sapere!", "Una volta che avrai esaminato i resti della creatura nell'acqua a ovest di qui, dovrei poter presentare un rapporto adeguato al ⟦Temple of the Moon=Tempio della Luna⟧ di Darnassus. Forse allora saremo più vicini a scoprire perché queste povere creature scelgono di finire la loro vita spiaggiate sulla costa di ⟦Darkshore=Rivafosca⟧.", "Oggi ci sei stat<o/a> di enorme aiuto; ora abbiamo buone possibilità di svelare il mistero del perché queste creature si spiaggino sulla costa di ⟦Darkshore=Rivafosca⟧. L'idea che possano fuggire dalla zona intorno a Teldrassil è inquietante. Se dovessi incontrarne altre nei tuoi viaggi, fammelo sapere. Le nostre ricerche qui sono appena agli inizi.\n\nA nome del ⟦Temple of the Moon=Tempio della Luna⟧, accetta questo come ringraziamento per il tuo impegno. Grazie, {name}!", 0x8079e34a, 0x149950e7, 0xcc7a3f7b, 0x32bf10da, 0xa60fc069, "....." },
  [4701] = { "Abbatterla", "Raggiungi i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e distruggi la fonte della minaccia dei worg. Mentre te ne andavi, Helendis ti ha gridato un nome: Halycon. È il nome che fanno gli orchi quando parlano dei worg.", "Avrai senz'altro visto i worg al comando degli orchi ⟦Blackrock=Roccianera⟧.\n\nÈ curioso: per quanti ne distruggiamo, il loro numero non cala mai. I miei esploratori riferiscono che i worg vengono allevati, addestrati e infine spediti fuori dai ⟦Blackrock Spire=Bastioni di Roccianera⟧, la capitale degli orchi ⟦Blackrock=Roccianera⟧. Devi raggiungere i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e scoprire la fonte di questa minaccia. Scoprirla... e distruggerla.\n\nBuona fortuna, {name}. Che Cenarius ti protegga...", "Hai scoperto la fonte della minaccia dei worg e te ne sei <occupato/occupata>?", "Non pensare alla sua sofferenza, {name}. La bestia era corrotta, frutto di magia oscura. Hai reso un grande servizio all'⟦Alliance=Alleanza⟧ e sarai ricompensat<o/a>.", 0xcfb89cb2, 0x5042d196, 0x416df2bc, 0x3ae0a971, 0xe17375b6, "....." },
  [4721] = { "Guardiani selvaggi", "⟦Trull Failbane=Trull Buonasorte⟧, nel ⟦Felwood=Vilbosco⟧, vuole che tu dia la caccia a 10 Berserk Owlbeast a ⟦Winterspring=Fontefredda⟧.", "Dei messaggeri sono tornati da ⟦Winterspring=Fontefredda⟧ riferendo che nella parte meridionale di ⟦Winterspring=Fontefredda⟧ c'è una serie di piccole grotte. Pare che nella zona attorno a queste grotte si trovino dei silvagufi. Se custodiscono qualcosa di prezioso, credo che sia lì che lo troveremo.\n\nQuesti ti daranno più filo da torcere dei precedenti, {name}. Sembra che le creature siano impazzite per l'esposizione proprio a ciò che cercano di proteggere.", "Conosci i tuoi ordini, {name}.", "Ho grande rispetto per il duro lavoro, {name}. Ora possiamo portare avanti i nostri piani per ⟦Winterspring=Fontefredda⟧.", 0x4ae5e0ac, 0x6995234b, 0xc3775c42, 0x638ad935, 0xb7573237, "....." },
  [4722] = { "Tartaruga marina spiaggiata", "Porta i ⟦Sea Turtle Remains=Resti di Tartaruga di Mare⟧ a ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧ ad Auberdine.", "Trovi la carcassa di una tartaruga marina che si era arenata sulla costa di ⟦Darkshore=Rivafosca⟧ tempo fa. È stata spolpata dai murloc che si sono accampati attorno ai resti della creatura. Eppure sui resti sembrano esserci ancora dei campioni adatti, che ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧ ad Auberdine potrebbe usare.", "Salve, {name}: hai scoperte da riferire su creature arenate sulla riva?", "Un'altra scoperta da studiare: ben fatto, {name}! Questi resti saranno studiati come si deve una volta arrivati a Darnassus. Accetta questo piccolo compenso in cambio dei resti che ci hai fornito per il nostro studio.", 0x3b1c0992, 0xb04a5a8b, 0x3d413149, 0x1ac8bd61, 0x9e7fd774, "....." },
  [4723] = { "Creatura marina spiaggiata", "Porta le ⟦Sea Creature Bones=Ossa di Creature Marine⟧ a ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧ ad Auberdine.", "I resti di un gigantesco plesiosauro, molto più grande di quelli che ci si aspetterebbe di trovare a ⟦Darkshore=Rivafosca⟧, giacciono arenati sulla riva di ⟦Mist's Edge=Costa Bruma⟧. Non si sa come questa creatura sia arrivata qui; il gruppo di murloc che ora banchetta con la sua carcassa sembra troppo debole, anche in gran numero, per aver abbattuto la bestia.\n\nAnche se in parte è stata spolpata, ne resta abbastanza per prelevare un campione da far studiare a ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧ ad Auberdine.", "Forse un giorno troveremo il modo di impedire a queste povere creature di morire inutilmente sulla costa di ⟦Darkshore=Rivafosca⟧. Fino ad allora, dobbiamo continuare le nostre ricerche!\n\nSalve, {name}: che notizie mi porti?", "Un'altra scoperta: ben fatto, {name}! Questi resti saranno studiati come si deve una volta arrivati a Darnassus. Accetta questo piccolo compenso in cambio dei resti che ci hai fornito per il nostro studio.", 0x4bb68b2b, 0xc0ba3e69, 0x9a0bf524, 0x919b7748, 0x3513dc87, "....." },
  [4724] = { "La capobranco", "Uccidi Halycon, la capobranco dei worg Scurerossa.", "Alcuni dicono che i worg controllati dagli orchi ⟦Blackrock=Roccianera⟧ siano opera di una forza soprannaturale. Altri dicono che non siano veri worg, ma una razza di cani demoniaci donata agli orchi da un signore degli abissi caduto.\n\nLa verità è molto meno artificiosa, ma altrettanto spaventosa. I worg di ⟦Blackrock=Roccianera⟧ discendono da Halycon e dal suo compagno. Halycon è la gigantesca madre del branco dei worg. Il suo compagno? Nessuno è mai sopravvissuto per raccontarlo.\n\nColpisci i worg al cuore. Distruggi Halycon... e, {name}, guardati le spalle.", "Uccisa la capobranco, possiamo cominciare a sfoltire le sentinelle worg dei Bastioni e, alla fine, aprirci un varco nella città.", "Cuccioli rabbiosi? ⟦Gizrul the Slavener=Gizrul il Capobranco⟧? E sei ancora viv<o/a> per raccontarlo?! Incredibile! Un tributo ben meritato!", 0xd14f9e29, 0xb373835f, 0x5dd20dfc, 0xeb799d55, 0xe160b968, "....." },
  [4725] = { "Tartaruga marina spiaggiata", "Porta la ⟦Strangely Marked Box=Cassa con Marchio Strano⟧ a ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧, ad Auberdine.", "Altri resti di tartaruga marina giacciono spiaggiati lungo la costa. Questi hanno una portantina abbandonata legata al guscio della tartaruga. Forse questa creatura è stata spinta a riva da esseri sconosciuti invece di arenarsi da sola, come lasciavano pensare alcuni degli altri resti. Ora i murloc Greymist hanno fatto dei resti di questa creatura la loro casa, e si nutrono della carcassa.\n\nNella portantina trovi una cassa con strani segni; forse ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧ ad Auberdine saprà interpretarli.", "È un piacere rivederti, {name}. Stiamo facendo grandi progressi nello svelare il mistero del perché maestose creature marine si arenino sulla costa di ⟦Darkshore=Rivafosca⟧, ma a quanto pare ogni risposta solleva altre due domande.\n\nSei qui per offrirci altro aiuto nelle nostre ricerche?", "Ho sentito parlare del tipo di portantine che hai trovato sul dorso della tartaruga. Credo proprio che siano portantine dei naga, usate sia in battaglia sia per trasportare le loro provviste sulla terraferma. I segni sulla cassa che hai trovato sono dei naga; questo spiegherebbe la loro presenza invasiva nell'estremo nord di ⟦Darkshore=Rivafosca⟧.\n\nManderò questa cassa a Darnassus insieme al resto delle tue scoperte. Questo è per te: grazie ancora per il tuo aiuto.", 0x3b1c0992, 0xe042fc30, 0xbf35a518, 0xeaee6b01, 0x3dd5d2a8, "....." },
  [4726] = { "⟦Broodling Essence=Essenza della Progenie⟧", "Porta 8 ⟦Broodling Essence=Essenza della Progenie⟧ e il Draco-Incarcinatrix 900 a ⟦Tinkee Steamboil=Tinkee Vapormarcio⟧ al ⟦Flame Crest=Cimiero Ardente⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Sono settimane che studio i dragoidi delle ⟦Burning Steppes=Steppe Ardenti⟧, e credo di aver finalmente fatto una scoperta! Ho creato un congegno, lo chiamo Draco Incarcinatrix 900. Può catturare l'essenza della progenie dei draghetti!\n\nO almeno, credo che possa.\n\nEcco, prendi il congegno e colpisci con una scarica un piccolo della progenie nelle ⟦Burning Steppes=Steppe Ardenti⟧. Mentre è sotto l'effetto del congegno, sconfiggilo e la sua essenza dovrebbe liberarsi.\n\nSe succede, splendido! Riportami dei campioni così posso studiarli!", "Hai l'essenza della progenie, {name}? Non vedo l'ora di studiarla.\n\nE poi... il mio mecenate non è il tipo di persona che vorresti deludere.", "Ha funzionato! Hai preso l'essenza! Ben fatto, {name}! Ben fatto!\n\nQuesta essenza sarà preziosissima per la mia ricerca. Spero un giorno di imparare a catturare draghetti vivi, o magari le loro uova. Se trovassi il modo di farlo, sarei l'invidia degli studiosi di draghi di tutto il mondo!\n\nAnche il mio datore di lavoro sarebbe contento e, come ho già detto, è uno che conviene tenersi buono...", 0xf3512895, 0x9d6bb3b9, 0x149c8369, 0x6d342062, 0xe8011b91, "....." },
  [4727] = { "Tartaruga marina spiaggiata", "Porta i ⟦Sea Turtle Remains=Resti di Tartaruga di Mare⟧ a ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧ ad Auberdine.", "I resti scheletrici di una tartaruga marina giacciono nella sabbia delle spiagge settentrionali di ⟦Darkshore=Rivafosca⟧. I murloc Greymist non hanno trovato questa carcassa, oppure l'hanno trovata e se ne tengono alla larga per qualche motivo sconosciuto. In ogni caso, della tartaruga resta abbastanza da portarne un campione a ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧, ad Auberdine, perché il ⟦Temple of the Moon=Tempio della Luna⟧ lo studi.", "Ben ritrovat<o/a>, {name}: hai trovato altre creature spiaggiate di cui il ⟦Temple of the Moon=Tempio della Luna⟧ dovrebbe sapere?", "È interessante che i murloc non fossero presenti in questo luogo; ne terremo conto mentre studiamo i resti di questa creatura! Grazie per il tuo impegno, {name}; il ⟦Temple of the Moon=Tempio della Luna⟧ vorrebbe che ti dessi questo, come compenso per il tuo tempo.", 0x3b1c0992, 0xb04a5a8b, 0x571231c8, 0x7d319b8f, 0x07b7db83, "....." },
  [4728] = { "Creatura marina spiaggiata", "Porta le ⟦Sea Creature Bones=Ossa di Creature Marine⟧ a ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧ ad Auberdine.", "La carcassa di quello che sembra un gigantesco mammifero marino giace in parte sventrata sulla spiaggia. Una carriola e vari attrezzi sono abbandonati accanto a questa enorme creatura marina spiaggiata, come se qualcuno avesse già tentato di studiarla. Anche se i murloc l'hanno saccheggiata, ne resta abbastanza da raccogliere un campione adatto per ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧, ad Auberdine.", "Ben ritrovat<o/a>, {name}! Cosa ti riporta ad Auberdine? Sei qui per riferire un'altra scoperta, forse?", "Ah, credo che tu ne abbia scoperta una che inizialmente stava esaminando la Lega degli Esploratori. Hanno una presenza qui a ⟦Darkshore=Rivafosca⟧, e avevano detto che stavano studiando una delle creature spiaggiate finché i murloc non li hanno cacciati. A quanto pare sei riuscit<o/a> dove noi due abbiamo fallito. Ti prego, accetta questo compenso a nome del ⟦Temple of the Moon=Tempio della Luna⟧.", 0x4bb68b2b, 0xc0ba3e69, 0xb92ea900, 0x2d08586e, 0xc17c3fc8, "....." },
  [4729] = { "Gli animali esotici di Kibler", "Raggiungi i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e trova dei Bloodaxe Worg Pup. Usa la gabbia per trasportare quelle feroci bestiole. Porta un ⟦Caged Worg Pup=Cucciolo di Worg Ingabbiato⟧ a Kibler.", "Ti starai chiedendo che ci faccio qui fuori. Guarda le gabbie! Non è ovvio?\n\nPrima di tutto amo gli animali, ma di mestiere faccio il venditore. Scovo animali esotici per i ricchi e famosi e addomestico le bestie perché si comportino da veri animali da compagnia.\n\nOra ti starai chiedendo: \"Cosa posso fare per te, Kibler?\" La risposta è semplice: prendi questa gabbia per bestie e trovami qualche cucciolo di worg. In cambio, ti addomesticherò un worg!", "<Kibler è impegnato a litigare con Opus.>", "Li hai presi al momento giusto, {name}. Ancora un po' e non si sarebbero più potuti addestrare! Dammi un minuto e il piccoletto sarà pronto da portare a casa.", 0xc161566b, 0x43257fa1, 0x2a9d1322, 0x7a68d331, 0x0346ba26, "....." },
  [4730] = { "Creatura marina spiaggiata", "Porta le ⟦Sea Creature Bones=Ossa di Creature Marine⟧ a ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧ ad Auberdine.", "Sulla spiaggia giace la carcassa mezza divorata di quello che forse era un enorme mammifero marino. Una banda di murloc, più forti di quelli che si trovano vicino ad Auberdine, si è stabilita attorno alla creatura morta. Della creatura resta abbastanza da poter consegnare un campione adeguato delle sue ossa a ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧, ad Auberdine.", "Salve di nuovo, {name}! Sei qui per riferire un'altra scoperta?", "Le ossa che hai portato appartengono a mansueti mammiferi marini che, si sa, abitano le acque attorno alla base di Teldrassil. Non si era mai saputo che si spiaggiassero in modo violento, come invece fanno i plesiosauri. Perché queste creature avrebbero fatto una cosa simile, mi chiedo? Beh, forse lo studio dei loro resti darà i frutti di conoscenza che cerchiamo.\n\nAncora grazie per il tuo aiuto. Ti prego, accetta questo compenso da parte del ⟦Temple of the Moon=Tempio della Luna⟧.", 0x4bb68b2b, 0xc0ba3e69, 0xe841063a, 0xd044bb6e, 0x6ea9c612, "....." },
  [4731] = { "Tartaruga marina spiaggiata", "Porta la ⟦Strangely Marked Box=Cassa con Marchio Strano⟧ a ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧, ad Auberdine.", "Un altro insieme di resti di tartaruga marina giace spiaggiato sulla costa. A questi resti è agganciato per metà al guscio un carro abbandonato. Forse questa creatura è stata spinta a riva da esseri sconosciuti invece di arenarsi da sola, come lasciavano pensare alcuni degli altri resti. Dei potenti murloc Greymist hanno fatto della carcassa di questa creatura la loro attuale dimora.\n\nNel carro trovi una cassa con strani segni; forse ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧, ad Auberdine, potrà capirne il significato.", "Ben ritrovat<o/a>, {name}. Il lavoro che hai svolto per il ⟦Temple of the Moon=Tempio della Luna⟧ è stato eccezionale. Saremo benedetti da altri tuoi sforzi in nostro favore?", "Ho sentito parlare del tipo di carro trovato sul dorso di quella tartaruga. Credo proprio che siano carri dei naga, usati sia in battaglia sia per trasportare i loro rifornimenti sulla terraferma. I segni sulla cassa che hai trovato sono dei naga; forse la creatura che hai scoperto è stata uccisa mentre si dirigeva più a sud... forse verso ⟦Ashenvale=Valtetra⟧?\n\nMi assicurerò di mandare questa cassa a Darnassus insieme alle altre tue scoperte. Questo è per te: grazie ancora per il tuo aiuto.", 0x3b1c0992, 0xe042fc30, 0x8653ac9e, 0x69e011cf, 0xb192bb2e, "....." },
  [4732] = { "Tartaruga marina spiaggiata", "Porta i ⟦Sea Turtle Remains=Resti di Tartaruga di Mare⟧ a ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧ ad Auberdine.", "Trovi la carcassa di una tartaruga marina che si era arenata sulla costa di ⟦Darkshore=Rivafosca⟧ qualche tempo fa. È stata spolpata quasi del tutto dai murloc Greymist, gli stessi che ora si sono accampati intorno ai resti della creatura. Tuttavia, sui resti sembrano esserci ancora dei campioni adatti, che ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧, ad Auberdine, potrebbe utilizzare.", "Salute di nuovo, {name}: hai altre scoperte da riferire al ⟦Temple of the Moon=Tempio della Luna⟧?", "Hai trovato altre creature spiaggiate, {name}? Un tempo le tartarughe marine si vedevano spesso giocare ai piedi di Nordrassil, prima che venisse distrutto. Con la nascita di Teldrassil, però, queste creature si sono viste in numero sempre minore. Alcune, come abbiamo scoperto, vengono a morire qui per qualche ragione sconosciuta.\n\nForse il tuo aiuto svelerà il mistero che abbiamo davanti. Accetta questo in cambio dei resti che hai fornito per i nostri studi.", 0x3b1c0992, 0xb04a5a8b, 0x149a42d1, 0x068b830b, 0x96ba0af6, "....." },
  [4733] = { "Creatura marina spiaggiata", "Porta le ⟦Sea Creature Bones=Ossa di Creature Marine⟧ a ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧ ad Auberdine.", "Quelli che sembrano i resti di un gigantesco squalo volpe sono stati portati a riva nell'insenatura rocciosa della ⟦Twilight Shore=Riva del Crepuscolo⟧. Lo squalo è parecchie volte più grande di qualsiasi altro squalo volpe avvistato da queste parti. Da dovunque sia venuta, questa creatura non sembra originaria di ⟦Darkshore=Rivafosca⟧.\n\nAnche se la creatura è stata fatta a pezzi in alcuni punti, ne resta abbastanza per raccogliere un campione adatto per ⟦Gwennyth Bly'Leggonde=Gwennyth Bly'leggonde⟧, ad Auberdine.", "Sia ringraziata Elune: sono lieta di rivederti, car<o/a> {name}. Il lavoro del Tempio della Luna sugli strani spiaggiamenti continua qui a ⟦Darkshore=Rivafosca⟧. Hai forse qualcos'altro da offrirci?", "Le dimensioni dello squalo volpe di cui parli sono sbalorditive. Anche i più vecchi squali volpe di questa regione raggiungono solo una frazione di quella grandezza. Sebbene si sapesse di alcuni esemplari più grandi vicino a Teldrassil, il loro numero è calato costantemente. Non posso fare a meno di chiedermi se lo spiaggiamento di queste creature sia in qualche modo collegato.\n\nMentre analizziamo le ossa che ci hai portato, accetta questo da parte del ⟦Temple of the Moon=Tempio della Luna⟧. Grazie, {name}.", 0x4bb68b2b, 0xc0ba3e69, 0x88008738, 0x2ba63290, 0xa5eb453e, "....." },
  [4734] = { "Uova congelate", "Usa il ⟦Eggscilloscope Prototype=Prototipo di Uovometro⟧ su un uovo nella Colonia.", "{name}, ho lavorato sodo a un nuovo congegno, l'uovometro! È progettato per sparare una scarica di energia gelida sull'uovo di un drago nero... e congelarlo all'istante! Puoi provarlo per me?\n\nHo sentito dire che in cima ai ⟦Blackrock Spire=Bastioni di Roccianera⟧ i draghi hanno una colonia dove covano le uova. È lì che dovrai andare a provare l'uovometro, poi fammi sapere come ha funzionato!\n\nE non preoccuparti. Le uova di drago congelate dovrebbero essere innocue. Sono quelle non congelate che devono preoccuparti!", "{name}, hai provato l'uovometro?", "Ha funzionato? Splendido! Lo sapevo!\n\nMentre eri via ho lavorato a una nuova versione dell'uovometro. Questa ha una portata molto più lunga.\n\nEcco, puoi tenerne uno, nel caso tornassi ai ⟦Blackrock Spire=Bastioni di Roccianera⟧.", 0xd86966f2, 0x4409fe76, 0x9c1ff9d5, 0xae292932, 0x28c0d761, "....." },
  [4735] = { "Raccolta di uova", "Porta 8 Uovo di Drago Raccolto e il ⟦Collectronic Module=Modulo Collettronico⟧ a ⟦Tinkee Steamboil=Tinkee Vapormarcio⟧ al ⟦Flame Crest=Cimiero Ardente⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "{name}, finalmente sono pronta per dei veri campioni di uova di drago! Ecco, prendi questo modulo collettronico. È progettato per estrarre un uovo di drago e prepararlo per il trasporto. Torna alla Colonia e usa il modulo per raccogliere le uova.\n\nE non dimenticare di congelarle prima, o potrebbero schiudersi prima che tu riesca a raccoglierle!\n\nQuando avrai abbastanza uova, portamele!", "Hai le uova, {name}? Il mio mecenate ha saputo che le stai raccogliendo per me, e non vede l'ora di metterci le mani sopra!", "Wow, ce l'hai fatta! Il modulo collettronico ha funzionato! Sono un genio!\n\nGrazie, {name}. Il mio mecenate sarà felicissimo di avere queste uova...", 0x46624cc2, 0xf424606c, 0x9fb80264, 0x8669b96c, 0xa116f248, "....." },
  [4736] = { "In cerca di ⟦Menara Voidrender=Menara Squarciavuoto⟧", "Parla con ⟦Menara Voidrender=Menara Squarciavuoto⟧ nelle ⟦Barrens=Savane⟧.", "Ah, salve, {name}. Stai facendo buoni progressi nel tuo addestramento. Così buoni, anzi, che credo tu meriti una ricompensa per il tuo impegno, e per non esserti ancora fatt<o/a> corrompere dall'arcano.\n\nSe ti interessa, cerca ⟦Menara Voidrender=Menara Squarciavuoto⟧ a ⟦Ratchet=Porto Paranco⟧. Al momento alloggia nella torre di Strahad Farsan, che domina la città.\n\nNon è molto cordiale, {name}, quindi non aspettarti lodi. Ma se lavori sodo, farà in modo che tu non resti a mani vuote.", nil, "Ah, ti manda ⟦Briarthorn=Rosaspina⟧. Bene. Allora la voce arriva abbastanza lontano da trovare futuri allievi. Questo mi fa piacere.\n\nÈ tipico della nostra specie, {name}, fare fronte comune, a prescindere dalla razza. È particolarmente importante, perché coloro con cui abbiamo più a che fare non fanno distinzioni nella loro malvagità, se non riusciamo a placarli o a controllarli come si deve.\n\nSento che hai imparato moltissime cose e, se sei dispost<o/a>, ti aiuterei a creare strumenti che completino le tue abilità.", 0x10f09105, 0xdd3a1725, 0x1f30d3ac, nil, 0xa4bfa39e, "...m." },
  [4737] = { "In cerca di ⟦Menara Voidrender=Menara Squarciavuoto⟧", "Parla con ⟦Menara Voidrender=Menara Squarciavuoto⟧ nelle ⟦Barrens=Savane⟧.", "Hmph, continui a cercare di diventare più potente. Io dico che è solo questione di tempo prima che la corruzione e la dipendenza si impadroniscano di te e tu diventi schiav<o/a> di ciò che cerchi di dominare.\n\nPuah! Sei <uno/una> <stolto/stolta>! Il tempo mi darà ragione, nient'altro... solo il tempo.\n\nMa a quanto pare non tutti sono d'accordo con Zevrost. Sembra che Menara voglia creare strumenti per renderti più potente e per imbrigliare la tua forza. Se ti interessa, va' a ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧. Sta lassù, da dove domina la città.", nil, "Ah, ti manda Zevrost. Bene. Allora la voce arriva abbastanza lontano da trovare futuri allievi. Questo mi fa piacere.\n\nÈ tipico della nostra specie, {name}, fare fronte comune, a prescindere dalla razza. È particolarmente importante, perché coloro con cui abbiamo più a che fare non fanno distinzioni nella loro malvagità, se non riusciamo a placarli o a controllarli come si deve.\n\nSento che hai imparato moltissime cose e, se sei dispost<o/a>, ti aiuterei a creare strumenti che completino le tue abilità.", 0x10f09105, 0xdd3a1725, 0x1ffc2c9b, nil, 0x76faa6d0, "...m." },
  [4738] = { "In cerca di ⟦Menara Voidrender=Menara Squarciavuoto⟧", "Parla con ⟦Menara Voidrender=Menara Squarciavuoto⟧ nelle ⟦Barrens=Savane⟧.", "Mettiamo in chiaro una cosa, {name}: non credo che tu sia pront<o/a> per simili responsabilità. Non penso che un novizio debba mai partecipare alla creazione di un oggetto di potere, men che meno uno così poco messo alla prova.\n\nMa non spetta a me deciderlo. Lo decidono i poteri superiori, o almeno quelli che desiderano concederti simili doni.\n\nSe vuoi saperne di più, ti consiglio di cercare ⟦Menara Voidrender=Menara Squarciavuoto⟧ a ⟦Ratchet=Porto Paranco⟧. Di solito risiede nella torre che sovrasta la città portuale.", nil, "Ah, ti manda Demisette. Bene. Allora la voce arriva abbastanza lontano da trovare futuri allievi. Questo mi fa piacere.\n\nÈ tipico della nostra specie, {name}, fare fronte comune, a prescindere dalla razza. È particolarmente importante, perché coloro con cui abbiamo più a che fare non fanno distinzioni nella loro malvagità, se non riusciamo a placarli o a controllarli come si deve.\n\nSento che hai imparato moltissime cose e, se sei dispost<o/a>, ti aiuterei a creare strumenti che completino le tue abilità.", 0x10f09105, 0x7c0126bb, 0x28c69a48, nil, 0xb18020cd, "...m." },
  [4739] = { "In cerca di ⟦Menara Voidrender=Menara Squarciavuoto⟧", "Parla con ⟦Menara Voidrender=Menara Squarciavuoto⟧ nelle ⟦Barrens=Savane⟧.", "{class}! Sì, proprio tu!\n\nNon hai tutto l'equipaggiamento, ma si vede chiaramente che sei pront<o/a>: l'aria intorno a te trasuda una sicurezza maggiore. Sì, ora lo vedo.\n\nMenara Voidrender ti insegnerebbe qualcosa, se ti senti pront<o/a>. Passa il suo tempo a istruire nell'arcano gli studenti più giovani. Fa persino dei doni a chi supera le sue prove.\n\nSe ti interessa, va' a ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧. Sta sopra la città, nella torre di Strahad.", nil, "Ah, ti manda Kaal. Bene. Allora la voce arriva abbastanza lontano da trovare futuri allievi. Questo mi fa piacere.\n\nÈ tipico della nostra specie, {name}, fare fronte comune, a prescindere dalla razza. È particolarmente importante, perché coloro con cui abbiamo più a che fare non fanno distinzioni nella loro malvagità, se non riusciamo a placarli o a controllarli come si deve.\n\nSento che hai imparato moltissime cose e, se sei dispost<o/a>, ti aiuterei a creare strumenti che completino le tue abilità.", 0x10f09105, 0xdd3a1725, 0x047f9579, nil, 0x6556e634, "...m." },
  [4740] = { "RICERCATO: ⟦Murkdeep=Limobranchio⟧!", "Trova e uccidi il murloc noto come ⟦Murkdeep=Limobranchio⟧. Si ritiene che la creatura difenda le capanne dei murloc lungo la riva, a sud di Auberdine.\n\nRiferisci la morte di ⟦Murkdeep=Limobranchio⟧ alla sentinella Glynda Nal'Shea, ad Auberdine.", "Attenzione!\n\nSi offre una ricompensa per la morte del murloc «⟦Murkdeep=Limobranchio⟧». Questa ripugnante bestia è responsabile della morte di almeno una Sentinella ed è sospettata di aver fatto affondare almeno due navi da carico nelle acque al largo di ⟦Darkshore=Rivafosca⟧!\n\n⟦Murkdeep=Limobranchio⟧ è stato avvistato l'ultima volta in un accampamento di capanne dei murloc a sud di Auberdine, e si ritiene che protegga le capanne. La ricompensa per questa taglia va richiesta alla sentinella Glynda Nal'Shea, ad Auberdine.\n\nIl Consiglio del villaggio di Auberdine", "Salute, {class}: in che cosa possono aiutarti oggi le ⟦Sentinels=Sentinelle⟧? Forse sei qui per informarti sulla taglia su ⟦Murkdeep=Limobranchio⟧?", "Be', a quanto pare non sei qui solo per informarti! I cittadini saranno felici di sapere che stanotte dormiranno un po' più tranquilli e al sicuro.\n\nOggi sei <stato/stata> il braccio della giustizia per la gente di Auberdine, {name}. Per questo vorrei offrirti questa degna ricompensa... per <un/una> ver<o/a> <eroe/eroina> della gente di Auberdine.", 0xcf1b7374, 0xd0180f37, 0x68da692c, 0x1e209309, 0xb1230932, "....." },
  [4741] = { "Guardiani selvaggi", "⟦Trull Failbane=Trull Buonasorte⟧, nel ⟦Felwood=Vilbosco⟧, vuole che tu dia la caccia a 13 Moontouched Owlbeast.", "Nelle zone settentrionali di ⟦Winterspring=Fontefredda⟧ i silvagufi diventano ancora più feroci. Dobbiamo proseguire lì le nostre misure.\n\nCaccia i Moontouched Owlbeast a ⟦Winterspring=Fontefredda⟧ ed esplora la zona che abitano.\n\nÈ un territorio pericoloso, ma so che saprai affrontare la sfida. Torna da me dopo aver ucciso 13 silvagufi.", "Non dirmi che hai troppa paura! Muoviti!", "Sento che il tuo lavoro ti piace. E credo che siamo sulla pista giusta.", 0x4ae5e0ac, 0x76331e15, 0x512b3ee5, 0x16914799, 0x632109b1, "....." },
  [4742] = { "Il Sigillo dell'Ascesa", "Trova le tre gemme del comando: la ⟦Gemstone of Smolderthorn=Gemma dei Bruciaspina⟧, la ⟦Gemstone of Spirestone=Gemma degli Spiraroccia⟧ e la ⟦Gemstone of Bloodaxe=Gemma degli Scurerossa⟧. Riportale a Vaelan insieme al ⟦Unadorned Seal of Ascension=Sigillo dell'Ascesa Disadorno⟧.\n\nI generali, come ti ha detto Vaelan, sono: ⟦War Master Voone=Maestro di Guerra Voone⟧ dei Bruciaspina, ⟦Highlord Omokk=Gran Signore Omokk⟧ degli Spiraroccia e ⟦Overlord Wyrmthalak=Supremo Dragthalak⟧ degli Scurerossa.", "Come vedi, il sigillo disadorno ha tre incastonature vuote. Ognuna va riempita con una gemma che rappresenta il comando dei capi. Infine il signore supremo Wyrmthalak, padrone della cittadella inferiore, deve forgiare il sigillo nelle fiamme dello Stormo Nero.\n\nSappi questo, mortale: è raro che uno dei tre generali della cittadella inferiore porti con sé una gemma in un dato momento. Dovrai essere vigile nella tua impresa. Non perderti d'animo!", "Coraggio e pazienza prima di tutto, {name}!", "<L'immagine di Vaelan si offusca per un istante.>\n\n<I pezzi che avevi raccolto sono scomparsi.>\n\nIl ⟦Unforged Seal of Ascension=Sigillo dell'Ascesa Non Forgiato⟧ ora è pronto. È il momento del passo finale.", 0xf0f215e7, 0x2162d61c, 0xa741b187, 0x5c4e12a1, 0x523d6f59, "....." },
  [4743] = { "Il Sigillo dell'Ascesa", "Raggiungi il ⟦Wyrmbog=Brago dei Dragoni⟧, ad ⟦Dustwallow Marsh=Acquemorte⟧. Trova l'antico draco ⟦Emberstrife=Braceardente⟧ e pestalo senza pietà finché la sua volontà non sarà spezzata.\n\nÈ in quel momento che dovrai porre il ⟦Unforged Seal of Ascension=Sigillo dell'Ascesa Non Forgiato⟧ davanti alla grande bestia. Poi dovrai essere rapid<o/a> a usare il ⟦Orb of Draconic Energy=Globo dell'Energia Draconica⟧ sul suo corpo indebolito e a impadronirti delle sue facoltà mentali. Controlla la bestia e costringila a riversare le Fiamme dello Stormo Nero sul ⟦Unforged Seal of Ascension=Sigillo dell'Ascesa Non Forgiato⟧!", "Pochi dragoidi neri, al di fuori di quelli della cittadella superiore, sanno forgiare il sigillo con il proprio soffio infuocato. Wyrmthalak è uno di loro, ma la sua volontà è infrangibile.\n\nDevi raggiungere il ⟦Wyrmbog=Brago dei Dragoni⟧, ad ⟦Dustwallow Marsh=Acquemorte⟧. È lì che troverai un antico draco chiamato ⟦Emberstrife=Braceardente⟧. Devi spezzare la sua volontà, {name}. Spezzala e usa questo globo sul suo corpo indebolito. Avrai pochi secondi per controllarne la mente e attizzare le fiamme che forgeranno il sigillo.", "Non perdere tempo, {name}. Nefarian lavora febbrilmente per scatenare il suo male sul nostro mondo.", "Non muoverti mentre lancio l'invocazione finale di protezione.\n\n<Gli occhi di Vaelan diventano due globi di fiamma.>\n\nIl Sigillo dell'Ascesa è completo...\n\nSappi questo: ho infuso nel manufatto alcune potenti protezioni. Nell'ora più buia, quando tutto sembrerà perduto, la potenza dello Stormo dei Draghi Rossi sarà al tuo servizio.", 0xf0f215e7, 0xd5e99e4f, 0x25238491, 0xcf559296, 0x66a1f4a0, "....." },
  [4761] = { nil, "Parla con ⟦Thundris Windweaver=Thundris Brigliavento⟧ ad Auberdine.", "Le informazioni raccolte esplorando l'accampamento dei mezzorsi dovrebbero arrivare a ⟦Thundris Windweaver=Thundris Brigliavento⟧. Con grande generosità fa da anziano di Auberdine, e guida con saggezza e giustizia la vita quotidiana del villaggio. Ti prego, condividi con lui ciò che hai scoperto finora sulla situazione dei mezzorsi.\n\nCredo che abbia delle idee sue sulle ragioni della loro corruzione. Forse potrai lavorare con lui a un piano per ristabilire l'equilibrio della natura qui!", nil, "Ben trovat<o/a>, {class}. La tua esplorazione della situazione dei mezzorsi arriva in un momento propizio per noi di Auberdine. Da tempo non abbiamo a che fare solo con abitanti della foresta ormai apertamente ostili alla nostra presenza, ma anche con la corruzione vera e propria della foresta stessa. Spero che tu possa dare aiuto ad Auberdine in questi tempi difficili.", 0xa1402122, 0xe04eac93, 0x5978da41, nil, 0x8e442694, "e..m." },
  [4762] = { "Il ⟦Cliffspring River=Fiume Altafonte⟧", "Viaggia a nord di Auberdine fino alla prima cascata lungo il ⟦Cliffspring River=Fiume Altafonte⟧ e preleva un campione dalla pozza che si trova lì.\n\nTorna da ⟦Thundris Windweaver=Thundris Brigliavento⟧ ad Auberdine con il ⟦Cliffspring River Sample=Campione del Fiume Altafonte⟧.", "Il ⟦Cliffspring River=Fiume Altafonte⟧ ha cominciato a diventare torbido e corrotto. Si getta nella ⟦Mist's Edge=Costa Bruma⟧, e temo che presto le sue acque raggiungeranno Auberdine. Sospetto che la causa della contaminazione siano i mezzorsi Blackwood risalendo il fiume, ma sospetto anche che non ne siano la vera origine.\n\nPrendi questa provetta e va' alla foce del fiume, a nord di qui. Prosegui verso l'interno fino alla prima cascata e preleva un campione dalla pozza che si trova lì. Vedrai un ponte sopra di te. Quando avrai il campione, torna da me ad Auberdine.", "L'inquinamento del ⟦Cliffspring River=Fiume Altafonte⟧ è solo l'inizio di una tendenza allarmante qui a ⟦Darkshore=Rivafosca⟧. Il campione che porterai ci aiuterà a definire un piano... un piano d'attacco, comincio a sospettare.", "Non sorprende quanto sia contaminata quest'acqua, ma guarda quanto sta diventando putrida! Sembra che bisogni agire prima piuttosto che poi, eh, {name}?\n\nA est di qui c'è ⟦Felwood=Vilbosco⟧: è la vera fonte di questa corruzione, che ho già visto in passato. Prevedo che questo campione lo confermerà. Potremmo riuscire a trovare una cura qui, ma per provarci avremo bisogno di aiuto. Quando verrà quel momento, {name}, spero che potrai darci l'aiuto di cui abbiamo bisogno.", 0x732408df, 0x9c875372, 0x31c4d12c, 0xcd07cafd, 0x405bb8d6, "....." },
  [4763] = { "I Blackwood corrotti", "Riempi la ⟦Empty Cleansing Bowl=Ciotola per la Pulizia Vuota⟧ al pozzo lunare di Auberdine.\n\nRaccogli un campione di frutta, di noci e di cereali dagli accampamenti settentrionali dei mezzorsi Selvanera.\n\nMescola il contenuto della ciotola e posala vicino al falò più vicino al ⟦Cliffspring River=Fiume Altafonte⟧, nell'accampamento settentrionale, per evocare il corruttore satiro.\n\nPrendi il ⟦Talisman of Corruption=Talismano della Corruzione⟧ e portalo a ⟦Thundris Windweaver=Thundris Brigliavento⟧, ad Auberdine.", "Abbiamo scoperto che una delle fonti della corruzione dei mezzorsi sono i satiri. Esercitano il loro dominio tramite talismani attraverso cui incanalano la magia. Se i mezzorsi hanno una possibilità di salvezza, dobbiamo attirare allo scoperto il corruttore satiro e prendergli quel talismano!\n\nRiempi questa ciotola al nostro pozzo lunare e prendi dei campioni del cibo dei mezzorsi dal loro accampamento settentrionale. Mescolali e metti la ciotola vicino al falò accanto al fiume: i mezzorsi che ne mangeranno saranno purificati quanto basta per attirare allo scoperto il corruttore satiro... che poi dovrai uccidere!", "Il ⟦Talisman of Corruption=Talismano della Corruzione⟧ è un congegno sinistro che serve solo a pervertire l'equilibrio della natura. Quando avrai sottratto questo oggetto al satiro che tormenta i mezzorsi e me lo porterai perché lo distrugga, oggi avremo ottenuto una grande vittoria!", "Abbiamo appena iniziato questa guerra per strappare la nostra foresta alle forze della corruzione, ma oggi abbiamo vinto una battaglia! {name}, la gente di Auberdine ha con te un debito di gratitudine che non sarà mai facile ripagare. Accetta questo insieme ai nostri ringraziamenti. Ciò che abbiamo imparato qui oggi potrebbe un giorno liberare per sempre i nostri amici mezzorsi dalle catene del tormento.", 0x2f8f88d9, 0xbffe0b22, 0xb9e3e349, 0x893d1d9e, 0xa947b3e7, "....." },
  [4764] = { "La ⟦Doomrigger's Clasp=Fibbia del Portarovina⟧", "Porta la ⟦Doomrigger's Clasp=Fibbia del Portarovina⟧ a ⟦Mayara Brightwing=Mayara Alachiara⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "C'è una sala, in alto nei ⟦Blackrock Spire=Bastioni di Roccianera⟧, che un tempo si chiamava Hall of Fortune. Era lì che i nani ⟦Dark Iron=Ferroscuro⟧ custodivano le loro reliquie, i trofei e le opere d'arte.\n\nTutto questo accadeva molto tempo fa. Si dice che la sala sia crollata e che ora venga usata per... scopi meno nobili. Ma credo che lì si possano ancora trovare alcune antiche reliquie naniche.\n\nUna di queste è la Fibbia del Portarovina, con la superficie così incrostata di gemme rare che si diceva facesse piangere qualunque nano la guardasse.\n\nQuella fibbia, {name}, è il tuo obiettivo.", "Hai la fibbia, {name}? Il mio mecenate la pagherà profumatamente.", "L'hai trovata! Allora le voci erano vere!\n\nGrazie, {name}. Il mio mecenate, il conte Remington Ridgewell, sarà molto contento di vedere questa aggiunta alla sua collezione.", 0x2d327b90, 0xe26bc34c, 0x50d49bc2, 0x9da3cae3, 0xf09398d5, "....." },
  [4765] = { "Consegna per Ridgewell", "Porta la ⟦Ridgewell's Crate=Cassa di Crestafonda⟧ a Remington Ridgewell, a ⟦Stormwind=Roccavento⟧.", "Ho imballato la Fibbia del Portarovina in una cassa adatta alla spedizione a ⟦Stormwind=Roccavento⟧. {name}, sei stat<o/a> di grandissimo aiuto... posso chiederti un ultimo favore?\n\nConsegna la cassa al conte Remington Ridgewell. Lo troverai nel Castello di ⟦Stormwind=Roccavento⟧. Sono sicura che sarà molto contento di vedere cosa hai per lui.", "Mi hanno detto che sarebbe arrivato un messaggero. Con un dono dai ⟦Blackrock Spire=Bastioni di Roccianera⟧.\n\nSei tu?", "Ah, allora sei tu! Hai la mia gratitudine, {name}. E... se non lo sapevi già... la gratitudine di un nobile della casata dei Ridgewell vale quasi quanto il riscatto di un re.", 0x8cf04bff, 0xf7182c21, 0xa8e591a6, 0xe5568bb1, 0x3663f6c4, ".....", nil, nil, nil, 0x5cc3b051, 0x14f78b72 },
  [4766] = { nil, "Parla con ⟦Mayara Brightwing=Mayara Alachiara⟧ nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Una mia agente, ⟦Mayara Brightwing=Mayara Alachiara⟧, è stata mandata nelle ⟦Burning Steppes=Steppe Ardenti⟧ a esplorare la città in rovina di Thaurissan. Quella città distrutta dei nani ⟦Dark Iron=Ferroscuro⟧ potrebbe nascondere oggetti di grande valore... oggetti che starebbero benissimo nel museo della nostra famiglia.\n\nMayara dice di aver trovato qualcosa e che le servirà aiuto per recuperarlo, ma non si trova a Thaurissan. Servirà invece una spedizione nei ⟦Blackrock Spire=Bastioni di Roccianera⟧.\n\nNon conosco i dettagli, ma se ti interessa, parla con Mayara nelle ⟦Burning Steppes=Steppe Ardenti⟧.", nil, "Vieni da ⟦Stormwind=Roccavento⟧? Magnifico! Conosco un'opera d'arte che Remington ucciderebbe pur di avere nel suo museo, ma recuperarla non sarà facile.\n\nEd è qui che entri in gioco tu.", 0x05c75784, 0x56e79fbe, 0x1d85f073, nil, 0xe3cb6b7f, "e..m." },
  [4767] = { "Cavaliere di viverne", "Porta 10 Uova di Viverna di ⟦Highperch=Covoalto⟧ a Elu al ⟦Freewind Post=Presidio di Ventolibero⟧.", "Mi è stato affidato il compito di reclutare altre viverne per i cavalieri di viverne più esperti. Il loro numero cresce e io stesso spero un giorno di diventare un cavaliere di viverne. Però non riusciamo ad addestrare abbastanza viverne per stare al passo con la richiesta. Forse puoi aiutarmi, {name}.\n\nHo bisogno che tu vada a ⟦Highperch=Covoalto⟧ a raccogliere alcune uova di viverna. Da qui, dirigiti a nord-ovest lungo le pareti del canyon fino a una rampa che ti porterà a ⟦Highperch=Covoalto⟧. Fai attenzione: le viverne proteggono gelosamente le loro uova e non saranno gentili con gli intrusi.", "{name}, hai recuperato le uova di viverna che cerco? Non vedo l'ora di iniziare il mio addestramento da cavaliere di viverne!", "Perfetto! Con queste uova spero di fare il prossimo passo per diventare un cavaliere di viverne. Ecco un segno della mia gratitudine; che la buona caccia ti sorrida sempre, {class}.", 0xb115ace3, 0x1b0bf486, 0x8c494c01, 0x55a37b15, 0x2fee56fe, "....." },
  [4768] = { "La ⟦Darkstone Tablet=Tavoletta di Pietra Nera⟧", "Porta la ⟦Darkstone Tablet=Tavoletta di Pietra Nera⟧ alla maestra delle ombre Vivian Lagrave, a Kargath.", "La ⟦Darkstone Tablet=Tavoletta di Pietra Nera⟧ contiene gli scritti del nano Urheld Darkstone, morto da tempo. Alchimista di grande talento, era considerato pazzo dai suoi contemporanei e per questo non condivise le sue ricerche.\n\nPerò le incise su delle tavolette, e credo che una di esse si trovi nei ⟦Blackrock Spire=Bastioni di Roccianera⟧, in una sala che un tempo si chiamava Hall of Fortune. Non so come si chiami ora, perché pochi entrano a ⟦Blackrock=Roccianera⟧ e ne tornano.\n\nMa se sei dispost<o/a> ad affrontarne i pericoli e a tornare da me con la tavoletta, la tua ricompensa sarà grande.", "Hai trovato la Tavoletta, {name}? Non vedo l'ora di scoprirne i segreti.", "Eccellente. Le formule incise su questa tavoletta richiederanno giorni di ricerche, ma sono fiduciosa che queste ricerche daranno frutti dolcissimi.\n\nGrazie, {name}. Ci sei stat<o/a> di un aiuto prezioso.", 0x9658baee, 0x9010bf76, 0x92a5578e, 0x7a25f7d7, 0xfa7108f2, "....." },
  [4769] = { "Vivian Lagrave e la ⟦Darkstone Tablet=Tavoletta di Pietra Nera⟧", "Parla con la maestra delle ombre Vivian Lagrave.", "Vivian Lagrave mi ha mandato un messaggio da Kargath, nelle ⟦Badlands=Maleterre⟧. Dai suoi studi è convinta che nei ⟦Blackrock Spire=Bastioni di Roccianera⟧ si trovi un testo antico che gioverebbe alle nostre ricerche. Per averne conferma, le serve qualcuno che vada a prendere il testo nei Bastioni. Non è un compito facile.\n\nSe ti interessa, parla con Vivian a Kargath.", nil, "È vero. Credo che nei ⟦Blackrock Spire=Bastioni di Roccianera⟧ sia custodita una tavoletta, una tavoletta che contiene antiche ricette alchemiche. Sono lieta che tu sia qui, perché mi serve aiuto per recuperarla.\n\nMettiti comod<o/a> e ti spiegherò meglio.", 0x1edac7b5, 0x816f52d4, 0xc42a7bd5, nil, 0xd02ea1cc, "...m." },
  [4770] = { "Ritorno a casa", "Scorta Pao'ka Swiftmountain fuori da ⟦Highperch=Covoalto⟧, poi parla con Motega Firemane all'⟦Whitereach Post=Accampamento di Manto Bianco⟧.", "Aiutami, ti prego, {class}! Mi nascondo qui a ⟦Highperch=Covoalto⟧ da un po' ormai, e sono giorni che non vedo un volto amico. Sono venuto qui a studiare le viverne e credo di essermi avvicinato un po' troppo. Dopo che mi hanno cacciato da uno dei nidi, mi sono perso.\n\nDevo tornare all'⟦Whitereach Post=Accampamento di Manto Bianco⟧! Motega non sa che sono sparito e si infurierà quando scoprirà che mi sono avventurato a ⟦Highperch=Covoalto⟧ da solo.\n\nL'⟦Whitereach Post=Accampamento di Manto Bianco⟧ è appena a est di qui... ti prego, portami là!", nil, "Cosa!? Se avessi saputo che Pao'ka Swiftmountain sarebbe andato a ficcare il naso a ⟦Highperch=Covoalto⟧, l'avrei incatenato a un totem! Suo padre era restio a lasciarlo venire con me a ⟦Thousand Needles=Millepicchi⟧. Siamo venuti qui per studiare le diverse creature che abitano queste splendide terre.\n\nApprezzo l'aiuto che hai dato a Pao'ka. Spero che questo ripaghi qualsiasi disavventura ti sia costata questa impresa.", 0x495ac7e2, 0xf36b8eeb, 0x9c7efe0f, nil, 0xc6301876, "...m." },
  [4771] = { "La Trappola della Luce dell'Alba", "Metti la Trappola della Luce dell'Alba nella Sala d'Osservazione di Scholomance. Sconfiggi Vectus, poi torna da ⟦Betina Bigglezink=Betina Lucestrema⟧.", "Ho messo la Trappola della Luce dell'Alba nel contenitore che ci hai portato, quello che conteneva le uova di drago. Il tuo compito è portarla nelle profondità di Scholomance.\n\nIl mago non morto Vectus guida una squadra di studiosi del Flagello... metti la Trappola della Luce dell'Alba nella loro sala, la \"Sala d'Osservazione\". Reagirà con i non morti che si trovano lì e, con un po' di fortuna, li distruggerà!\n\nDopodiché, sconfiggere Vectus non dovrebbe essere un problema. Giusto?", "Ricorda, {name}: dobbiamo essere tolleranti, ma saldi nelle nostre convinzioni!", "Ce l'hai fatta! Vectus è sconfitto! E la Trappola della Luce dell'Alba... ha funzionato?\n\nMm... forse il mio congegno non è stato il successo che speravo, ma sono contenta che tu sia riuscit<o/a> a cavartela comunque. Ben fatto, {name}!\n\nL'⟦Argent Dawn=Alba d'Argento⟧ e la brava gente di Azeroth sono in debito con te.", 0xe69ac5eb, 0x6d5640e4, 0xa08c5d9e, 0x2a558b5c, 0x872f453b, "....." },
  [4781] = { "Componenti per la ⟦Enchanted Gold Bloodrobe=Tonaca Dorata Incantata⟧", "Porta un ⟦Gold Bar=Lingotto d'Oro⟧ a ⟦Xizk Goodstitch=Xizk Puntaspilli⟧ nella Valle di Rovotorto.", "Il tuo prossimo compito è semplice come il primo, ma dovrai cercare aiuto.\n\nMi serve del filo d'oro per ricamare il mantello, ma il filo d'oro non è facile da trovare, e pochissimi sanno farlo. Per fortuna, uno che è fedele alla nostra causa ne conosce i segreti ed è disposto ad aiutare chi sale nei nostri ranghi.\n\nPorta un lingotto d'oro a ⟦Xizk Goodstitch=Xizk Puntaspilli⟧ alla ⟦Booty Bay=Baia del Bottino⟧. È un maestro sarto e sarà felice di filarlo per te. I lingotti d'oro li fondono i minatori esperti. Chiedi aiuto a un minatore.", "Lingotti d'oro, sì... sì. Portamene uno e vedremo cosa si può fare per filarti un po' di filo. Nel frattempo, ti suggerirei di concentrare i tuoi sforzi sul diventare più potente. Le prove più dure ti aspettano ancora. E fidati... vorrai essere più preparat<o/a>, per quanto potente tu creda di essere.", "Perfetto, {name}. Sono contento che tu abbia trovato così in fretta un minatore che ti aiutasse. O hai fatto il lavoro da te? In ogni caso, hai fatto bene. Questo sarà perfetto per il filo.\n\nCi vorrà un po' di tempo per produrlo, quindi dovrai tornare: in realtà lo mando a una principessa che teniamo rinchiusa in una torre e il cui unico compito è filare filo d'oro... no, sul serio. Dico davvero... va bene, non proprio.", 0x7fee9266, 0x16a84461, 0x54d5ef6e, 0x024ea4f3, 0x476cbcd4, "....." },
  [4782] = { "Componenti per la ⟦Enchanted Gold Bloodrobe=Tonaca Dorata Incantata⟧", "Torna da ⟦Menara Voidrender=Menara Squarciavuoto⟧ nelle ⟦Barrens=Savane⟧.", "Torna da Menara e dille che ci vorrà un po' di tempo, ma non deluderò né lei... né te. Dille di farti finire di raccogliere il resto dei componenti: per allora il filo dovrebbe essere pronto. Potrai tornare a prenderlo.\n\nBuona fortuna, {name}. Ah, e già che ci sei salutami Strahad. Quel vecchio matto... piazzare una torre proprio lì accanto a ⟦Ratchet=Porto Paranco⟧... roba da pazzi.", nil, "Bene, sei tornat<o/a>, {name}. E dov'è il filo?\n\nAh, capisco. È accettabile. Il goblin e suo fratello non ci hanno mai delusi finora: immagino sia comprensibile che non l'avesse pronto subito. E sia... nel frattempo abbiamo altre cose di cui occuparci.\n\nSei pront<o/a> per il passo successivo?", 0x7fee9266, 0xb874296f, 0xe71c1200, nil, 0xce0868a5, "...m." },
  [4783] = { "Componenti per la ⟦Enchanted Gold Bloodrobe=Tonaca Dorata Incantata⟧", "Porta 10 Fiala di Sangue di Furiatorva e 1 ⟦Lesser Infernal Stone=Pietra Infernale Inferiore⟧ a ⟦Menara Voidrender=Menara Squarciavuoto⟧ nelle ⟦Barrens=Savane⟧.", "I prossimi componenti si trovano a ⟦Desolace=Desolanda⟧, molto a ovest delle ⟦Barrens=Savane⟧ e persino delle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.\n\nLaggiù il caos regna ancora dopo la Separazione. Saranno messe alla prova sia la tua forza che la tua astuzia: affronterai creature dell'odio e anche della Legione Infuocata.\n\nDai satiri Furiatorva a nord-est, portami il loro sangue. Dagli infernali minori della ⟦Mannoroc Coven=Congrega di Mannoroc⟧, portami una pietra infernale inferiore.\n\nUseremo entrambi per confezionare la tua tonaca.", "⟦Desolace=Desolanda⟧ non è una terra gentile: naga, giganti, satiri, la Legione Infuocata... tutti loro, e i clan di centauri in guerra tra loro, rendono la regione pericolosa se non stai attent<o/a>.\n\nCome ti ho detto, metterà alla prova non solo la tua forza e la tua astuzia, ma anche la tua pazienza. Sta' in guardia in quelle terre, {name}.", "Eccellente, {name}. Questi andranno benissimo. Li preparerò ora, mentre tu passi agli ultimi due componenti. Sei pront<o/a>?", 0x7fee9266, 0xfd7ed7f0, 0x055bed5e, 0x9a052ff2, 0xfb7327df, "....." },
  [4784] = { "Componenti per la ⟦Enchanted Gold Bloodrobe=Tonaca Dorata Incantata⟧", "Porta del ⟦Fine Gold Thread=Filo Dorato Pregiato⟧, 2 Carbone Infuocato e un Soul Shard a ⟦Menara Voidrender=Menara Squarciavuoto⟧ nelle ⟦Barrens=Savane⟧.", "Ora mi servono solo tre cose, {name}, poi potremo finire la tua tonaca.\n\nPrima di tutto, il filo dorato pregiato che Xizk sta preparando per te. Torna da lui alla ⟦Booty Bay=Baia del Bottino⟧ e fattelo dare.\n\nSecondo, portami due carboni infuocati dagli elementali del fuoco degli ⟦Arathi Highlands=Altopiani d'Arathi⟧. Se ricordo bene, si trovano a ovest, vicino al ⟦Thoradin's Wall=Muro di Thoradin⟧.\n\nInfine, un frammento d'anima creato da te.\n\nQuando avrai tutti i componenti, torna qui alla torre e completerò la tonaca per te.", "Presto, {name}. Te lo prometto. La tonaca sarà più che adeguata alle tue esigenze e di certo ti darà un vantaggio sui tuoi avversari.", "Eccellente, {name}! I componenti sono riuniti e siamo pronti.\n\nSono certo che ne sarai soddisfatt<o/a>.", 0x7fee9266, 0x57678e6a, 0x01e0638a, 0x10b8afc4, 0x33387de3, "....." },
  [4786] = { "La veste ultimata", "Aspetta che ⟦Menara Voidrender=Menara Squarciavuoto⟧ finisca la tua veste, poi parla di nuovo con lei.", "Ora metterò insieme la veste per te. Ci vorrà solo qualche istante. Non allontanarti.", "Un momento, {name}...", "È fatto, {name}. Eccola. Indossala con orgoglio.\n\nHai lavorato sodo, e vedo grandi cose nel tuo futuro. Ricorda: resistere alla corruzione che accompagna il nostro cammino richiede grande volontà e forza d'animo. Finché la tua volontà resterà tua, avrai grande successo.", 0x6458d4ea, 0x1f58f886, 0xac1a561e, 0x5118b45f, 0x7b3d8bf4, "....." },
  [4787] = { "L'⟦Ancient Egg=Uovo Antico⟧", "Porta l'⟦Ancient Egg=Uovo Antico⟧ a Yeh'kinya, a Tanaris.", "La Profezia di Mosh'aru parla di un uovo antico. È una reliquia dei tempi in cui i troll governavano vasti imperi, e ha il potere di contenere l'essenza di Hakkar. Potrebbe essere l'unico modo per proteggere il nostro mondo dalla sua malvagità.\n\nPortami l'uovo antico, {name}. Si dice che sia nascosto nelle profondità di ⟦Jintha'Alor=Jintha'alor⟧, nelle Entroterre, in una grotta dietro l'anfiteatro in cima alla città.", "Hai l'uovo antico? Sento grandi forze che si risvegliano, e temo che il tempo stringa.", "Ah, hai l'uovo! M'inchino a te, {name}. La tua forza e il tuo coraggio saranno ricordati a lungo.", 0x145cd452, 0x848c5ffa, 0x907bfabd, 0xec9c0814, 0x7bde200a, "....." },
  [4788] = { "Le ultime tavolette", "Porta la Quinta Tavoletta Mosh'aru e la Sesta Tavoletta Mosh'aru al prospettore Ironboot, a Tanaris.", "Mentre io esamino la terza e la quarta tavoletta di Mosh'aru, tu devi trovare la quinta e la sesta! Non sarà facile, perché sono custodite dai troll Bruciaspina all'interno dei ⟦Blackrock Spire=Bastioni di Roccianera⟧. I bastioni sono una tetra montagna di fuoco tra le ⟦Burning Steppes=Steppe Ardenti⟧ e la ⟦Searing Gorge=Gorgia Rovente⟧.\n\nBuona fortuna, {name}. I ⟦Blackrock Spire=Bastioni di Roccianera⟧ non sono un posto per gente perbene...", "Sei stat<o/a> ai bastioni, {name}? Hai la quinta e la sesta tavoletta?", "Incredibile! Le hai trovate! Hai davvero la stoffa dell'eroe, {name}!\n\nÈ un bene, perché ho letto le tavolette che mi hai portato prima e, da quel che ho capito... ci servirà un eroe per fermare ciò che sta arrivando...", 0x987997a3, 0xc9b97742, 0xef778150, 0x4a4945d3, 0x7b123b86, "....." },
  [4808] = { nil, "Consegna la ⟦Tinkee's Letter=Lettera di Tinkee⟧ a ⟦Felnok Steelspring=Felnok Mollacciaio⟧.", "Ho un altro favore da chiederti.\n\nIl mio primo studio dell'essenza che hai raccolto mostra che potrebbe essere possibile congelare le uova dei cuccioli di drago e conservarle! Voglio verificare questa teoria, ma prima mi servono componenti di ingegneria fatti apposta. Il mio collega, ⟦Felnok Steelspring=Felnok Mollacciaio⟧, può costruirli.\n\nEcco, porta questa lettera a Felnok. Gli spiega di cosa ho bisogno. Troverai Felnok a ⟦Winterspring=Fontefredda⟧, nella città di ⟦Everlook=Lungavista⟧.", "Che freddo quassù! Spero che tu mi abbia portato una coperta!", "Questa non è una coperta! Ma cosa abbiamo qui? Una lettera di Tinkee? Chissà cosa ha da dire...\n\nAh, sta facendo ricerche nelle ⟦Burning Steppes=Steppe Ardenti⟧. Ha senso: è un buon posto per trovare dragoidi. Oh, ma guarda! Qui dice che le servono dei pezzi per un dispositivo che vuole costruire. Immagino che qui entri in gioco io, eh?", 0xd723b278, 0xcf66a2d3, 0xed2e16a1, 0x42eb722b, 0x96652015, "e...." },
  [4809] = { "Corni di Ventofreddo", "Porta 8 Corno di Ventofreddo Intatto a ⟦Felnok Steelspring=Felnok Mollacciaio⟧.", "Ho quasi tutto quello che serve a Tinkee, ma mi manca un componente importante: i corni di Ventofreddo. I corni delle chimere Ventofreddo di ⟦Winterspring=Fontefredda⟧ sono una fonte concentrata di freddo, ma vanno bene solo quelli perfetti, senza crepe! Me ne serve una scorta per completare l'ordine di Tinkee.\n\nPortami i corni di Ventofreddo intatti e preparerò un pacco per Tinkee.", "Hai i corni di Ventofreddo, {name}?", "Questi sono ottimi esemplari. Sono carichi di freddo! Fammi mettere un paio di guanti, poi li imballerò insieme alle altre cose che servono a Tinkee...", 0x57866406, 0xd3c65a4c, 0x2d4d46d9, 0x49da01ef, 0xe51c3160, "....." },
  [4810] = { "Ritorno da Tinkee", "Porta la ⟦Felnok's Package=Cassa di Felnok⟧ a ⟦Tinkee Steamboil=Tinkee Vapormarcio⟧ nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Ok, è tutto pronto, imballato e pronto per il trasporto! Buon viaggio, e assicurati di dire a Tinkee che me ne deve una!", "{name}! Hai parlato con Felnok? Mi hai portato i componenti che mi servono?", "Li hai portati! Fantastico! Mi metto subito al lavoro! Grazie mille, {name}!\n\nMi sei <stato/stata> così d'aiuto che più avanti potrei aver bisogno di te per compiti ancora più importanti...", 0x613a4bee, 0xd63de51b, 0x4015e85f, 0xb1d0a031, 0x69656083, "....." },
  [4811] = { "Il cristallo rosso", "Viaggia a est di Auberdine e cerca un grosso cristallo rosso lungo la catena montuosa orientale di Rivafosca. Riferisci ciò che trovi alla sentinella Glynda Nal'Shea, ad Auberdine.", "A est di qui si aggirano lunagufi ostili, sempre più numerosi. Un tempo li si riteneva creature gentili, quasi mistiche. Anche se alcuni continuano a venerarli, la sicurezza di Auberdine mi obbliga a una visione più realistica.\n\nHo ricevuto rapporti secondo cui i lunagufi sono attirati da un grosso cristallo rosso lungo la catena montuosa orientale di Rivafosca. Nessuno ha idea di cosa sia quel cristallo, e nemmeno se esista davvero. Voglio che tu vada a trovarlo e che mi riferisca ciò che scopri.", "Cos'hai da riferire su quel cristallo rosso? Esiste davvero?", "Dunque il cristallo esiste, {name}? Affascinante... comunque, hai svolto bene il tuo compito; ottimo lavoro!\n\nChe cos'è esattamente questo cristallo? È solo una domanda in un mare di domande. Un'altra che mi viene in mente è perché i lunagufi siano attirati da questo oggetto. Il cristallo è di natura benigna o ha uno scopo più sinistro?\n\nHo molte altre domande, ma dovremo esaminare da vicino quel cristallo per avere qualche risposta.", 0x5ae7f813, 0x8d4ec0d3, 0x69995f12, 0x84875e53, 0xe63afa83, "....." },
  [4812] = { "Mentre l'acqua scorre", "Riempi la ⟦Empty Water Tube=Fialetta d'Acqua Vuota⟧ al pozzo lunare di Auberdine, poi esamina il cristallo rosso lungo la parete montuosa orientale di Rivafosca.", "Prendi questa fiala vuota e riempila con un po' d'acqua del pozzo lunare, qui ad Auberdine. Una magia così potente dovrebbe darci un indizio sulla composizione del cristallo. Per farlo, verserai il liquido sul cristallo; al resto penserà l'acqua.\n\nAnche se non prevedo che ti accada nulla di male, voglio comunque che tu stia attent<o/a>. Sopra di noi, a est, c'è ⟦Felwood=Vilbosco⟧; se quel cristallo è legato a quel luogo, come sospetto, potrebbe rivelarsi molto pericoloso.", "Il cristallo sembra del tutto estraneo al paesaggio boscoso di ⟦Darkshore=Rivafosca⟧. Ti sembra di sentire un lievissimo ronzio provenire dalle sue profondità.", "Sei arrivat<o/a> di nuovo al misterioso cristallo. Togli il tappo alla fialetta d'acqua del pozzo lunare e ne versi con cautela il contenuto sulla sommità del cristallo. Mentre l'acqua scorre lungo le sue strutture reticolari, vedi la superficie opaca diventare trasparente...", 0xdefb4541, 0xe834c2df, 0x29e90dd5, 0xb62a1acf, 0x9b8b44cb, "....." },
  [4813] = { "I frammenti all'interno", "Riferisci ciò che hai scoperto alla sentinella Glynda Nal'Shea, ad Auberdine.", "L'acqua del pozzo lunare ha rivelato che all'interno del cristallo sono incastonati alcuni piccoli frammenti d'osso, oltre a metà di una mandibola. La mandibola sembra appartenere a un umanoide, ma non se ne può essere certi senza spaccare il cristallo, un'impresa che perfino la magia più potente troverebbe quasi impossibile.\n\nPortato a termine il compito, non resta che tornare a riferire alla sentinella Glynda Nal'Shea, ad Auberdine.", nil, "Be', a quanto pare, anche se ora sappiamo di più su questo cristallo, il risultato sono altre domande senza risposta!\n\nPorterò le informazioni che hai scoperto al consiglio qui ad Auberdine. Forse sapranno quale linea d'azione seguire riguardo a questo cristallo. Sempre che ce ne sia una da intraprendere; per ora la minaccia resta abbastanza lontana, a est, da non nuocerci.\n\nQuanto a te, prendi questo. Consideralo una ricompensa per un lavoro ben fatto, {name}.", 0xb84b9e71, 0x336ce815, 0x1453b5e8, nil, 0xd3015ad0, "...m." },
  [4821] = { "⟦Alien Egg=Uovo Alieno⟧", "Riporta l'⟦Alien Egg=Uovo Alieno⟧ a Hagar Lightninghoof, al ⟦Freewind Post=Presidio di Ventolibero⟧.", "Circola una voce su un uovo alieno qui a ⟦Thousand Needles=Millepicchi⟧. Chi dice di averlo visto non è riuscito nemmeno ad avvicinarsi abbastanza da esaminarlo per bene. I serpenti sorvegliano l'uovo come se fosse uno dei loro.\n\nVoglio che tu trovi questo uovo alieno e me lo porti, così che possa esaminarlo. Si dice che l'uovo si trovi in una tana di serpenti, ma ce ne sono diverse lungo la base delle pareti rocciose a sud e a nord-est del ⟦Freewind Post=Presidio di Ventolibero⟧.", "Devo sapere di più su questo uovo misterioso: chissà cosa ne uscirà.", "Sì, finalmente... l'uovo misterioso mi è stato finalmente consegnato. Ora, diamo un'occhiata più da vicino... Cosa..! Cos'è questo..?", 0x3030ce44, 0x472a0b24, 0x6e429e9a, 0x5cb94efa, 0xfb1826a4, "....." },
  [4822] = { "Gelato, che passione...", "Procura del gelato alla fragola per il tuo pupillo. Il ragazzino sembra preferire il gelato di Tigule.", "GELATO! Oh, ti prego ti prego ti prego, mi prendi un gelato?! La fragola è il mio gusto preferito, e non c'è gelato alla fragola al mondo migliore del ⟦Tigule's Strawberry Ice Cream=Gelato alla Fragola di Tigule⟧! È il mio gelato preferito in tutto il mondo!\n\nL'ho mangiato una volta, tanto tempo fa, quando ero alla pista delle corse delle Distese Salate, ma ho sentito che ora forse lo vendono anche in città! Per favore? Per favore per favore? Con sopra il ⟦Tigule's Strawberry Ice Cream=Gelato alla Fragola di Tigule⟧??!?!", "Vorrei che facessero altri gusti di gelato oltre alla fragola, ma per fortuna la fragola è il mio preferito!", "Mmmmmmmmm! Adoro il loro gelato alla fragola! Se c'è una cosa che Tigule e Foror sanno fare, è il gelato!\n\nGrazie mille, {name}: è la merenda più buona di sempre!", 0xa1977492, 0xb0828d78, 0xd500c0de, 0xf1f00363, 0x51094ed8, "....." },
  [4841] = { "Pacificare i centauri", "Uccidi 12 Galak Scout, 10 Galak Wrangler e 6 Galak Windchaser, poi torna dal guardiacolli Longhorn al ⟦Freewind Post=Presidio di Ventolibero⟧.", "{name}, ti supplico di dare la caccia a questi centauri. Sentiranno l'ira della nostra vendetta. Attacca l'accampamento dei centauri a nord del ⟦Freewind Post=Presidio di Ventolibero⟧! Che l'ira guidi la tua mano!", "Su, {name}, so che non hai ancora ucciso la tua parte. Dà loro la caccia, e ti darò una ricompensa in segno di gratitudine.", "In segno di gratitudine, questo è per te, {name}.", 0x1d435eac, 0xb4351619, 0x27f17b09, 0x9319ff75, 0x8bb40c71, "....." },
  [4842] = { "Strane sorgenti", "Segui le istruzioni di Donova Snowden, poi torna a fare rapporto.", "A dirti la verità, anche se qui a ⟦Winterspring=Fontefredda⟧ non ci sono vulcani, credo che dietro queste sorgenti calde ci siano ragioni ben più minacciose...\n\nBeh, credo che vorrai vederlo con i tuoi occhi. Dovrai attraversare ⟦Winterspring=Fontefredda⟧ in tutta la sua lunghezza e spingerti fino all'estremo sud. Quando l'aria si farà pesante e afosa e il cielo si scurirà, avrai trovato quella che credo sia l'origine delle sorgenti calde.\n\nDai un'occhiata. Sono sicura che al tuo ritorno avrai molte domande.", "L'acqua delle sorgenti sembra avere proprietà molto strane... Non sono ancora sicura di cosa significhi...", "Sì, i demoni laggiù nella ⟦Darkwhisper Gorge=Gola di Mormoscuro⟧; credo sia la loro presenza a colpire così la regione. Continuerò a osservare le sorgenti calde qui e vedrò se scopro qualcos'altro.\n\nSe hai intenzione di addentrarti nella ⟦Darkwhisper Gorge=Gola di Mormoscuro⟧, al tuo posto aspetterei di essere un po' più forte.", 0x770638b8, 0x09ab8759, 0x266e3272, 0xbdd0d69c, 0xa72387b6, "....." },
  [4861] = { "Silvagufi infuriati", "Trova l'accampamento distrutto e i rifornimenti di Jaron Stoneshaper nel sud di ⟦Winterspring=Fontefredda⟧.", "Ehi, <ragazzo/ragazza>! Dei silvagufi assetati di sangue mi hanno cacciato dal mio accampamento nel sud di ⟦Winterspring=Fontefredda⟧! Be', immagino di essermi avvicinato troppo a qualcosa che i silvagufi custodivano.\n\nSono riuscito a malapena a mettermi in salvo; temo che un mio compare non sia stato altrettanto fortunato. Ti dispiacerebbe sfidare i silvagufi e andare all'accampamento? Ho davvero bisogno dei miei rifornimenti, e vorrei anche recuperare l'amuleto che ho dissotterrato ieri al sito di scavo.", nil, "Tra gli averi distrutti dell'accampamento spicca una cassa gravemente danneggiata...", 0x79149705, 0x7441f7b9, 0x028c9c59, nil, 0x0236ad18, "...m.", nil, nil, 0xda8a0008, nil, nil },
  [4862] = { nil, "Raggiungi i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e raccogli 15 Uovo del ⟦Spire Spider=Ragno dei Bastioni⟧ per Kibler.\n\nA quanto pare, queste uova si trovano vicino ai ragni.", "Che tu ci creda o no, c'è gente disposta a pagare per le bestie addomesticate più ripugnanti!\n\nAvevo mandato Bijou nei Bastioni a raccogliere qualche uovo di ragno dei Bastioni, ma non ho sue notizie da settimane. Forse puoi darmi una mano?\n\nFacciamo così, {name}. Va' ai ⟦Blackrock Spire=Bastioni di Roccianera⟧ e raccogli per me qualche uovo di ragno dei Bastioni. Riportameli qui e non solo ti darò un po' di soldi, ma te ne addomesticherò anche uno!", "Hai delle uova di ragno nello zaino o sei solo content<o/a> di vedermi?", "Che carico! Voglio dire, guarda quante uova! Mi frutteranno un bel po' d'oro.\n\nCome promesso, ecco la tua bestiola. Attent<o/a> che non ti morda!", 0xbe9d4fa6, 0xd87f13c1, 0xcb2f6b38, 0xa23da4b7, 0xa14c937e, "e...." },
  [4863] = { "Silvagufi infuriati", "Trova il carro distrutto di Jaron Stoneshaper.", "Guardandoti attorno, non vedi molto che possa servire a Jaron. Noti però che la cassa che hai trovato è stata sfondata, quasi come se fosse proprio questo ciò che cercavano i silvagufi...\n\nGuardando a est, riesci a malapena a distinguere un carro abbandonato. Forse lì troverai le cose di Jaron. Vale la pena dare un'occhiata.", nil, "Avvicinandoti al carro, non sembra che ci sia molto altro per Jaron. Guardando a terra, però, noti alcune casse che sembrano intatte, anche se mezze sepolte nella neve.", 0x79149705, 0xca1fe111, 0x3baac11d, nil, 0xbd4184d1, "...m." },
  [4864] = { "Silvagufi infuriati", "Raccogli i ⟦Jaron's Supplies=Rifornimenti di Jaron⟧ dalla neve, poi trova il silvagufo che ha rubato l'amuleto di cui ti ha parlato Jaron.\n\nPorta i ⟦Jaron's Supplies=Rifornimenti di Jaron⟧ e il Blue-feathered Amulet a ⟦Jaron Stoneshaper=Jaron Formapietre⟧, alla baita di ⟦Winterspring=Fontefredda⟧.", "Dopo aver esaminato il contenuto della cassa, decidi che gli attrezzi e gli altri oggetti al suo interno potrebbero tornare utili a Jaron. Dell'amuleto, però, non c'è traccia.\n\nSembra che i silvagufi abitino le terre a nord e a est di qui, quindi decidi che il passo successivo è affrontare le creature e riprendere loro l'amuleto.", "Già... Dammi le notizie.", "Be', me lo aspettavo, <ragazzo/ragazza>. Immaginavo che quelle bestie impazzite avessero distrutto tutti i miei averi...\n\nMa hai trovato i miei attrezzi e, soprattutto, l'amuleto! Chissà perché i silvagufi difendevano quest'oggetto con tanta ferocia... In ogni caso, ci penserò due volte prima di tornare da quelle parti!", 0x79149705, 0x4e5f6f02, 0x713e526e, 0x18bc5c8b, 0x775c972b, ".....", nil, nil, nil, nil, 0x41d708bc },
  [4865] = { "Serpente selvaggio", "Riferisci le tue scoperte a Motega Firemane.", "Se non l'avessi visto con i miei occhi non ci avrei mai creduto. La Vendetta è giunta a ⟦Thousand Needles=Millepicchi⟧!\n\n<Hagar si asciuga la fronte.>\n\n{name}, devi agire in fretta! Va' subito a cercare Motega Firemane; si trova all'⟦Whitereach Post=Accampamento di Manto Bianco⟧, appena a nord-ovest del ⟦Freewind Post=Presidio di Ventolibero⟧ lungo la strada. Lui saprà cosa fare!", nil, "La Vendetta! Dunque la leggenda di Arikara è vera. Questo è davvero un problema da risolvere immediatamente.", 0x612f028d, 0xc8e5a036, 0x7e5035fc, nil, 0x1fdaed2a, "...m." },
  [4866] = { "⟦Mother's Milk=Latte Materno⟧", "Nel cuore dei ⟦Blackrock Spire=Bastioni di Roccianera⟧ troverai ⟦Mother Smolderweb=Madre Bruciatela⟧. Affrontala e fatti avvelenare. È probabile che dovrai anche ucciderla. Quando sarai <avvelenato/avvelenata>, torna da ⟦Ragged John=John il Malconcio⟧, così potrà 'mungerti'.", "È probabilmente uno dei veleni più potenti al mondo, {race}!\n\nHo sentito i ⟦Blackrock=Roccianera⟧ parlare della sua letalità durante le mie scorribande nei Bastioni. Lo chiamano '⟦Mother's Milk=Latte Materno⟧', da ⟦Mother Smolderweb=Madre Bruciatela⟧, quel ragno enorme e schifoso della grotta di Skitterweb.\n\nEcco cosa mi serve da te: un campione vivo del Latte, che scorra nelle TUE vene. Portarmi solo la ghiandola non basterà! Fatti avvelenare da lei e torna da me!\n\nPoi... potrò mungerti!\n\n<Si sfrega le mani pregustando il momento.>", "<⟦Ragged John=John il Malconcio⟧ ti dà un pizzicotto.>", "Ne verrà fuori la birra migliore di sempre!\n\nEh, per cosa pensavi che l'avrei usato? Per un veleno o roba simile??\n\nRagazzi matti...", 0x92128101, 0x55e77086, 0x235114fa, 0x65d131a5, 0x3b930086, "....." },
  [4867] = { nil, "Leggi la ⟦Warosh's Scroll=Pergamena di Warosh⟧. Porta il ⟦Warosh's Mojo=Mojo di Warosh⟧ a Warosh.", "Argh! Così difficile parlare!\n\nPrendi questo biglietto! Riportami il mio mojo!", "Ah! Hai il mio mojo?", "Aha! Sento già i miei poteri tornare. E la mia mente non è più tormentata dalla maledizione di Urok.\n\nGrazie, {name}! L'umiltà è al di sotto di me, ma devo riconoscere il tuo aiuto.\n\nE ti auguro buona fortuna nel tuo viaggio attraverso i ⟦Blackrock Spire=Bastioni di Roccianera⟧. Sei sciocc<o/a> a pensare di poter arrivare in cima, ma il tuo coraggio è fuori discussione.", 0xf56d6e8c, 0x77f6dbd8, 0xe3f54a7e, 0xe79ceef2, 0xca23224d, "e...." },
  [4881] = { "Complotto omicida", "Avverti Kanati Greycloud, all'⟦Whitereach Post=Accampamento di Manto Bianco⟧, del complotto per ucciderlo.", "Il tauren Kanati Greycloud ha avuto l'ardire di piantare un accampamento di caccia a ⟦Thousand Needles=Millepicchi⟧. Dobbiamo ucciderlo per liberarci di questo accampamento e di tutti quelli che potrebbero seguirlo. Ci raduneremo al piccolo avamposto a sud-ovest del Grande Ascensore.", nil, "Vengono a uccidermi? Mostrerò loro come combatte un tauren!", 0xc85dbd6e, 0x9ca08705, 0x1c5ff84a, nil, 0x4f9dc751, "...m." },
  [4882] = { "A guardia dei segreti", "Porta il Blue-feathered Necklace a ⟦Trull Failbane=Trull Buonasorte⟧, all'⟦Bloodvenom Post=Accampamento di Sanguemarcio⟧.", "Non sai bene che importanza abbia la collana caduta dal collo del silvagufo appena ucciso. Brilla intensamente, affievolendosi e ravvivandosi piano.\n\nTrull Failbane potrebbe dirti di più, visto che sembra sapere molto sui silvagufi. Forse dovresti chiedere a lui.", "Sei qui per un altro incarico?", "Una scoperta importante?", 0xb324739d, 0x5378112c, 0x363bbfd4, 0x85113514, 0x06fa0b6f, "....." },
  [4883] = { "A guardia dei segreti", "Porta il Blue-feathered Necklace a ⟦Nara Wildmane=Nara Manto Selvaggio⟧.", "Pur sapendo molto sui silvagufi che hai sconfitto a ⟦Winterspring=Fontefredda⟧, non sono molto istruito in materia delle magie che usano. Credo però di conoscere qualcuno in grado di esaminare la collana e, con ogni probabilità, di dirti di cosa si tratta.\n\nNara Wildmane, a ⟦Thunder Bluff=Picco del Tuono⟧, è esperta in questo campo; va' da lei. Buona fortuna, {name}.", "Come posso aiutarti, {name}?", "L'energia di questa collana, {name}... Credo che abbia una sola fonte.\n\n<Nara chiude gli occhi e resta in silenzio per un momento.>\n\nI silvagufi, ora sviati e confusi, un tempo non erano così. Avevano uno scopo, ed erano guidati a servire. La dea degli elfi della notte, Elune, creò queste creature perché custodissero i suoi luoghi più sacri.\n\nQuesto fatto può sembrare di poco valore, ma ti esorto a guardare più a fondo.\n\nCapirai, col tempo. Grazie per avermela portata, {name}.", 0xb324739d, 0xb360f381, 0xc9511183, 0x12fea955, 0xfda5700f, "....." },
  [4901] = { "I guardiani dell'altare", "Proteggi Ranshalla mentre cerca di riattivare l'altare di Elune. Riferisci ciò che hai scoperto a ⟦Erelas Ambersky=Erelas Cieloambrato⟧, a ⟦Rut'theran Village=Rut'theran⟧.", "In cima alla cresta si trova quello che credo sia un altare della dea Elune. Da quel che posso capire, dobbiamo accendere le cinque torce, una in ogni grotta, e allora potremo accedere direttamente all'altare.\n\nHo trascritto alcune formule incise nella pietra delle antiche Rovine di Kel'Theril, che credo siano il segreto per sbloccare l'altare. Mi servirà il tuo aiuto per accendere ogni torcia mentre recito l'incantesimo.\n\nSe ci riusciremo, potrai riferire le nostre scoperte a Erelas!", nil, "Hai incontrato Ranshalla?", 0x9acf7bfb, 0xb5a7b357, 0xc65f04b8, nil, 0xf1e2455b, "...m." },
  [4902] = { "I silvagufi di Elune", "Parla con l'arcidruido Fandral Staghelm, a Darnassus.", "Affascinante!\n\nMi sono sempre chiesta quale fosse la verità... Be', devi assolutamente condividere quello che sai! Va' subito dall'arcidruido Fandral Staghelm: lo troverai a Darnassus, presso il ⟦Cenarion Circle=Circolo Cenariano⟧. Spiegagli cos'è successo, proprio come l'hai raccontato a me. Sono certa che gli interesserà altrettanto!\n\nÈ un'informazione importante, {name}!", nil, "Non esitare; dimmi perché sei venut<o/a>.\n\nAh, sì? Mmh. Be'.\n\nGrazie per averlo portato direttamente a me; è sempre meglio rivolgersi ai vertici... Però... Sì. I druidi del ⟦Cenarion Circle=Circolo Cenariano⟧ sanno dei silvagufi da tempo. Sanno che sono i prediletti di Elune, scelti per proteggere i luoghi più sacri.\n\nQuindi, anche se non è una novità, mi complimento davvero per il tuo impegno. Ecco, prendi questo: mi sembra adatto a un'impresa del genere.", 0x1fa3452e, 0xf466e7fe, 0xd56e78fc, nil, 0x14e16654, "...m." },
  [4903] = { "Gli ordini del signore della guerra", "Uccidi ⟦Highlord Omokk=Gran Signore Omokk⟧, ⟦War Master Voone=Maestro di Guerra Voone⟧ e ⟦Overlord Wyrmthalak=Supremo Dragthalak⟧. Recupera i ⟦Important Blackrock Documents=Documenti Importanti di Roccianera⟧. Torna dal signore della guerra Goretooth, a Kargath, quando avrai portato a termine la missione.", "Per ordine del signore della guerra Goretooth, i seguenti abitanti dei ⟦Blackrock Spire=Bastioni di Roccianera⟧ devono essere annientati:\n\nLa pingue minaccia, il gran signore Omokk.\n\nIl troll crudele e spietato, il maestro di guerra Voone.\n\nIl signore supremo Wyrmthalak, sorvegliante della città inferiore.\n\nDovrai inoltre riportare tutti i documenti importanti che dovessi trovare.\n\nRiesci e avrai onore.\n\nFallisci e cadrai nell'oblio.", "<Il signore della guerra Goretooth fa il saluto militare.>", "<La pelle verde e opaca del signore della guerra Goretooth diventa per un attimo bianca come il gesso.>", 0x74e9f805, 0xcfacba72, 0x1625864e, 0x31f0b738, 0x989eb15a, "....." },
  [4904] = { "Libera, finalmente", "Scorta Lakota Windsong fuori dal ⟦Darkcloud Pinnacle=Pinnacolo Nubenera⟧, poi parla con Thalia Amberhide al ⟦Freewind Post=Presidio di Ventolibero⟧.", "Arnak crede che ci sposeremo... ma dopo che ho rifiutato la sua proposta è tornato quella notte e mi ha rapita. Mio fratello ha cercato di fermarlo, ma Arnak era troppo forte. Lui... ha ucciso mio fratello e poi mi ha portata qui. Il mio povero fratello...\n\n{name}, puoi scortarmi fuori dal ⟦Darkcloud Pinnacle=Pinnacolo Nubenera⟧? Ti prego... devo tornare da Thalia! Sarà preoccupatissima per me.", nil, "Grazie, {name}. Nel profondo delle ossa sapevo che avrebbe ritrovato la strada per tornare da me. Mi ha raccontato del tuo coraggio e di come l'hai aiutata a fuggire. Queste cose appartenevano a suo fratello. So che vorrebbe che le avessi tu.", 0x1ba438b0, 0xcbafa782, 0xeb06eed1, nil, 0xf5fd9df3, "...m." },
  [4906] = { "Altra corruzione", "⟦Eridan Bluewind=Eridan Brezzastrale⟧, nel ⟦Felwood=Vilbosco⟧, vuole che tu uccida 8 Jadefire Hellcaller, 8 Jadefire Betrayer, 8 Jadefire Trickster e Xavaric. Torna da Eridan quando avrai finito.", "Un secondo accampamento di satiri minaccia la terra del ⟦Felwood=Vilbosco⟧ verso nord, guidato dal crudele Xavaric. Quei vili traditori e imbroglioni si nutrono della corruzione delle creature native del ⟦Felwood=Vilbosco⟧.\n\nXavathras e i suoi servitori erano solo parte di un piano più vasto: coltivare un pozzo lunare corrotto e poi consegnarne i frutti a Xavaric.\n\nOra che Xavathras è fuori dai giochi, porta a termine questo compito, {name}. Dirigiti a nord e sconfiggi Xavaric.", "Ti prego, poni fine alla sofferenza delle creature del Vilbosco.", "Grazie per tutto ciò che hai fatto, {name}. Che Elune ti protegga e ti guidi sul cammino che ti attende.", 0x55f5548e, 0x1ad6df81, 0x5c753791, 0x861c4d72, 0x12182e6d, "....." },
  [4907] = { nil, "Parla con ⟦Tinkee Steamboil=Tinkee Vapormarcio⟧.", "Ciao, {name}. Ti ricordi di ⟦Tinkee Steamboil=Tinkee Vapormarcio⟧? Be', lei si ricorda di te! Mi ha mandato un messaggio chiedendomi di tenere gli occhi aperti nel caso passassi di qui, perché... ha di nuovo bisogno del tuo aiuto. Credo che abbia a che fare con i suoi studi sui draghi.\n\nDovresti parlarle nelle ⟦Burning Steppes=Steppe Ardenti⟧, al ⟦Flame Crest=Cimiero Ardente⟧.", nil, "Felnok aveva ragione! Ho di nuovo bisogno del tuo aiuto, e stavolta... sarà davvero pericoloso.\n\nSei pront<o/a>??", 0xb0872af6, 0x9d39dc7b, 0x7bf6730e, nil, 0x2a394db3, "e..m." },
  [4921] = { "Dispersa in battaglia", "Trova la moglie di Mankrik, poi torna da lui al ⟦Crossroads=Crocevia⟧.", "Stavamo combattendo in un piccolo accampamento tauren quando ci hanno separati: lei da sola teneva a bada tre Mantotergo. Ma erano troppi per noi. Ne ho attirati via alcuni, solo per vederla sopraffatta dai nuovi arrivati. Accecato dalla rabbia mi sono voltato ad affrontare i nemici, ma col loro gran numero mi hanno abbattuto con facilità.\n\nMi sono risvegliato mentre un druido tauren curava le mie ferite: mi aveva trovato sulla ⟦Gold Road=Strada dell'Oro⟧, dove ero caduto.\n\nTi prego, {class}, trova qualche traccia di mia moglie.", "Hai trovato qualche traccia di lei? Il dolore nel petto mi dice che è successo il peggio, ma spero che tu la trovi sana e salva.", "Capisco. Grazie, {class}.", 0xac9b0a79, 0xf3b9fa6f, 0x129c3977, 0xa6107eba, 0xc0eb0cb6, "....." },
  [4941] = { "La saggezza di Eitrigg", "Parla con Eitrigg a Orgrimmar. Dopo aver discusso la faccenda con Eitrigg, chiedi consiglio a Thrall.\n\nRicordi di aver visto Eitrigg nella sala di Thrall.", "Rend è vivo?\n\nImpossibile!\n\nSi pensava che Rend fosse stato ucciso decenni fa.\n\nCerca la saggezza di Eitrigg, {name}. Nessuno conosce i ⟦Blackrock=Roccianera⟧ meglio di lui, e se ciò che è scritto qui è vero, Eitrigg deve esserne informato. A nessuno si dovrebbe negare il diritto alla vendetta.\n\nLo troverai a Orgrimmar.\n\nDopo aver parlato con Eitrigg, consulta il Capoguerra per sapere cosa intende fare riguardo a questo problema.", "Non vedi che non devo essere disturbato?", "<Thrall appare sgomento per le notizie che porti.>", 0x610a016f, 0x9f2039c3, 0xa6200170, 0x4cf1d215, 0x55dbcaa0, "....." },
  [4961] = { "La purificazione del Globo di Orahil", "Uccidi il ⟦Demon of the Orb=Demone del Globo⟧, poi parla con Tabetha.", "Ah, un globo da evocatore: è da qui che deve venire la corruzione. Dobbiamo esorcizzare il demone che vi è racchiuso, se vuoi usarlo. Questo posso farlo facilmente.\n\nIl compito difficile spetta a te. Dovrai uccidere il demone quando lo libererò.\n\nE dovrai essere rapid<o/a>. Se ci metti troppo, tornerà nel globo e dovremo ricominciare da capo!\n\nQuindi preparati, {name}. Tieni pronti gli incantesimi più potenti e le pozioni a portata di mano, e porta un amico, se ne hai uno. Perché non sarà uno spettacolo piacevole.", "Dovrai uccidere quel demone per cancellare per sempre la sua presenza dal globo, {name}.", "Ben fatto, {name}! Hai dato a quel demone una lezione che non dimenticherà presto. Hai dimostrato grande potere e abilità. Ora credo sia il momento di tornare da Menara con la tua sfera purificata, così potrai farne buon uso.\n\nBuona fortuna, {class}. Forse le nostre strade si incroceranno di nuovo.", 0xa2af51d8, 0x0c09dbd7, 0xef1d65ce, 0x2aeacd11, 0x36989af8, "....." },
  [4962] = { "Frammento di un vilsegugio", "Prendi il ⟦Felhas Ruby=Vil Rubino⟧ e usalo su uno dei Felhound in ⟦Desolace=Desolanda⟧. Una volta riuscit<o/a>, riporta il ⟦Felhas Ruby=Vil Rubino⟧ e lo ⟦Imprisoned Felhound Spirit=Spirito di Vilsegugio Imprigionato⟧ a ⟦Menara Voidrender=Menara Squarciavuoto⟧, nelle ⟦Barrens=Savane⟧.", "Dunque hai scelto di catturare l'anima di un vilsegugio. Bene.\n\nPrendi questo rubino: con esso potrai catturare l'anima della creatura. Funziona in modo molto simile a incantesimi che già conosci: quando la creatura è prossima alla morte, usa la gemma e farà il resto del lavoro per te.\n\nTi suggerisco di andare in ⟦Desolace=Desolanda⟧ e di metterti alla prova con uno dei vilsegugi che si trovano lì. Dovrebbero andare benissimo.\n\nQuando ci sarai riuscit<o/a>, porta sia lo spirito catturato sia il rubino a Menara.", "Sì, {name}? Hai scelto? Infernale o vilsegugio?\n\nOgni scelta è personale e dovrebbe rispecchiare i tuoi punti di forza e le tue debolezze. Non è raro che uno stregone preferisca potenziare ancora le proprie doti invece di compensare quelle che gli mancano. A volte sopraffare un nemico è una tattica efficace quanto diventare un incantatore più equilibrato.", "Ah, lo spirito di un vilsegugio. Ben fatto, {name}.\n\nQuando avrò sia lo spirito sia la sfera purificata, li fonderò per te, ma non prima.", 0xcac8654f, 0xdbee1707, 0x3d24b7b3, 0x90161bdb, 0x9222e0a7, "....." },
  [4963] = { "Frammento di un infernale", "Prendi lo ⟦Infus Emerald=Smeraldo Infuso⟧ e usalo su uno degli Infernal in ⟦Desolace=Desolanda⟧. Una volta riuscit<o/a>, riporta lo ⟦Infus Emerald=Smeraldo Infuso⟧ e lo ⟦Imprisoned Infernal Spirit=Spirito di Infernale Imprigionato⟧ a ⟦Menara Voidrender=Menara Squarciavuoto⟧, nelle ⟦Barrens=Savane⟧.", "Dunque hai scelto di catturare l'anima di un infernale. Bene.\n\nPrendi questo smeraldo: con esso potrai catturare l'anima della creatura. Funziona in modo molto simile a incantesimi che già conosci: quando la creatura è prossima alla morte, usa la gemma e farà il resto del lavoro per te.\n\nTi suggerisco di andare in ⟦Desolace=Desolanda⟧ e di metterti alla prova con uno degli infernali che si trovano lì. Dovrebbero andare benissimo.\n\nQuando ci sarai riuscit<o/a>, porta sia lo spirito catturato sia lo smeraldo a Menara.", "Sì, {name}? Hai scelto? Infernale o vilsegugio?\n\nOgni scelta è personale e dovrebbe rispecchiare i tuoi punti di forza e le tue debolezze. Non è raro che uno stregone preferisca potenziare ancora le proprie doti invece di compensare quelle che gli mancano. A volte sopraffare un nemico è una tattica efficace quanto diventare un incantatore più equilibrato.", "Ah, lo spirito di un infernale. Ben fatto, {name}.\n\nQuando avrò sia lo spirito sia la sfera purificata, li fonderò per te, ma non prima.", 0x99d101f6, 0xc9a4d7b1, 0x14f7176a, 0x90161bdb, 0x614e3e45, "....." },
  [4964] = { "Il ⟦Orb of Dar'Orahil=Globo di Dar'Orahil⟧ completato", "Aspetta che ⟦Menara Voidrender=Menara Squarciavuoto⟧ completi il ⟦Orb of Dar'Orahil=Globo di Dar'Orahil⟧, poi parlale di nuovo.", "Mi metterò subito al lavoro per forgiare il tuo globo e infondervi il tuo nuovo demone. Quando avrò finito, potrai scegliere se averlo in forma di bastone o di globo. Ho sempre ritenuto importante assecondare l'arma scelta da uno stregone... e non vedo motivo di abbandonare questa abitudine.", nil, "È fatto, {name}. Dimmi soltanto cosa preferisci: un bastone che richiede l'uso di entrambe le mani, o un globo che ti permetta di usare un pugnale o una spada come arma.\n\nAffrontare un vilsegugio è stata una grande impresa da parte tua. Di certo il tuo oggetto ti servirà bene in futuro. Continua a impegnarti nelle arti, {name}. Attenderò notizie delle tue gesta.", 0x0db266f4, 0xe3749851, 0x7c553bb6, nil, 0x34bb4f9e, "...m." },
  [4965] = { "La conoscenza del Globo di Orahil", "Parla con ⟦Menara Voidrender=Menara Squarciavuoto⟧ nelle ⟦Barrens=Savane⟧.", "Bene, bene, bene... che piacere vedere che il tuo potere cresce, {name}. Scommetto che saresti quasi pront<o/a> per parlare con ⟦Menara Voidrender=Menara Squarciavuoto⟧, nelle ⟦Barrens=Savane⟧. Se non ci hai mai parlato, lascia che te lo dica: non credo di aver mai conosciuto un'altra esperta nella creazione di oggetti (globi, in particolare) capaci di imprigionare persino un demone e piegarlo al nostro volere con tanta facilità.\n\nSe ti interessa, si trova nella torre di Strahad, sopra ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧.", nil, "Ah, cerchi davvero qualcosa di più... sostanzioso. In questo posso aiutarti, se sei davvero pront<o/a>.\n\nÈ un piacevole cambiamento vedere uno dei nostri cercare più potere in forme diverse dal semplice sapere.\n\nAllora, ti senti pront<o/a>, {name}?", 0x1e06a5bc, 0xdd3a1725, 0xded3c63b, nil, 0xc0e51e95, "...m." },
  [4966] = { "In difesa di Kanati Greycloud", "Proteggi Kanati Greycloud dall'attacco dei centauri.", "Ma i centauri potrebbero essere più di quanto pensassi; ti chiedo, {name}, di combattere al mio fianco contro questi vili assassini.", nil, "Grazie per l'aiuto, {name}. Senza di te non ce l'avrei fatta a respingerli.", 0x87ee9084, 0xb8578399, 0x907deac5, nil, 0xfb6cc9e7, "...m." },
  [4967] = { "La conoscenza del Globo di Orahil", "Parla con ⟦Menara Voidrender=Menara Squarciavuoto⟧ nelle ⟦Barrens=Savane⟧.", "Ancora <uno/una> sciocc<o/a>, e ancora in cerca dei fronzoli dei mortali. Sì, ti parlo con arroganza. Ti vedo davanti a me e rido. Sei patetic<o/a>!\n\nMa non importa cosa penso io. Importa solo cosa pensano quelli disposti a trattare con te! E in questo caso, contro il mio parere, quelli che hanno un po' di potere ritengono che tu meriti di più.\n\nSe è questo che cerchi, dovresti parlare con ⟦Menara Voidrender=Menara Squarciavuoto⟧ nella torre sopra ⟦Ratchet=Porto Paranco⟧. Credo che tu l'abbia già incontrata tempo fa.", nil, "Ah, cerchi davvero qualcosa di più... sostanzioso. In questo posso aiutarti, se sei davvero pront<o/a>.\n\nÈ un piacevole cambiamento vedere uno dei nostri cercare più potere in forme diverse dal semplice sapere.\n\nAllora, ti senti pront<o/a>, {name}?", 0x1e06a5bc, 0xdd3a1725, 0xabcb7e15, nil, 0xc0e51e95, "...m." },
  [4968] = { "La conoscenza del Globo di Orahil", "Parla con ⟦Menara Voidrender=Menara Squarciavuoto⟧ nelle ⟦Barrens=Savane⟧.", "Mmh, sei arrivat<o/a> fin qui... davvero sorprendente. Avrei pensato che la corruzione dell'incanalare l'arcano ti fosse già penetrata fin nell'anima, facendoti impazzire. Che ne dici di spingerti ancora più in là?\n\nSe vuoi mettere alla prova la tua abilità, cerca ⟦Menara Voidrender=Menara Squarciavuoto⟧ sopra ⟦Ratchet=Porto Paranco⟧, nella torre di Strahad. Ti guiderà lei.", nil, "Ah, cerchi davvero qualcosa di più... sostanzioso. In questo posso aiutarti, se sei davvero pront<o/a>.\n\nÈ un piacevole cambiamento vedere uno dei nostri cercare più potere in forme diverse dal semplice sapere.\n\nAllora, ti senti pront<o/a>, {name}?", 0x1e06a5bc, 0xdd3a1725, 0x4b72c193, nil, 0xc0e51e95, "...m." },
  [4969] = { "La conoscenza del Globo di Orahil", "Parla con ⟦Menara Voidrender=Menara Squarciavuoto⟧ nelle ⟦Barrens=Savane⟧.", "Ah ah! Te la stai cavando proprio bene, giovane {class}.\n\nCol tempo, infernali e signori del terrore si inchineranno davanti a te!\n\nMa finché quel momento non arriverà, dovrai ancora affidarti ad armi forgiate dalle mani delle razze mortali.\n\nSembri pront<o/a> per un'altra di queste creazioni, e se lo desideri, ⟦Menara Voidrender=Menara Squarciavuoto⟧ vorrebbe parlarti! Si trova vicino alla torre di Strahad che domina la città portuale di ⟦Ratchet=Porto Paranco⟧. Va' da lei quando sei pront<o/a>.", nil, "Ah, cerchi davvero qualcosa di più... sostanzioso. Posso aiutarti, se sei davvero pront<o/a>.\n\nÈ un piacevole cambiamento vedere uno dei nostri cercare più potere in forme diverse dal semplice sapere.\n\nAllora, ti senti pront<o/a>, {name}?", 0x1e06a5bc, 0xdd3a1725, 0x4438376e, nil, 0x5ab9669e, "...m." },
  [4971] = { "Una questione di tempo", "Usa il ⟦Temporal Displacer=Distorsore Temporale⟧ vicino a uno dei silos di Andorhal e fai uscire allo scoperto i Temporal Parasite.\n\nUccidi 15 Temporal Parasite, poi riporta il ⟦Temporal Displacer=Distorsore Temporale⟧ a ⟦Chromie=Cromie⟧, nella locanda di Andorhal, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Una forza sinistra, quasi certamente il Flagello, ha manomesso il corso del tempo ad Andorhal! Posso tentare di preservare lo scorrere del tempo qui e riparare ciò che è stato danneggiato, ma mi serve il tuo aiuto per farlo senza interruzioni.\n\nI parassiti temporali, sciacalli che si nutrono dei fili del flusso alterato del tempo, ora infestano i silos di Andorhal. Un impulso blu di distorsione è l'unico segno visibile della loro presenza. Rallentano i miei auspici; ti prego, {name}, aiutami: usa questo distorsore temporale per stanare quei parassiti.", "I parassiti temporali sono un male comune ovunque il flusso del tempo sia stato manomesso. Ne avverto molti, e questo è preoccupante.\n\nStanare tutti quelli che riesci a trovare mi aiuterà a riprendere meglio il controllo della situazione temporale che qui si sta deteriorando. Saprò quando ci sarai riuscit<o/a>.", "Ora il tempo sembra più facile da riparare, grazie, {name}. Anche se forse non comprendi appieno le conseguenze di una linea temporale spezzata, apprezzo che tu capisca l'urgenza di contrastare quello che sospetto sempre più sia un misfatto ordito dal Flagello.\n\nNon vedo nulla di male nel ricompensarti per il tuo aiuto, mortale. Le tue imprese più grandi devono ancora venire, e ricevere un gingillo non cambierà certo il tuo destino. Il tuo aiuto costante, però, è qualcosa di cui io e lo stormo potremmo avere bisogno...", 0xe492e2f3, 0x83d594de, 0xdbab402f, 0x948b7dfe, 0x170199d3, "....." },
  [4972] = { "Il conto del tempo", "Trova 5 Orologio di Andorhal, chiusi nei forzieri tra le macerie della città. Portali a ⟦Chromie=Cromie⟧, nella locanda di Andorhal, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Ho bisogno che tu agisca nel mondo oltre questa stanza, {name}. Lascia che ti spieghi.\n\nVedi quanto questa stanza è diversa dal resto di Andorhal. Il mio stormo opera in molti modi diversi e in molte linee temporali diverse. Per riparare i danni di Andorhal, ora agisco da un'altra linea temporale, così da non contaminarla troppo. Per continuare, però, mi servono dei ninnoli del tempo, rimasti intrappolati da quando arrivò la piaga. Li troverai nei forzieri dentro gli edifici in rovina di quella che un tempo fu una città fiera.", "I ninnoli del tempo che cerco sono congegni semplici. Sono per lo più orologi, con le lancette ferme per sempre al momento in cui la piaga devastò Andorhal.\n\nIl tempo non finisce mai, e gli orologi che mi porterai finiranno inevitabilmente per tornare, contati, alle loro case... almeno finché qui continueranno i disturbi.", "Sono proprio ciò che mi serve, {name}. Grazie.\n\nPermettimi di ricompensarti come si deve con questo. Forse non capirai a cosa ti possa servire un congegno simile. Forse non sai nemmeno bene che cosa sia davvero. Purtroppo non posso dirti quando ti sarà più utile; sappi solo che, a un certo punto del futuro, consumarlo potrebbe rivelarsi estremamente utile e funzionale. Che tu decida di conservarlo fino ad allora o no... questo, amico mio, sta a te.", 0x5df1aeae, 0x5e72ad1f, 0x7f49c2ea, 0xbfad7074, 0x4441cc2e, "....." },
  [4974] = { "Per l'⟦Horde=Orda⟧!", "Raggiungi i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e uccidi ⟦Warchief Rend Blackhand=Capoguerra Rend Manonera⟧. Prendi la sua testa e torna a Orgrimmar.", "Rend osa avanzare pretese così grandi grazie alla protezione che gli offre lo Stormo dei Draghi Neri.\n\nTu, {name}, troverai un modo per attraversare le Halls of Ascension. Poi troverai il 'Capoguerra' Rend Blackhand e lo distruggerai: PER L'ORDA!\n\n<Thrall batte un pugno sul trono.>\n\nLa prossima volta che tornerai nelle mie stanze, terrai alta la sua testa in trionfo e la presenterai al tuo Capoguerra. Fallo e sarai onorat<o/a> come eroe dell'⟦Horde=Orda⟧.", "<Thrall grugnisce.>", "Hai inferto un colpo devastante alle forze dei ⟦Blackrock=Roccianera⟧, {name}. Con il loro Capoguerra ucciso, la legione dei ⟦Blackrock=Roccianera⟧ è di nuovo gettata nelle fauci del caos.\n\nIn onore delle tue gesta eroiche, il popolo di Kalimdor sarà ricompensato!", 0xcbedc0b0, 0xe788cadb, 0x91a3ffba, 0x51810db7, 0xe9f6f7cd, "....." },
  [4975] = { "Il ⟦Orb of Noh'Orahil=Globo di Noh'Orahil⟧ completato", "Aspetta che ⟦Menara Voidrender=Menara Squarciavuoto⟧ completi il ⟦Orb of Noh'Orahil=Globo di Noh'Orahil⟧, poi parlale di nuovo.", "Mi metterò subito al lavoro per forgiare il tuo globo e infondervi il tuo nuovo demone. Quando avrò finito, potrai scegliere se averlo in forma di bastone o di globo. Ho sempre ritenuto importante assecondare l'arma scelta da uno stregone... e non vedo motivo di abbandonare questa abitudine.", nil, "È fatto, {name}. Dimmi soltanto cosa preferisci: un bastone che richiede l'uso di entrambe le mani, o un globo che ti permetta di usare un pugnale o una spada come arma.\n\nAffrontare l'infernale è stata una grande impresa da parte tua, e questa ricompensa ti si addice. Ti auguro altri successi nelle arti, {name}.", 0x2893fd72, 0xa83dbe16, 0x7c553bb6, nil, 0xa7b51784, "...m." },
  [4976] = { "La restituzione della sfera purificata", "Riporta la ⟦Cleansed Infernal Orb=Sfera Infernale Purificata⟧ a ⟦Menara Voidrender=Menara Squarciavuoto⟧, nelle ⟦Barrens=Savane⟧.", "Riporta la sfera purificata a Menara, a ⟦Ratchet=Porto Paranco⟧, {name}. Portale i miei saluti e sta' attent<o/a>. Spero davvero che saprai resistere alla tentazione e alla corruzione che di certo incontrerai lungo il tuo cammino.\n\nBuona fortuna.", "Come procede la ricerca di Tabetha e del globo, {name}?\n\nTabetha si è dimostrata più che utile nelle questioni arcane. Di certo non avrà problemi ad aiutarti, se riuscirai a trovarla.", "Ben fatto, {name}. Questa andrà benissimo.\n\nNon ti resta che decidere quale demone vuoi che imprigioni nella sfera purificata. Fallo, e avrai un magnifico nuovo oggetto da impugnare.", 0xa1f2e73c, 0x4d497ee2, 0x7b21dd71, 0x3e294480, 0x638e5fcd, "....." },
  [4981] = { "L'agente Bijou", "Raggiungi i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e scopri che fine ha fatto Bijou.", "Mai fidarsi di un goblin. Alla fine si riduce tutto a questo, {name}.\n\nSi chiama Bijou: una delle nostre agenti più sfuggenti. Ho scoperto che lavorava per un losco commerciante di animali esotici delle ⟦Burning Steppes=Steppe Ardenti⟧ di nome Kibler; in pratica, faceva il doppio gioco. Peggio ancora, usava i fondi dell'⟦Horde=Orda⟧ per finanziare le sue operazioni.\n\nLa voglio qui viva.\n\nL'ultima volta è stata vista entrare nei ⟦Blackrock Spire=Bastioni di Roccianera⟧. Trovala e riportala qui.\n\nE, {name}, non farti incantare dalle sue moine.", nil, "Non ti mentirò, {race}. Mi servivano i soldi! Kibler paga molto, molto bene: molto meglio di quanto la K.E.F. potrebbe mai fare.\n\nMa non dubitare della mia lealtà! Perché credi che sia quaggiù? Per procurare a quel goblin pazzo qualche uovo di animale esotico o un'altra sciocchezza del genere? No, solo un vero idiota verrebbe ai ⟦Blackrock Spire=Bastioni di Roccianera⟧ a raccogliere animaletti. Già, non credo che al mondo esista molta gente così.\n\n<Bijou ride.>\n\nL'ultima cosa che ci serve è che gente del genere si riproduca.", 0xe4e02c06, 0x1c554da3, 0x1a593ac0, nil, 0x28659457, "...m." },
  [4982] = { "⟦Bijou's Belongings=Beni di Bijou⟧", "Trova i ⟦Bijou's Belongings=Beni di Bijou⟧ e riportaglieli. Ricordi che ti ha detto di averli nascosti al piano più basso della città.", "Di notte, quando questo posto è poco sorvegliato, mi aggiro furtiva per la città, prendo appunti e annoto tutto ciò che vedo e che potrebbe avere un valore strategico per la K.E.F.\n\nIeri notte, però, le cose sono andate malissimo. Sono inciampata in un filo teso e ho fatto scattare un allarme. Ho nascosto la mia attrezzatura da ricognizione e sono corsa al riparo! Purtroppo non riesco a tornare a prenderla. Hanno raddoppiato, anzi triplicato le pattuglie! Tutte quelle informazioni sono perdute.\n\nRecupera le mie cose e tornerò dalla K.E.F. senza fare storie.", "Fortuna?", "Ce l'hai fatta! Quando Lexlort avrà questi piani, si dimenticherà di tutte le cattiverie che voleva farmi.\n\n{name}, sei <il/la> mi<o/a> <eroe/eroina>!", 0xb62123b7, 0x33b105fa, 0x3bb799a8, 0x87e6d3ba, 0xf03858c8, "....." },
  [4983] = { "⟦Bijou's Reconnaissance Report=Rapporto di Ricognizione di Bijou⟧", "Riporta il ⟦Bijou's Reconnaissance Report=Rapporto di Ricognizione di Bijou⟧ al gran maestro Lexlort, a Kargath.", "Riporta questo rapporto a Lexlort. Riscatterà il mio buon nome e darà di sicuro alla K.E.F. un vantaggio strategico nell'affrontare questi orchi.\n\nVenire con te? Ho davvero troppo lavoro da fare. Muoviti, quei rapporti gli servono il prima possibile!", "Dov'è la goblin???", "Devo riconoscerglielo: è riuscita a sgusciare fuori da un'altra situazione spinosa! Questi rapporti si riveleranno preziosissimi nei nostri rapporti con gli orchi ⟦Blackrock=Roccianera⟧.\n\nNaturalmente sarai ricompensat<o/a> per il tuo duro lavoro.", 0x25549b86, 0xc495008b, 0x20efa83e, 0xd4a96813, 0x4492c5db, "....." },
  [4984] = { "Anche gli animali soffrono", "Distruggi 8 Diseased Wolves, poi torna da ⟦Mulgris Deepriver=Mulgris Fiume Nero⟧ al Campo Putrido, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "Anche se da solo potevo fare ben poco per ostacolare il Flagello, sono comunque venuto in queste terre per cercare di sanare i danni inflitti alla natura. Gli animali soffrono per la pestilenza che continua a soffocare queste terre, senza trovare pietà né pace. Ti chiedo di continuare ciò che io non ho potuto finire.\n\nNon c'è salvezza per gli animali sofferenti se non una dolce e pietosa liberazione. Cerca i lupi malati qui vicino e abbattili. Ti prego, {name}, poni fine alla loro sofferenza: farlo darà di certo sollievo alla mia.", "I lupi infettati dalla pestilenza vanno abbattuti, {name}. Il morbo che portano non si può curare. Ci ho provato... ci ho provato finché la pestilenza non ha preso anche me.", "Io... sento che le anime dei lupi che hai abbattuto ora riposano in pace. Loro, e io con loro, ti ringraziano per la pietosa liberazione.\n\nI lupi non sono i soli a soffrire in questo luogo maledetto, {name}. Ti prego, ho di nuovo bisogno di te.", 0x63c3b4ce, 0xa188bdce, 0xea977f5e, 0x0e50456b, 0xe07aafd7, "....." },
  [4985] = { "Anche gli animali soffrono", "Abbatti 8 Diseased Grizzly, poi torna da ⟦Mulgris Deepriver=Mulgris Fiume Nero⟧ al Campo Putrido, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "A est di qui, vicino al confine con le ⟦Eastern Plaguelands=Terre Infette Orientali⟧, un tempo vagavano per le campagne grizzly fieri e maestosi. La piaga scatenata dal Flagello ha devastato anche queste bestie. Vagano per le campagne, tormentate dall'irrigidirsi dei muscoli e dal marcire del pelo e della carne.\n\nTi chiedo di porre fine anche alla loro sofferenza. L'unica cura per il loro tormento è una morte rapida, e deve venire dalla tua mano.", "Sento i tuoi passi, {name}. La vista mi ha abbandonato, ma riesco ancora a percepire ciò che mi circonda. Hai posto fine alla sofferenza dei grizzly malati?", "«So che i grizzly sono stati abbattuti e che il loro tormento è finito. Io... ho un'ultima cosa per te. L'ho scritta su... su questo ramo, sentendo che il mio tempo in questo mondo era giunto al termine.\n\nE infatti... sono giunto alla fine. Grazie ancora, amico... le creature di questa terra maledetta possono riposare... e ora riposerò anch'io.»\n\nDetto questo, il druido emette un pesante sospiro, seguito da quello che sembra un rantolo di morte. Il suo corpo giace immobile sul pavimento della capanna.", 0x63c3b4ce, 0x98858541, 0xc9e58228, 0xf2b7d5ee, 0x8c93a7a9, "....." },
  [4986] = { "⟦Glyphed Oaken Branch=Ramo di Quercia con Glifi⟧", "Stando alla magia infusa nel ⟦Glyphed Oaken Branch=Ramo di Quercia con Glifi⟧, il passo successivo voluto dal druido tauren è consegnarlo al ⟦Cenarion Circle=Circolo Cenariano⟧ a Darnassus. Cerca l'aiuto di uno dei druidi che vi si trovano.", "La mano senza vita del druido tauren stringe un ramo di quercia dall'aspetto sorprendentemente sano. Esaminandolo, scopri dei glifi di natura druidica incisi nella corteccia.\n\nQuando afferri il ramo, ti accorgi che è caldo al tatto, più di quanto dovrebbe. Ti si forma in mente l'immagine dell'albero di Teldrassil, e di Darnassus in particolare, e hai sulla punta della lingua le parole «⟦Cenarion Circle=Circolo Cenariano⟧». Sembra che nel ramo sia stata racchiusa l'indicazione di dove portarlo.", "A nome del ⟦Cenarion Circle=Circolo Cenariano⟧ ti do il benvenuto in questa enclave, {class}. Cosa ti porta da noi?", "Questo... questo è piuttosto strano. Questo druido, e per giunta un druido tauren, ti ha affidato moltissime informazioni preziose sulla portata della piaga del Flagello. Mi sorprende che un tauren abbia dato informazioni simili a <un/una> {race}, e per di più spontaneamente, se ciò che dici è vero. Ne faremo buon uso, te lo prometto. Forse i tauren non si sono allontanati da Cenarius quanto crede Fandral...\n\nEhm, comunque, ti prego: accetta questo in segno di gratitudine da parte del ⟦Cenarion Circle=Circolo Cenariano⟧.", 0xc8244b3c, 0x2bab27cf, 0x7b819468, 0x675f6520, 0xdf30dbc2, "....." },
  [4987] = { "⟦Glyphed Oaken Branch=Ramo di Quercia con Glifi⟧", "Stando alla magia infusa nel ⟦Glyphed Oaken Branch=Ramo di Quercia con Glifi⟧, il passo successivo voluto dal druido tauren è consegnarlo al ⟦Cenarion Circle=Circolo Cenariano⟧ a ⟦Thunder Bluff=Picco del Tuono⟧. Cerca l'aiuto di uno dei druidi che vi si trovano.", "La mano senza vita del druido tauren stringe un ramo di quercia dall'aspetto sorprendentemente sano. Esaminandolo, scopri dei glifi di natura druidica incisi nella corteccia.\n\nQuando afferri il ramo, ti accorgi che è caldo al tatto, più di quanto dovrebbe. Ti si forma in mente l'immagine di ⟦Thunder Bluff=Picco del Tuono⟧, a Mulgore, e dell'⟦Elder Rise=Altura degli Anziani⟧ in particolare, e hai sulla punta della lingua le parole «⟦Cenarion Circle=Circolo Cenariano⟧». Sembra che nel ramo sia stata racchiusa l'indicazione di dove portarlo.", "A nome del ⟦Cenarion Circle=Circolo Cenariano⟧ ti do il benvenuto in questa enclave, {class}. Cosa ti porta da noi?", "Questo viene da Mulgris, dici? Avevamo saputo che voleva prendersi cura delle creature che soffrono nelle ⟦Plaguelands=Terre Infette⟧, ma questo è del tutto inaspettato... e molto triste. Mulgris è... era un buon amico. Piangerò profondamente la sua scomparsa.\n\nI suoi sforzi non sono stati vani, grazie alla tua diligenza. In questo ramo sono custodite molte conoscenze sulla piaga che il Flagello diffonde per queste terre. Le studieremo con cura. Quanto a te, accetta questo, ti prego. È il minimo che possiamo fare per il tuo nobile impegno.", 0xc8244b3c, 0x364df13d, 0x2cc00fb4, 0x675f6520, 0x49acd227, "....." },
})
